INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wpy6w', 'wpy6w', 'Gestão universitária em foco: desafios contemporâneos na Universidade Estadual de Feira de Santana – UEFS', 'desafios contemporâneos na Universidade Estadual de Feira de Santana – UEFS', '["Antônio de Macêdo Mota Júnior"]', 'Figshare', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro foca no arranjo político-institucional da Universidade Estadual de Feira de Santana (UEFS) — uma instituição pública presente no interior do estado da Bahia — e o seu enfrentamento a desafios contemporâneos da gestão universitária. Deste modo, explora a compreensão do campo teórico da gestão universitária no Brasil, interpretando e analisando alguns desafios na contemporaneidade, em função do seu impacto no arranjo político-institucional dessa instituição. Para tanto, apresenta os resultados de uma pesquisa social aplicada a partir das dimensões políticas (democratização do acesso, permanência estudantil), organizacional (processo decisório colegiado), cultural (relevância social e econômica) e sustentabilidade financeira, trazendo importantes contribuições para esse campo científico.', '["university administration","Universidade Estadual de Feira de Santana","democratization of access","student retention","collegial decision-making","social relevance of universities","financial sustainability","public universities","Bahia"]', '10.7476/9788555921612', '9786589524694', 'https://books.scielo.org/id/wpy6w', NULL, NULL, 'https://books.scielo.org/id/wpy6w/cover/cover_thumbnail.jpeg', 375, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wqffx', 'wqffx', 'Saúde e Povos Indígenas', NULL, '["Ricardo Ventura Santos","Carlos Ε. A. Coimbra"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1994, '1994-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'ApresentaçãoEnglobando dimensões biológicas, culturais e sociais, a saúde e a doença são processos que dizem respeito a todas as sociedades humanas.Este livro propõe-se a contribuir ao melhor entendimento acerca do intercruzamento destas dimensões, tendo como campo de reflexão as sociedades indígenas brasileiras.Trata-se de uma coletânea que tem por objetivo apresentar a pluralidade teórica-metodológica que atualmente caracteriza os estudos acerca do processo saúde/doença nestas sociedades.Em sua concepção e conteúdo, o livro situa-se (ainda que não unicamente) no campo da antropologia, disciplina cuja tradição de pesquisa em sociedades indígenas brasileiras é longa e frutífera.No tocante à saúde e à doença, as pesquisas antropológicas entre estas sociedades caracterizam-se por sua diversidade, indo desde aquelas mais centradas na dinâmica epidemiológica até outras com maior enfoque em aspectos culturais.Este livro procura registrar esta saudável heterogeneidade.Na seleção dos trabalhos, partiu-se da premissa que, para um entendimento adequado do processo saúde/doença nas sociedades indígenas, é preciso levar em consideração não somente os aspectos bioecológicos que regulam a relação parasita-hospedeiro, por um lado, como também os fatores culturais envolvidos na escolha dos itinerários terapêuticos, por outro.Ao nosso ver, estas questões, assim como diversas outras, são passíveis de serem abordadas por meio de um enfoque antropológico.Devemos ressaltar que a pluralidade aqui manifesta vai além de uma tentativa de holismo e interdisciplinaridade, expressões que ocupam um locus diferenciado no discurso científico contemporâneo.No estudo do processo saúde/doença em sociedades indígenas, ela é absolutamente essencial.Assim, o livro inclui contribuições de autores identificados com vertentes tão diversas como a antropologia biológica, a antropologia ecológica e a antropologia médica.O diálogo entre estas subáreas da antropologia não tem sido freqüente, muito menos fácil, nestes tempos de crescente especialização das maneiras de compreender a diversidade biológica e cultural das sociedades humanas.As contribuições desta coletânea demonstram, ao nosso ver, que a dicotomia comumente observada entre perspectivas de cunho simbólico e materialista, só para citar duas vertentes, não se sustenta no tocante aos estudos sobre o processo saúde/doença das populações indígenas.Por se tratar de um campo eminentemente multifacetado, aparatos teórico-metodológicos diversos são necessários para tornar clara sua complexidade.Nosso intuito aqui não é o de proceder ã uma revisão da literatura sobre o processo saúde/doença das populações indígenas do Brasil.Da maneira como o entendemos, trata-se de um campo muito extenso que, no presente, conta com uma bibliografia especializada cujo domínio, arriscaríamos dizer, está possivelmente além da capacidade de síntese de investigadores individuais.É importante, contudo, explicitar as dimensões que interligam as diversas contribuições, das quais duas são particularmente evidentes.Primeiro, os autores estão primariamente interessados em sociedades experimentando acelerados e profundos processos de transformação.Historicidade e processualismo são aspectos que emergem repetidamente, de forma menos ou mais explícita, nos diversos capítulos.Como pano de fundo, têm-se as sociedades indígenas inseridas em contextos socioeconômico-culturais nos quais a negociação em torno dos significados e práticas relativos à saúde e à doença é intensa.Segundo, tomadas em seu conjunto, as contribuições demonstram que os impactos das mudanças sobre a dinâmica do processo saúde/doença inscrevem-se nas várias dimensões da realidade social e biológica dos povos indígenas, incluindo seus genes, seus ossos, seus corpos, suas construções culturais, suas narrativas, seus arranjos sociais e assim por diante.Ou seja, é razoável argumentar que temos unicidade no que diz respeito ao processo sob análise (saúde/doença em sociedades experimentando rápida transformação) e complementariedade no que tange aos níveis de análise (biologia, cultura e sociedade).Há um terceiro e igualmente importante elo de ligação: diversas contribuições apontam que, para se prover uma assistência à saúde para as sociedades indígenas consonante com suas construções e práticas relativas ao processo saúde/doença, é essencial compreender seus sistemas de crenças e práticas médicas.A primeira parte (Saúde e Doença na Pré-História e Contato) traz contribuições que exploram tópicos como a paleopatologia, a interface entre epidemiologia e dinâmica demográfica e as inter-relações entre variabilidade biológica e os impactos de epidemias de doenças infecto-parasitárias. O atual perfil epidemiológico das populações indígenas resulta de uma longa experiência de contato com patógenos, sejam eles autóctones ou introduzidos.Em seu conjunto, os capítulos desta seção provêm um panorama diacrônico do processo saúde/doença, permitindo avaliar como têm sido suas respostas biológicas e culturais frente às epidemias ao longo do tempo.Sheila Mendonça de Souza, Adauto Araújo e Luiz Fernando Ferreira revêem os estudos em paleopatologia de populações indígenas brasileiras.Este é um campo de pesquisa que procura gerar informações sobre o processo saúde/doença a partir da análise de remanescentes biológicos humanos usualmente recuperados em escavações arqueológicas e a partir da análise de documentos históricos.Os autores apontam que a paleopatologia ainda é pouco desenvolvida no Brasil, o que decorre da falta de tradição acadêmica e da existência de poucas coleções em condições apropriadas para análises paleopatológicas mais aprofundadas, dentre outros fatores.A despeito destas limitações, como bem demonstram os autores, através da paleopatologia já tem sido possível identificar a presença de patologias específicas nas populações indígenas na pré-história.O capítulo de Carlos Coimbra Jr. & Ricardo Santos mostra como um enfoque comparado pode ser útil para entender os diferentes perfis epidemiológicos das parasitoses entre as populações indígenas sulamericanas, tomando como exemplo a doença de Chagas.A partir da análise dos fatores ecológicos e comportamentais envolvidos na transmissão desta zoonose, os autores procuram explicar o porquê da doença de Chagas ser endêmica entre as populações indígenas andinas desde longa data, o que não ocorre entre as amazônicas.Argumenta-se que a elevada mobilidade e a ausência de animais domésticos, potencialmente reservatórios do parasita em nível domicilar, seriam as razões pelas quais a doença não se tornou endêmica entre os grupos indígenas da Amazônia.Francis Black analisa uma questão de interesse central: como explicar os elevadíssimos níveis de mortalidade experimentados pelas populações indígenas devido às epidemias associadas ao contato?A partir de uma revisão da literatura, o autor argumenta que a hipótese de colapso das atividades de subsistência e crise social devido ao adoecer simultâneo da maioria da população é insuficiente para explicar a elevada letalidade.Segundo Black, há possivelmente um componente biológico importante envolvido no processo, qual seja, um acentuado nível de homogeneidade genética das populações indígenas que se traduziria numa menor capacidade (em nível populacional e comparado às sociedades não-indígenas) de responder imunologicamente às infecções.A segunda seção (Sistema de Crenças e Práticas Médicas) é composta por quatro contribuições centradas na etnomedicina.Menos interessados na descrição de práticas de cura e rituais xamanísticos, os autores demonstram como a saúde e a doença, assim como as representações acerca destes processos, constitui-se em uma arena de intensa negociação de significados e práticas.Trata-se, portanto, de um espaço privilegiado para analisar relações de poder.Além da relevância teórica, os autores chamam atenção para o fato de que, efetivamente, torna-se necessário enfocar os sistemas médicos tradicionais se o intuito', '["health and disease","indigenous peoples of Brazil","Indigenous health","physical anthropology","ecological anthropology","medical anthropology","parasitology","host-parasite interactions","therapeutic itinerary","holistic approach","interdisciplinarity","epidemiology"]', '10.7476/9788575412770', '9788575412770', 'https://books.scielo.org/id/wqffx', 'https://books.scielo.org/id/wqffx/pdf/santos-9788575412770.pdf', NULL, 'https://books.scielo.org/id/wqffx/cover/cover_thumbnail.jpeg', NULL, 31, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wrdxb', 'wrdxb', 'Conflictos indígenas ante la justicia colonial: los hilos entrelazados de una compleja trama social y legal, siglos XVI-XVII', NULL, '["Héctor Manuel Cuevas Arenas"]', 'Editorial Universidad Santiago de Cali', 'Colombia', 'SciELO Books', 'books', 2020, '2020-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este texto compilatorio recoge distintas investigaciones que giran en torno a la relación entre los pueblos indígenas con la corona hispánica en el periodo colonial. A través de distintos estudios de caso en los niveles locales y regionales, estos escritos indagan sobre problemas tales como la agencia histórica y social indígena, la hegemonía del poder político y las estrategias de los actores para afrontar los desafíos de su vida particular y colectiva. La justicia, el orden social y los conflictos son los marcos de estas historias entrelazadas, que contribuyen a una comprensión más específica y problemática sobre dichos pasados en la América Hispánica.', '["indigenous peoples","colonial justice","indigenous conflict","Spanish colonialism","indigenous agency","political hegemony","social order","colonial America","16th-17th centuries","legal history"]', '10.7476/9786287501676', '9789585147607', 'https://books.scielo.org/id/wrdxb', 'https://books.scielo.org/id/wrdxb/pdf/cuevas-9786287501676.pdf', 'https://books.scielo.org/id/wrdxb/epub/cuevas-9786287501676.epub', 'https://books.scielo.org/id/wrdxb/cover/cover_thumbnail.jpeg', 156, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wrn2q', 'wrn2q', 'Olhares sobre o adoecimento crônico: representações e práticas de cuidado às pessoas com doença falciforme', NULL, '["Evanilda Souza de Santana Carvalho","Xavier, Aline Silva Gomes"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'O foco deste estudo é a doença falciforme, à luz das histórias de pessoas portadoras dessa patologia. Em 21 capítulos, os autores investigam e analisam as repercussões da doença, tanto as resultantes do corpo em transformação e adaptação contínua, com grande sofrimento físico, quanto as provenientes da invisibilidade dos sintomas. A medicina já conhece há mais de um século a doença falciforme, que se caracteriza por uma alteração anatômica nos glóbulos vermelhos. Com isso, fica prejudicado o transporte de oxigênio. Daí a anemia. Crises de dores são causadas pela obstrução do fluxo sanguíneo. A importância deste livro reside nas informações que presta a respeito dessa doença, o que constitui uma ajuda valiosa aos pacientes, familiares, prestadores de serviços e cuidados.', '["sickle cell disease","chronic disease","patient narratives","care practices","illness representations","vaso-occlusive crisis","anemia","oxygen transport","sickle red blood cells","patient and family caregivers"]', '10.7476/9788555921124', '9788555921124', 'https://books.scielo.org/id/wrn2q', 'https://books.scielo.org/id/wrn2q/pdf/carvalho-9788555921124.pdf', NULL, 'https://books.scielo.org/id/wrn2q/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wrznc', 'wrznc', 'Produtos à base de plantas: efetividade e segurança no tratamento de pacientes oncológicos', NULL, '["Eliana Rodrigues","Patrícia de Carvalho Mastroianni"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', '“Ainda que produtos à base de plantas (PBPs) sejam amplamente utilizados pela população, faltam informações seguras e orientações adequadas sobre sua utilização como recurso terapêutico. É preciso conhecer mais sobre preparo e manuseio corretos, posologia, indicações, possíveis interações medicamentosas e regulamentação dos PBPs, pois o uso associado de determinados fitoterápicos a tratamentos convencionais pode aumentar os riscos de efeitos adversos medicamentosos (EAM). Nesse sentido, é grande a relevância desta obra, pois as organizadoras reuniram aqui um completo material de apoio sobre produtos à base de plantas associados ao tratamento de pacientes oncológicos, oferecendo importantes informações e orientações para profissionais e estudantes de graduação da área de saúde que objetivam promover o uso efetivo e seguro de PBPs.”', '["plant-based products","herbal medicine","cancer patients","cancer therapy","drug interactions","adverse drug reactions","safety","herbal medicine regulation","dosage"]', '10.7476/9786557140109', '9786557140109', 'https://books.scielo.org/id/wrznc', 'https://books.scielo.org/id/wrznc/pdf/rodrigues-9786557140109.pdf', NULL, 'https://books.scielo.org/id/wrznc/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wrzz4', 'wrzz4', 'O futuro é meu enquanto eu viver: desafios da psicologia em contextos educacionais', NULL, '["Teixeira, Adrielle de Matos Borges","Jacinto, Pablo Mateus dos Santos","Dazzani, Maria Virgínia Machado"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta coletânea reúne 11 textos sobre as relações entre psicologia e educação no contexto brasileiro contemporâneo, profundamente marcado por desigualdades sociais e lutas políticas. Ao longo da leitura, são apresentadas especulações teóricas, análises de casos e relatos de pesquisa que procuram refletir sobre diversos contextos educacionais, tensões sociais e raciais no interior das instituições educacionais e trajetórias estudantis. A obra visa contribuir para a compreensão das práticas de psicólogos(as) e educadores(as) nessa zona tensa, permanentemente assombrada pela desigualdade, pela injustiça e pela violência.', '["psychology and education","educational psychology","educational inequality","student trajectories","school violence","educational injustice","Brazilian education"]', '10.7476/9786556305189', '9786556305189', 'https://books.scielo.org/id/wrzz4', 'https://books.scielo.org/id/wrzz4/pdf/teixeira-9786556305189.pdf', NULL, 'https://books.scielo.org/id/wrzz4/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wtg4k', 'wtg4k', 'Nas rodas da capoeira e da vida: corpo, experiência e tradição', NULL, '["Christine Nicole Zonzon"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Trata-se de um livro voltado tanto ao público acadêmico quanto aos amantes da capoeira interessados em questões como corporeidade, transmissão da cultura e permanências/mudanças no seio da tradição. Praticante da capoeira angola há muitos anos, a autora passou, no curso de sua pesquisa, pelo aprendizado da capoeira regional. Essa experiência revestiu-se de um caráter duplo: ela não apenas aprendeu um novo estilo de prática, mas também, à luz desse processo, pode re-aprender o estilo (angola) ao qual o corpo já se habituara. O resultado disso é uma reflexão cuidadosa, sensível, sobre os modos de engajamento do corpo em duas vertentes da capoeira até então vistas predominantemente sob a ótica simplista de uma oposição entre a conservação e desvirtuamento da tradição.', '["capoeira","embodiment","cultural transmission","tradition and change"]', '10.7476/9788523220334', '9788523215682', 'https://books.scielo.org/id/wtg4k', NULL, NULL, 'https://books.scielo.org/id/wtg4k/cover/cover_thumbnail.jpeg', 333, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wtthy', 'wtthy', 'A vertente grega da gramática tradicional: uma visão do pensamento grego sobre a linguagem', NULL, '["Maria Helena de Moura Neves"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Versão revisada do livro A vertente grega da gramática tradicional, de 1987, esgotado há muitos anos, título ao qual se acrescenta agora o subtítulo Uma visão do pensamento grego sobre a linguagem, que torna mais transparente o conteúdo da obra. Reedição que surge num momento de efervescência das bases do ensino de gramática, discussão essencialmente centrada nas críticas à gramática tradicional, que muitas vezes remontam à emergência da disciplina gramatical na Grécia, e que, em geral, são nascidas de um desconhecimento das condições em que a disciplina surgiu. Essas condições é que são tratadas neste livro.', '["traditional grammar","Greek grammar","history of grammar","language teaching"]', '10.7476/9788539303465', '9788571395817', 'https://books.scielo.org/id/wtthy', NULL, NULL, 'https://books.scielo.org/id/wtthy/cover/cover_thumbnail.jpeg', 278, 19, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wvqr3', 'wvqr3', 'Urbanismo na América do Sul: circulação de ideias e constituição do campo, 1920-1960', NULL, '["Marco Aurélio A. de Filgueiras Gomes"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Engineering', 'Os textos reunidos nessa coletânea visam contribuir para ampliar as possibilidades de discussão sobre a história do urbanismo nessas décadas cruciais em que as cidades sul-americanas conhecem expressivas taxas de crescimento, o agravamento dos problemas urbanos e a busca, em várias frentes e de diferentes maneiras, de soluções para enfrentá-los. A partir de perspectivas diversas, eles buscam aproximar diferentes experiências nacionais, explorar singularidades, rastrear o surgimento de redes profissionais, mapear discussões, identificar enfim caminhos e descaminhos da construção de uma cultura urbanística no âmbito continental.', '["urban history","urban expansion","urban problems","circulation of ideas","professional networks","urban-rural relations"]', '10.7476/9788523209261', '9788523209261', 'https://books.scielo.org/id/wvqr3', 'https://books.scielo.org/id/wvqr3/pdf/gomes-9788523209261.pdf', NULL, 'https://books.scielo.org/id/wvqr3/cover/cover_thumbnail.jpeg', NULL, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ww5zt', 'ww5zt', 'Os verbos de padrão especial no português do século XVI', NULL, '["Zenaide de Oliveira Novais Carneiro"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A escrita portuguesa do século XVI — a chamada fase clássica, ou português clássico — é estudada neste livro, em que os verbos conhecidos na tradição gramatical como irregulares apresentam variação tanto nos seus lexemas quanto em suas flexões, o que os afastaria dos verbos regulares. Para a autora, no entanto, esses verbos possuem características mórficas e padrões comuns, razão pela qual seria justificável classificá-los como pertencentes a um paradigma especial, como agrupamentos específicos. O corpus do estudo foi formado por dois conjuntos de documentos, datados da primeira metade do século XVI e do início do terceiro quartel, distribuídos em 23 itens verbais, além dos verbos de particípio passado especial, totalizando 7.238 dados, referentes às cartas de D. João III e à obra pedagógicogramatical de João de Barros.', '["irregular verbs","verb morphology","verb inflection","lexical variation","João de Barros","João III of Portugal"]', '10.7476/9788555921087', '9788555921087', 'https://books.scielo.org/id/ww5zt', 'https://books.scielo.org/id/ww5zt/pdf/carneiro-9788555921087.pdf', NULL, 'https://books.scielo.org/id/ww5zt/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wwfpz', 'wwfpz', 'Uma superfície de gelo ancorada no riso: a atualidade do grotesco em Hilda Hilst', NULL, '["Reginaldo Oliveira Silva"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A compreensão de Contos d’Escárnio não poderia restringir-se à construção do horizonte no qual nasce, o século XX. A intenção de escrever lixo e bestagem, anunciada pelo narrador, aos poucos, revela um grotesco vindo de um longínquo, de um aquém. Por isto, faz-se necessário também compreender o fluxo histórico-estético que encontra acolhida na imaginação de Hilda Hilst, cujo amparo conceitual buscou-se à estética da recepção e do efeito. Na Teoria Estética, o feio insurge como fenômeno da realidade artística contemporânea; refúgio de sobrevivência da arte e dos belos escritos, deixa livre à plasticidade do presente a tarefa da denúncia da realidade. Em protesto, o dissonante reivindica cidadania e se mantém como possibilidade da arte. Neste sentido, tem lugar em Hilda Hilst a atualidade do grotesco.', '["Hilda Hilst","grotesque","the uncanny","aesthetic theory","reception theory","contemporary art"]', '10.7476/9788578792848', '9788578792848', 'https://books.scielo.org/id/wwfpz', 'https://books.scielo.org/id/wwfpz/pdf/silva-9788578792848.pdf', NULL, 'https://books.scielo.org/id/wwfpz/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wwn4b', 'wwn4b', 'Entrenotas: compreensões de pesquisa', NULL, '["Cássio E. Viana Hissa"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'Este livro não constitui um manual, mas leitura estimulante que orienta a estruturação não convencional de projetos e de pesquisas. Trata-se de crítica propositiva ao padronizado modo de fazer ciência, aos métodos que subtraem a criatividade, aos caminhos previsíveis na produção do conhecimento. A delicadeza imaginativa desta obra ensaística é de interesse de um público diverso – das mais variadas áreas do conhecimento, no âmbito da graduação e da pós-graduação – envolvido com a produção do saber que se quer distante do que é repetição comum.', '["research design","creative research","knowledge production","research methodology","graduate research","undergraduate research"]', '10.7476/9788542302912', '9788570419934', 'https://books.scielo.org/id/wwn4b', NULL, NULL, 'https://books.scielo.org/id/wwn4b/cover/cover_thumbnail.jpeg', 197, 17, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wx2f8', 'wx2f8', 'Escrevam porque as ditaduras não duram para sempre', NULL, '["Loiva Otero Félix","Daniela Oliveira Silveira"]', 'Editora da UFRGS', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Obra que enfoca o período da ditadura civil-militar, inaugurado com outro golpe de Estado em 1964, a partir da trajetória de uma bravíssima mulher de lutas e realizações. Esta edição, além do novo prefácio e de uma revisão geral, conta com capítulo que discute as alterações histórica pelas quais o Brasil passou desde o fim dos governos Fernando Henrique Cardoso até o contexto atual.', '["Brazilian military dictatorship","Estado Novo","1964 coup","civil-military dictatorship","Fernando Henrique Cardoso","Brazilian politics","political history","democratization"]', '10.7476/9786557251249', '9788538604730', 'https://books.scielo.org/id/wx2f8', NULL, NULL, 'https://books.scielo.org/id/wx2f8/cover/cover_thumbnail.jpeg', 338, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wxn94', 'wxn94', 'Entre a literatura e o ensino: a formação do leitor', NULL, '["Maria do Rosário Longo Mortatti"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Neste livro, estão reunidos onze textos produzidos durante a atuação profissional da autora, no ensino fundamental e médio, entre 1976 e 1991, e na Universidade Estadual Paulista, desde 1991. Nele, “o leitor vai encontrar, ao lado de instigantes reflexões sobre questões de literatura, leitura e ensino, registros preciosos da formação de um pesquisador. No caso, da autora Maria do Rosario Mortatti, especialista renomada na área de leitura e educação. É com os passos que construíram sua expertise na área que este livro, já de início, nos familiariza. […] Foi por este percurso, e ao longo de todo ele que – creio – foi se tecendo, se fortalecendo e se sofisticando a indagação fundamental que a autora faz a si mesma e a seus leitores: a leitura da literatura é mesmo essencial? E se for – como creio que postula Mortatti e que constitui a tese deste livro – como desenvolver práticas pedagógicas, formais e informais, que promovam acesso humanamente significativo a textos literários? […] Considerando que é a importância da leitura, particularmente a importância da leitura literária que justifica a missão da escola de formar leitores, Mortatti acompanha o percurso histórico cumprido pelas reflexões/preocupações sobre o papel da leitura na escola e (para fora dela) na vida de todos nós.”', '["reader formation","literary reading","reading instruction","literature teaching","teaching practice","history of reading instruction"]', '10.7476/9788595462854.', '9788595462854', 'https://books.scielo.org/id/wxn94', 'https://books.scielo.org/id/wxn94/pdf/mortatti-9788595462854.pdf', NULL, 'https://books.scielo.org/id/wxn94/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wxtn8', 'wxtn8', 'Línguas estrangeiras/adicionais, educação crítica e cidadania', NULL, '["Silva, Kleber Aparecido da"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Aprender línguas, na atualidade, envolve engajamento social e discursivo em um mundo multimodal, multicultural e multimidiático. Essa situação acaba por demandar dos professores um engajamento crítico em seu contexto de atuação e na realidade circundante ainda maior. Assumir posturas críticas, cidadãs, engajadas faz-se, portanto, necessário. Nessa linha, esta obra realizou um mapeamento da área de ensino e aprendizagem de línguas estrangeiras/adicionais nos anos iniciais e finais do ensino fundamental I e II, focalizando questões de parametrizações, material didático, interação em sala de aula, avaliação e formação de professores, considerando centralmente uma preocupação com a criação de contextos informados, significativos e emancipatórios.', '["foreign language teaching","additional languages","critical education","citizenship","primary education","teacher professional development","teaching materials","classroom interaction","assessment","emancipatory learning","multimodal learning","multiculturalism"]', '10.7476/9786558461647', '9786558461647', 'https://books.scielo.org/id/wxtn8', 'https://books.scielo.org/id/wxtn8/pdf/silva-9786558461647.pdf', NULL, 'https://books.scielo.org/id/wxtn8/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wy7ft', 'wy7ft', 'Uma procissão na geografia', NULL, '["Zeny Rosendahl"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A religião constitui um fato social, sendo objeto de estudo por parte da filosofia e diversas ciências sociais.Como fato social, exibe uma necessária temporalidade e espacialidade; isto é, está inscrita no tempo e no espaço.Desse modo, é também objeto da geografia, ainda que nesta a espacialidade adquira muito mais ênfase.No entanto, o interesse do geógrafo pela religião é muito menor do que aquele demonstrado por outros campos de conhecimento, ainda que a religião esteja em toda a parte, apresentando processo, formas e interações espaciais que apresentam diversos significados.O interesse do geógrafo pela religião, por menor que seja, produziu um conhecimento singular e relativamente recente.Mas ainda há muito mais a fazer.Nesse sentido, o presente livro contribui para a ampliação desse conhecimento produzido por geógrafos brasileiros vinculados ao NEPEC -Núcleo de Estudos e Pesquisas sobre Espaço e Cultura -do Departamento de Geografia Humana da UERJ.Trata-se de uma coletânea organizada por Zeny Rosendahl, fundadora do NEPEC, que incluiu alguns de seus textos.A coletânea, na verdade, é o resultado da longa e rica trajetória de Zeny Rosendahl, iniciada efetivamente em 1989, 8 quando foi fazer seu doutoramento na USP.Sua tese diz respeito a um pequeno centro de peregrinação, Porto das Caixas, localizado em Itaboraí, região metropolitana do Rio de Janeiro.A tese foi defendida em 1994, mas o NEPEC já tinha sido fundado em 1993.Seguiram-se inúmeros estudos e diversas publicações, a começar pelo livro Espaço e Religião: uma abordagem geográfica, de 1996; Hierópolis: o sagrado e o urbano; Trilhas do Sagrado e Primeiro a obrigação, depois a devoção: estratégias espaciais da Igreja Católica no Brasil de 1500 a 2005, todos publicados pela EdUERJ.A organização de coletâneas, em capítulos de livros e artigos, faz parte da contribuição à geografia da religião.Acrescentam-se ainda cerca de 21 dissertações de mestrado e seis teses de doutorado orientadas por ela no PPGEO/UERJ, criado em 2012, com a abordagem na dimensão religiosa no espaço.A contribuição de Zeny Rosendahl é mais bem explicitada ao se considerarem os temas abordados por ela.O mais importante diz respeito à temática do espaço sagrado e espaço profano, tema central na obra de Mircea Eliade.Não se trata de uma dicotomia, mas de uma unidade na diversidade, na qual a espacialidade assume uma expressão thuniana.Há, em realidade, uma continuidade em relação ao ponto fixo, de maior sacralidade, exibindo uma continuidade no espaço.A segunda contribuição refere-se às dimensões de análise do sagrado, publicada em 2003 na coletânea Introdução à Geografia Cultural.Trata-se de uma proposição metodológica, sendo indicadas três vias por meio 9 das quais o sagrado pode ser estudado.Dimensão política, dimensão econômica e dimensão do lugar, as três vias indicadas anteriormente, fornecem caminhos para a análise do sagrado, estabelecendo conexões com temas da geografia política, econômica e da análise do lugar com base na geografia cultural e humanista.A espacialidade do sagrado traduz-se em lógicas locacionais de suas formas espaciais.Nesse sentido, as hierópolis apresentam padrões de localização variados, tanto no espaço regional quanto no intraurbano.O território religioso -sua identificação, descrição e interpretação -é a quarta temática no âmbito das contribuições da geógrafa.A paróquia e a diocese são os territórios religioso e político sobre os quais a Igreja Católica está espacialmente organizada.A difusão espacial das dioceses constitui--se no quinto tema.Trata-se do espraiamento no tempo das dioceses católicas no Brasil, espraiamento estudado desde 1551, quando a primeira diocese foi criada em Salvador, até cerca do ano de 2000.A análise da difusão relaciona-se ao processo de povoamento do território brasileiro e às múltiplas estratégias da Igreja.Tolerância e intolerância religiosa, tema inscrito ao longo da história humana e em evidência nos tempos atuais, é de fundamental importância para a geografia da religião, porque nela o espaço está claramente presente.Intolerância entre católicos e protestantes na Irlanda do Norte, entre evangélicos e umbandistas no Rio de Janeiro 10 e entre sunitas e xiitas no mundo mulçumano são exemplos atuais muito significativos.Consideram-se ainda os embates e conflitos entre cristãos e mulçumanos e a intolerância contra judeus e ciganos.Essa temática é ainda mais importante quando se pensa no Brasil, porque a diversidade recente de religiões tem feito emergir a tolerância e a intolerância religiosa, agora com mais vigor do que no passado.Parte da contribuição de Zeny Rosendahl está presente nos diversos textos deste livro, mas não toda.Há trilhas e itinerários simbólicos a serem percorridos, conexões com outros temas a serem estabelecidos, além de novos temas a serem descobertos.Mas, por ora, leiamos os textos aqui reunidos, enriquecendo nossas mentes e corações.tempo i 1989 a 1999 espaço e cUltUra Uma proposição temática 1O temário apresentado visa contribuir para sistematizar os estudos sobre a diversidade religiosa no espaço, permitindo encontrar analogias e formular princípios.O exame dos temas selecionados, por outro lado, pode ser objeto de preocupação para aqueles que se dedicam ao estudo de uma mesma religião em suas complexas dimensões espaciais.O temário selecionado é constituído pelos seguintes assuntos:• fé, espaço e tempo: difusão e área de abrangência;• centros de convergência e irradiação;• religião, território e territorialidade;• espaço e lugar sagrado: vivência, percepção e simbolismo.É conveniente ressaltar que os temas em questão não são mutuamente excludentes entre si; ao contrário, interpenetram-se.Assim, à guisa de exemplificação, um centro de convergência religiosa está inserido no 29 des, na França, e Roma, na Itália.Entretanto, deve-se reconhecer que no Brasil a peregrinação guarda, de forma quase unânime, uma característica evidentemente religiosa, assumindo o sentido de um sacrifício.Os locais sagrados do Brasil variam em tamanho e importância, incluindo desde um pequeno crucifixo à beira da estrada até santuários requintados como a Basílica de Nossa Senhora Aparecida, estrategicamente construída no eixo Rio-São Paulo, ligando as duas mais importantes cidades brasileiras.Os centros de convergência religiosa de Bom Jesus, em Iguape, Pirapora do Bom Jesus e Bom Jesus dos Perdões, situados no estado de São Paulo, foram examinados por França (1972) num estudo religioso-geográfico. Sua preocupação estava voltada para as cidades de função religiosa, iniciando, dessa forma, no Brasil, o estudo do impacto da religião sobre a paisagem.Na tentativa de relacionar religião e ambiente, através do estudo da organização espacial dos centros de peregrinação do interior do Brasil, Rosendahl (1994) analisou Muquém, no estado de Goiás, e Santa Cruz dos Milagres, no estado do Piauí.São centros rurais de convergência religiosa, predominantemente do catolicismo popular, nos quais o fenômeno religioso recria o espaço sagrado por ocasião da peregrinação.Como explicar que uma localidade de duzentos habitantes tenha, numa festa religiosa, a presença de sessenta mil pessoas, conforme ocorre em Muquém?Que transformações espaciais são advindas dessa Enfim… resta apenas sair a campo e desvendar a heterogeneidade religiosa brasileira em sua espacialidade.ReFeRências BOURDIEU, P. "Gênese e estrutura do campo religioso".A economia das trocas simbólicas. 2 ed.', '["religion and geography","sacred space","pilgrimage","Brazilian geography","space and culture","Itaboraí","Rio de Janeiro metropolitan region"]', '10.7476/9788575115015', '9788575115015', 'https://books.scielo.org/id/wy7ft', 'https://books.scielo.org/id/wy7ft/pdf/rosendahl-9788575115015.pdf', NULL, 'https://books.scielo.org/id/wy7ft/cover/cover_thumbnail.jpeg', NULL, 11, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wywjy', 'wywjy', 'Agadá: dinâmica da civilização africano-brasileira', NULL, '["Marco Aurélio de Oliveira Luz"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra traz informações sobre as instituições das tradições africanas no Brasil, seu universo de valores e linguagens. Além disso, destaca-se o funcionamento das políticas do Estado eurocêntrico e seus desdobramentos no decorrer da história. A singularidade da abordagem evidencia-se na ruptura com os limites positivistas, valorizando as narrativas do mito da tradição africana como fonte de saber universal e atemporal. O livro abre a percepção do/a leitor/a para a pujança do continuum da civilização africana antes e durante o período colonial e neocolonial. Dessa forma, possibilita perceber o negro como sujeito coletivo da história, que infere diretamente no fim do tráfico e da escravatura, além de repor nas Américas sua comunidade baseada em valores, linguagens e formas de sociabilidade das diversas tradições socioculturais.', '["African diaspora","Eurocentrism","colonialism","neocolonialism","slavery","transatlantic slave trade","socio-cultural traditions","sociability"]', '10.7476/9786556303710', '9786556300283', 'https://books.scielo.org/id/wywjy', NULL, NULL, 'https://books.scielo.org/id/wywjy/cover/cover_thumbnail.jpeg', 511, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wz6qg', 'wz6qg', 'Desenlace a los conflictos desde la justicia tradicional: experiencias comparadas, aportes para el caso colombiano', NULL, '["Cubides-Cárdenas, Jaime","Reyes García, Daiana","Paola Alexandra Sierra-Zamora"]', 'Editorial Fundación Universitaria San Mateo', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Los acuerdos de paz son estudiados en la pre-sente propuesta como referencia (Filipinas, Irlanda del Norte, Sudán del Sur, El Salvador y Colombia). Ayudan a comprender que la tan anhelada paz (estable y duradera) solo puede ser pronta, rígida y transformadora si se comprenden el conjunto de medidas mínimas requeridas. Depende de acuerdo con la capacidad institucional de cada Estado, puesto que no existe una única fórmula internacional e interinstitucional en el marco de un acuerdo de paz. Este hecho hace que la presente propuesta lleve consi-go un plus elemental para evaluar las condiciones y medidas (en todos sus niveles) en el desarrollo del acuerdo.', '["peace agreements","peacebuilding","traditional justice","conflict resolution","post-conflict peace","institutional capacity","comparative case study","Colombia","Northern Ireland","El Salvador"]', '10.7476/9786289558227', '9786289558227', 'https://books.scielo.org/id/wz6qg', 'https://books.scielo.org/id/wz6qg/pdf/cubides-9786289558227.pdf', NULL, 'https://books.scielo.org/id/wz6qg/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wzck3', 'wzck3', 'Estudos linguísticos e literários aplicados ao ensino/9788582930472', NULL, '["Elisa Guimarães"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '[RETIRADO/WITHDRAWN] A obra encadeia associações entre os valores técnicos da língua e os valores estéticos da literatura. Realiza, então, duas abordagens complementares, defi nida a unidade língua/literatura como uma díade com polos inseparáveis – a língua sustentando um código limitativo e prescritivo; a literatura alimentando a reprodução artística do sistema linguístico –, da fusão de ambas resultando um efeito de sentido.', '["language and literature","linguistics","literature","language teaching","literary analysis","linguistic values","aesthetic value","language as code","language system"]', '10.7476/9788582930472', '9788582930472', 'https://books.scielo.org/id/wzck3', NULL, NULL, 'https://books.scielo.org/id/wzck3/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wzwg4', 'wzwg4', 'Pesquisas em lingüística aplicada: ensino e aprendizagem de língua estrangeira', NULL, '["Douglas Altamiro Consolo","Maria Helena Vieira Abrahão"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Tema fascinante e de grande importância, este livro trata da atuação de professores de segunda língua ou língua estrangeira, reunindo trabalhos realizados a partir de dissertações de alunos do Programa de Pós-Graduação em Estudos Lingüísticos do Instituto de Biociências, Letras e Ciências Exatas (Ibilce) da UNESP, Câmpus de São José do Rio Preto, da área de Lingüística Aplicada. Especialmente interessante para a formação de pesquisadores e professores de línguas, por apresentar estudos de situações de ensino/aprendizagem em diversos contextos escolares, considerando a diversidade do cenário brasileiro, com sugestões de encaminhamento de novas investigações.', '["applied linguistics","foreign language teaching","second language teaching","language learning","teacher professional development","language teacher education","school context"]', '10.7476/9788539303366', '9788571395169', 'https://books.scielo.org/id/wzwg4', NULL, NULL, 'https://books.scielo.org/id/wzwg4/cover/cover_thumbnail.jpeg', 183, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wzwmf', 'wzwmf', 'O feroz mosquito africano no Brasil: o Anopheles gambiae entre o silêncio e a sua erradicação (1930-1940)', NULL, '["Gabriel Lopes"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '(Prêmio Oswaldo Cruz de Teses 2017) Integrante da coleção História e Saúde da Editora Fiocruz, o livro desenvolve uma narrativa histórica de chegada, alastramento e erradicação do Anopheles gambiae, mosquito que teve provável origem em Dacar, capital do Senegal, e chegou ao Brasil pelo Rio Grande do Norte. O vetor causou uma epidemia de malária sem precedentes no Brasil no início dos anos 1930 e, após esforços cooperativos entre o governo brasileiro de Getúlio Vargas e a Fundação Rockefeller, foi erradicado em 1940. Pesquisador da Casa de Oswaldo Cruz, o autor Gabriel Lopes aborda, ao longo de quatro capítulos, condicionantes políticas, sociais e ecológicas que permitiram que o mosquito se espalhasse pelo Nordeste do país, incluindo questões como o ritmo das chuvas e os períodos de seca. A obra também apresenta notas, referências e imagens de acervo ligadas ao período de alastramento e combate ao Anopheles gambiae.', '["Anopheles gambiae","malaria","mosquito eradication","mosquito invasion","Rio Grande do Norte","Northeast Brazil","Getúlio Vargas government","Rockefeller Foundation","history of public health","malaria epidemic","vector control","1930s"]', '10.7476/9786557080160', '9786557080023', 'https://books.scielo.org/id/wzwmf', NULL, NULL, 'https://books.scielo.org/id/wzwmf/cover/cover_thumbnail.jpeg', 227, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-x2898', 'x2898', 'Pluralismo jurídico estatal: entre conflicto y diálogo. Enseñanzas de un caso colombiano', NULL, '["Nelcy López Cuéllar"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Más allá de qué corte tiene la razón en el conocido “choque de trenes” entre las altas cortes colombianas, el libro explora qué tipo de fenómeno jurídico se presenta en este choque. La autora argumenta que el caso colombiano es un claro ejemplo de pluralismo jurídico estatal. Este vívido ejemplo de pluralismo debilita el mito del monismo jurídico dentro del Estado. Igualmente, debido a su relación con el pluralismo jurídico estatal, el texto explora con precisión y cuidado conceptos de uso continuo en la teoría del derecho y ciencia política como: autoridad, obediencia, desobediencia y diálogo interinstitucional. Además, la obra ofrece una mirada nueva a las consecuencias de la implantación del modelo de derecho jerárquico propuesto por Kelsen y sus limitaciones para desarrollar una dinámica de diálogo y colaboración armónica dentro del Estado.', '["legal monism","Colombian Constitutional Court","Colombian Supreme Court","inter-institutional dialogue","authority","obedience","disobedience","Hans Kelsen","Colombian constitutional law"]', '10.7476/9789587385649', '9789587385632', 'https://books.scielo.org/id/x2898', NULL, NULL, 'https://books.scielo.org/id/x2898/cover/cover_thumbnail.jpeg', 278, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-x2pc4', 'x2pc4', 'Processo de enfermagem: da teoria à prática no cuidado oncológico', NULL, '["Júlia Valéria de Oliveira Vargas Bitencourt","Édlamar Kátia Adamy","Carla Argenta"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Nursing', 'Este livro, que é o terceiro volume da Coleção Processo de Enfermagem: da teoria à prática, conta com a participação de 28 autores(as). A partir do tema central – cuidado de enfermagem ao paciente oncológico –, organiza-se em seis capítulos, os quais apresentam aspectos históricos e contextuais do cuidado em oncologia, o relato acerca do desenvolvimento e a implantação do histórico de enfermagem no serviço de oncologia do Hospital Regional do Oeste (HRO), em Chapecó, os resultados de uma pesquisa sobre a prevalência dos diagnósticos de Enfermagem em pacientes com neoplasias gastrointestinais, a apresentação da Matriz Assistencial com a ligação entre os diagnósticos, intervenções e resultados de Enfermagem para o atendimento a pacientes em tratamento oncológico, o relato da informatização do Processo de Enfermagem no HRO e o ensino do Processo de Enfermagem em oncologia. Processo de Enfermagem: da teoria à prática no cuidado oncológico pode contribuir com o processo de aprendizado de estudantes e de enfermeiros, além de ser uma leitura essencial para docentes que atuam no ensino teórico, prático e na pesquisa. O conteúdo revela um modelo construído que contribui para o desenvolvimento do pensamento crítico de profissionais de enfermagem que desejam adaptá-lo à sua vida profissional.', '["nursing process","nursing diagnosis","gastrointestinal cancer","nursing interventions","nursing outcomes","history of nursing","nursing informatics","nursing education","critical thinking in nursing"]', '10.7476/9786550190606', '9786550190606', 'https://books.scielo.org/id/x2pc4', 'https://books.scielo.org/id/x2pc4/pdf/bitencourt-9786550190606.pdf', NULL, 'https://books.scielo.org/id/x2pc4/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-x3d3q', 'x3d3q', 'Tabu da morte', NULL, '["José Carlos Rodrigues"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Do mesmo autor de Tabu do Corpo, originalmente tese de doutorado, este livro, publicado anteriormente em 1983, explora um tema que se situa à margem do que costuma ser objeto das investigações antropológicas – a vida que as pessoas vivem em seus diversos aspectos, seja no plano social, familiar, político, econômico, artístico ou religioso. Desse modo, uma antropologia da morte poderia representar um contra-senso, a menos que seja tratada da maneira que se faz aqui, como meio para se compreender a própria vida. Das sociedades chamadas primitivas ao capitalismo contemporâneo, o autor conduz a reflexão a expandir nossa imaginação por meio do inventário e da cuidadosa análise das diferentes formas de pensamento e dos distintos modos de ação que permitem aos coletivos humanos inverter o rumo aparentemente inexorável das coisas e da morte, fazer a vida.', '["anthropology of death","death","life","primitive society","capitalism","ways of thinking","mechanism of action","meaning of life"]', '10.7476/9788575413722', '9788575410905', 'https://books.scielo.org/id/x3d3q', NULL, NULL, 'https://books.scielo.org/id/x3d3q/cover/cover_thumbnail.jpeg', 260, 78, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-x3fts', 'x3fts', 'Livros didáticos de história: concepções civilizatórias para o ensino primário da Bahia (1925-1933)', 'concepções civilizatórias para o ensino primário da Bahia (1925-1933)', '["Cristina Ferreira de Assis"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A obra investiga concepções civilizatórias veiculadas em três livros didáticos de História adotados no ensino primário da Bahia entre 1925 e 1933, em meio às reformas educacionais realizadas ente os estados brasileiros na Primeira República. Por meio da análise de conteúdo e do estudo da materialidade de obras de Rocha Pombo, Pedro Calmon e Alberto de Assis, a autora identifica valores, normas e códigos sociais transmitidos pelos livros, compreendidos como artefatos da cultura material escolar. Os resultados contribuem para os campos da História da Educação e do Ensino de História ao examinarem as trajetórias dos autores, além dos impressos como instrumentos que fizeram parte da formação social e política no âmbito das práticas escolares.', '["history textbooks","primary education","Bahia","First Brazilian Republic","educational reform","school material culture","history education"]', '10.7476/9788574556291', '9788574556079', 'https://books.scielo.org/id/x3fts', NULL, NULL, 'https://books.scielo.org/id/x3fts/cover/cover_thumbnail.jpeg', 278, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-x47ps', 'x47ps', 'SUS: o desafio de ser único', NULL, '["Carlos Octávio Ocké‐Reis"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Ao investigar nosso sistema de saúde – o público e o privado –, este livro propõe alternativa para fortalecer o Sistema Único de Saúde (SUS) e fustigar o poder econômico do capital financeiro e dos oligopólios. Afinal, segundo Ocké-Reis, esse sistema paralelo reproduz desigualdades sociais, favorece o crescimento do mercado e inviabiliza os preceitos constitucionais da saúde. Enquanto o SUS atravessa uma crise crônica de financiamento, a consolidação dos planos acaba concentrando renda e subtraindo recursos do setor público de saúde. De acordo com autor, o setor privado mais prejudica do que colabora com o setor público, porque o aumento do gasto privado e o fortalecimento do poder econômico corroem a sustentabilidade do financiamento público na arena política, levando a um círculo vicioso, caracterizado por uma queda relativa do investimento na saúde pública. Ocké-Reis, do Instituto de Pesquisa Econômica Aplicada (Ipea), defende uma regulação substantiva do mercado pela Agência Nacional de Saúde Suplementar (ANS), que não pode ter sua atuação ameaçada pela concentração, centralização e internacionalização das operadoras líderes. A ANS deve organizar o mercado na perspectiva do interesse público, impedindo que a assistência à saúde seja convertida em um bem de consumo como outro qualquer.', '["public health funding","private health insurance","ANS","oligopoly","financial capital","social inequality","health as a public good"]', '10.7476/9788575415276', '9788575413838', 'https://books.scielo.org/id/x47ps', NULL, NULL, 'https://books.scielo.org/id/x47ps/cover/cover_thumbnail.jpeg', 180, 31, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-x49kz', 'x49kz', 'Protocolos para o monitoramento de habitats bentônicos costeiros - Rede de Monitoramento de Habitat Bentônicos Costeiros - ReBentos', NULL, '["Alexander Turra","Márcia Regina Denadai"]', 'Instituto Oceanográfico da Universidade de São Paulo', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Earth and Planetary Sciences', 'Com a participação de mais de 100 especialistas em pesquisa bentônica marinha costeira, o livro apresenta propostas metodológicas para o monitoramento contínuo e de longo prazo em ecossistemas bentônicos existentes na costa brasileira. Dado que a Rede de Monitoramento de Habitats Bentônicos Costeiros (ReBentos) se propõe a monitorar esse ambiente continuamente e pelo maior número de grupos de pesquisa, cobrindo da forma mais completa possível toda a variação latitudinal da costa, os métodos apresentados foram definidos buscando-se presteza, simplicidade dos procedimentos e baixo custo, favorecendo sua ampla aplicação. A partir desse produto, todos os pesquisadores, vinculados ou não à ReBentos, poderão desenvolver, de forma padronizada e comparativa, pesquisas com diferentes habitats bentônicos nas diferentes regiões da costa brasileira.', '["long-term monitoring","low-cost monitoring","benthic ecosystems","Brazilian coast","comparative research"]', '10.7476/9788598729251', '9788598729251', 'https://books.scielo.org/id/x49kz', 'https://books.scielo.org/id/x49kz/pdf/turra-9788598729251.pdf', NULL, 'https://books.scielo.org/id/x49kz/cover/cover_thumbnail.jpeg', NULL, 21, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-x4fgh', 'x4fgh', 'Negrura, brancura e mestiçagem no imaginário literário brasileiro', NULL, '["Sally Cheryl Inkpin"]', 'EDUNEB', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O objetivo central deste livro é analisar como as ideologias da brancura, negrura e mestiçagem foram criadas e se inseriram no imaginário literário brasileiro, apoiando uma hegemonia sociocultural que enaltece a beleza, os valores e a cultura forjados como sendo do branco em detrimento aos padrões e valores das populações indígena e negra.', '["whiteness","Blackness","racial mixing","mestiçagem","Brazilian literature","literary imaginary","racial ideology","cultural hegemony","indigenous peoples","Black people","racial representation"]', '10.7476/9786588211311', '9788578873707', 'https://books.scielo.org/id/x4fgh', 'https://books.scielo.org/id/x4fgh/pdf/inkpin-9786588211311.pdf', 'https://books.scielo.org/id/x4fgh/epub/inkpin-9786588211311.epub', 'https://books.scielo.org/id/x4fgh/cover/cover_thumbnail.jpeg', 374, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-x4tj4', 'x4tj4', 'Diálogos apócrifos: sobre educação, ensino de língua e literatura', NULL, '["Maria do Rosário Longo Mortatti"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Em Diálogos apócrifos, estão reunidos textos selecionados da produção da autora, Maria do Rosário Longo Mortatti, durante sua atuação profissional: entre 1976 e 1991, como professora de língua portuguesa e literatura na rede pública oficial de ensino paulista e em escolas particulares da cidade de Campinas/SP; e, a partir de 1991, como docente universitária vinculada à Unesp (Universidade Estadual Paulista). São textos de palestras, entrevistas, notas e artigos de opinião ou divulgação científica, escritos entre 1986 e 2014, que permaneceram inéditos ou foram publicados em veículos de circulação restrita ou atualmente fora de circulação. Todos estão relacionados com a temática “educação e ensino de língua e literatura”, na qual estão circunscritos os temas de estudos e pesquisas que a autora veio desenvolvendo ao longo das últimas quatro décadas. Os textos estão organizados em ordem cronológica de sua produção e circulação, propiciando maior visibilidade da perspectiva interdisciplinar, no que se refere à relação tanto dos temas entre si quanto com as demandas que motivaram sua abordagem, em cada momento histórico. Essa ordenação cronológica propicia ainda que o leitor relacione informações e opiniões sobre os assuntos abordados com o momento histórico a que se referem, evitando, assim, anacronismos.', '["Portuguese language teaching","literature teaching","education","public schools","private schools","Campinas","interdisciplinary approach","teacher perceptions","history of education"]', '10.7476/9788568334799', '9788568334799', 'https://books.scielo.org/id/x4tj4', 'https://books.scielo.org/id/x4tj4/pdf/mortatti-9788568334799.pdf', NULL, 'https://books.scielo.org/id/x4tj4/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-x5cz4', 'x5cz4', 'Pesquisa e pós-graduação em estudos do lazer', NULL, '["Hélder Ferreira Isayama","Víctor Andrade de Melo"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'A partir da programação do I Congresso Brasileiro de Estudos do Lazer, um dos principais eventos promovidos até hoje pela Associação Brasileira de Pesquisa e Pós-graduação em Estudos do Lazer (Anpel), entidade organizada e fundada em 2013, a obra Pesquisa e pós-graduação em estudos do lazer apresenta um panorama internacional da produção do conhecimento nessa área – representada por Argentina, Austrália, Brasil, Canadá, Costa Rica, Equador, México, Nova Zelândia e Reino Unido. Ela traz à baila dados inéditos sobre características de programas de mestrado e doutorado (propostas de formação), tendências (temas, categorias, abordagens teóricas e metodológicas e métodos de coletas de dados) e grupos de pesquisa internacionais e nacionais. Em particular, este volume promove importantes reflexões sobre lazer e meio ambiente, lazer e educação, lazer e psicologia, como também apresenta pressupostos teóricos para investigações orientadas à luz da etnografia. Por sua perspectiva multiprofissional, diversidade de temas, ineditismo, abrangência internacional e notoriedade acadêmico-científica dos autores, o livro passa a figurar como referência para cursos de graduação, mestrado e doutorado que dialogam direta ou indiretamente com o lazer, assim como é leitura recomendada para estudiosos do tema. Junior Vagner Pereira da Silva Presidente da Anpel.', '["leisure studies","graduate education","master''s and doctoral programs","research trends","leisure and education","ethnographic methods","international research group"]', '10.7476/9786558580157', '9788542303285', 'https://books.scielo.org/id/x5cz4', NULL, NULL, 'https://books.scielo.org/id/x5cz4/cover/cover_thumbnail.jpeg', 228, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-x5x7v', 'x5x7v', 'Catálogo de plantas e fungos do Brasil - Vol. 2', NULL, '["Forzza, Rafaela Campostrini","Leitman, Paula Moraes","Costa, Andrea","Carvalho Jr., Aníbal Alves de","Peixoto, Ariane Luna","Walter, Bruno Machado Teles","Bicudo, Carlos","Zappi, Daniela","Costa, Denise Pinheiro da","Lleras, Eduardo","Martinelli, Gustavo","Lima, Haroldo Cavalcante de","Prado, Jefferson","Stehmann, João Renato","Baumgratz, José Fernando A.","Pirani, José Rubens","Sylvestre, Lana da Silva","Maia, Leonor Costa","Lohmann, Lucia G.","Paganucci, Luciano","Silveira, Marcos","Nadruz, Marcus","Mamede, Maria Cândida Henrique","Bastos, Maria Nazaré C.","Morim, Marli Pires"]', 'Instituto de Pesquisas Jardim Botânico do Rio de Janeiro', 'Brasil', 'SciELO Books', 'books', 2010, NULL, 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', NULL, '', '[]', '10.7476/9788560035090', '9788588742437', 'https://books.scielo.org/id/x5x7v', 'https://books.scielo.org/id/x5x7v/pdf/forzza-9788560035090.pdf', 'https://books.scielo.org/id/x5x7v/epub/forzza-9788560035090.epub', 'https://books.scielo.org/id/x5x7v/cover/cover_thumbnail.jpeg', 830, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-x63v8', 'x63v8', 'Corujebó: Candomblé e Polícia de Costumes (1938-1976)', NULL, '["Vilson Caetano de Souza Júnior"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro é sobre a perseguição aos candomblés e o controle exercido sobre as manifestações de origem africana na cidade de Salvador através da Delegacia de Jogos e Costumes entre os anos de 1938 a 1976. Trata-se de pesquisa histórica documental realizada realizada nos arquivos da polícia baiana, nos livros de ocorrências e livro de queixas. Entre asocorrências encontramos apreensões de instrumentos a pessoas pegas de sobressalto colocando oferendas. Dentre as queixas, destaca-se ao lado do barulho, os feitiços chamados de bozó. O acesso às fontes pesquisadas por Vilson Caetano de Sousa Júnior representa uma contribuição de inestimável valor aos estudiosos da presença afro-brasileira e de suas marcas indeléveis em nossa cultura, em nosso modo de ser e, por meio dos difíceis caminhos trilhados por sua preservação.', '["Candomblé","Afro-Brazilian religions","Salvador, Bahia","Afro-Brazilian culture"]', '10.7476/9788523218782', '9788523218034', 'https://books.scielo.org/id/x63v8', NULL, NULL, 'https://books.scielo.org/id/x63v8/cover/cover_thumbnail.jpeg', 288, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-x66cf', 'x66cf', 'De poeta a editor de poesia: a trajetória de Machado de Assis para a formação de suas Poesias completas', NULL, '["Fabiana Gonçalves"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Autor dos mais estudados da literatura brasileira, a atuação de Machado de Assis como poeta, no entanto, só mais recentemente tem recebido a devida atenção da crítica. Sendo assim, o estudo de Fabiana Gonçalves vem suprir uma lacuna que de há muito era sentida pelos pesquisadores machadianos. A pesquisa com as Poesias completas, obra publicada em 1901, visou não apenas estudar a produção poética, como também investigar a figura do editor Machado de Assis na organização da antologia.', '["Machado de Assis","poetry collection","literary editing","Brazilian poetry"]', '10.7476/9788579836589', '9788579836589', 'https://books.scielo.org/id/x66cf', 'https://books.scielo.org/id/x66cf/pdf/goncalves-9788579836589.pdf', NULL, 'https://books.scielo.org/id/x66cf/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-x6bh8', 'x6bh8', 'vLiteratura de multidão e intermidialidade: ensaios sobre ler e escrever o presente', NULL, '["Luciano Barbosa Justino"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro perfaz dois movimentos, duas estratégias de leitura: a da intermidialidade e a da literatura de multidão. A fronteira entre elas é tênue e provisória. O que as separa é um filtro que tanto deixa passar quanto retém. É um livro de crítica, um exercício de experimentação crítica que propõe um olhar transversal sobre as obras, com a finalidade de compreendê-las por aquilo que nelas remete para as formas de vida, para os espaços de produção simbólica e de sua logística de circulação e consumo.', '["intermediality","contemporary literature","reading strategies","literary criticism","literary circulation","symbolic production","forms of life"]', '10.7476/9788578792404', '9788578792404', 'https://books.scielo.org/id/x6bh8', 'https://books.scielo.org/id/x6bh8/pdf/justino-9788578792404.pdf', NULL, 'https://books.scielo.org/id/x6bh8/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-x6gng', 'x6gng', 'Expansão e mudanças tecnológicas no agronegócio canavieiro: impactos na estrutura fundiária e na ocupação agropecuária', NULL, '["José Giacomo Baccarin"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A partir de 1975, ocorre uma grande expansão da lavoura canavieira no estado de São Paulo e, no final da década de 1990, o início da mecanização das etapas de plantio e colheita da cultura. Com a expansão produtiva, elevou-se a concentração da posse da terra no estado, com mais de 64% de canaviais plantados em estabelecimentos agropecuários maiores que mil hectares. Nas empresas sucroalcooleiras paulista, o número de pessoas ocupadas nas atividades industriais cresceu proporcionalmente à produção setorial, mas foi reduzido para menos da metade o número dos trabalhadores empregados no corte de cana ou em outras atividades com menor exigência de qualificação profissional. Esses dados indicam que as transformações tecnológicas fizeram a atividade canavieira contribuir de modo negativo para a ocupação agropecuária paulista. Este livro procura estudar os efeitos dessa expansão na estrutura fundiária, apontar as causas da aceleração recente da mecanização das atividades de lavoura e, ao mesmo tempo, analisar seus efeitos sobre a ocupação canavieira e agropecuária no estado de São Paulo.', '["sugarcane industry","land tenure structure","land concentration","technological change","agricultural employment","sugarcane harvesting","sugar and alcohol industry","large farms","São Paulo state"]', '10.7476/9788595463349', '9788595463349', 'https://books.scielo.org/id/x6gng', 'https://books.scielo.org/id/x6gng/pdf/baccarin-9788595463349.pdf', NULL, 'https://books.scielo.org/id/x6gng/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-x6mh4', 'x6mh4', 'Resíduos plásticos e reciclagem: aspectos gerais e tecnologia', NULL, '["María Zanín","Sandro Donnini Mancini"]', 'EdUFSCar', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'A população do planeta, no início do século XXI, é estimada em 6,2 bilhões de habitantes (no início da civilização era de somente 200 milhões), que geram mais de um bilhão de toneladas de resíduos sólidos a cada ano, sendo cerca de 83 milhões de toneladas a parte brasileira. Nesse sentido, a ação de reciclar significa algo possível, viável, necessário e urgente. É isso que este livro tem por base.', '["plastic waste","recycling","solid waste","recycling technology","population growth","waste generation","Brazil"]', '10.7476/9788576003601', '9788576003601', 'https://books.scielo.org/id/x6mh4', 'https://books.scielo.org/id/x6mh4/pdf/zanin-9788576003601.pdf', NULL, 'https://books.scielo.org/id/x6mh4/cover/cover_thumbnail.jpeg', NULL, 21, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-x6p69', 'x6p69', 'Como escolher amantes e outros escritos', NULL, '["Benjamim Franklin"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '"Os textos apresentados neste livro são uma pequena amostra desse encanto e humor refinado. Exemplificam um tipo de escrita que Franklin produziu desde quando era um jovem de dezesseis anos até chegar à casa dos oitenta. Esses textos teriam, com certeza, surpreendido Max Weber ou chocado um capitalista devoto como Thomas Mellon. Mas eles dão vida ao perfil convencional de Franklin- na verdade, trazem-no para o ''gozo espontâneo da vida'', de Weber. Com efeito, ensejam àquele retrato na nota de cem dólares abrir um sorriso zombeteiro e permitir-se uma rápida e confiante piscadela." Da Apresentação Biográfica de R. Jack Wilson.', '["Benjamin Franklin","humor","Max Weber","American literature"]', '10.7476/9788539302833', '9788571397194', 'https://books.scielo.org/id/x6p69', NULL, NULL, 'https://books.scielo.org/id/x6p69/cover/cover_thumbnail.jpeg', 124, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
