INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-x78rf', 'x78rf', 'Nos subterrâneos da história: a psicologia na Bahia durante a ditadura militar (1968-1980)', 'a psicologia na Bahia durante a ditadura militar (1968-1980)', '["Rosane Maria Souza e Silva"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro resgata a história da institucionalização da psicologia na Bahia no período da ditadura militar (1968-1980), mostrando como o contexto autoritário da época afetou o desenvolvimento e modos de atuação da psicologia. Fruto de uma consistente pesquisa documental, o livro tece sua teia narrativa histórica e historiográfica entre a política e a psicologia brasileiras, mais especificamente com a história da psicologia na Universidade Federal da Bahia (UFBA). Os resultados são analisados, discutidos e situados em um contexto complexo com usos atentos da literatura e dos conceitos na dimensão analítica e nas conclusões desenvolvidas. Trata-se de uma obra inovadora, original e de grande importância para graduandos(as), professores(as) e pesquisadores(as), podendo contribuir de modo crucial para a elucidação de práticas relacionadas à psicologia no contexto da UFBA.', '["history of psychology","institutionalization of psychology","military dictatorship","Bahia","Universidade Federal da Bahia","psychology and politics","authoritarianism","psychology in Brazil"]', '10.7476/9786556308852', '9786556306124', 'https://books.scielo.org/id/x78rf', 'https://books.scielo.org/id/x78rf/pdf/silva-9786556308852.pdf', NULL, 'https://books.scielo.org/id/x78rf/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-x89sf', 'x89sf', 'Jamais fomos zumbis: contexto social e craqueiros na cidade de São Paulo', NULL, '["Ygor Diego Delgado Alves"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'O livro debruça sua análise sobre o uso do crack na Cracolândia paulistana, espaço símbolo do “craqueiro”, onde se encontram diversos locais de comércio, de uso e mistos. A partir de uma pesquisa baseada na observação participante, o autor teve acesso a informações que de outra maneira não estariam à disposição, preenchendo, desta forma, uma lacuna no conhecimento a respeito do uso do crack.', '["crack cocaine","Cracolândia","São Paulo","social context of drug use","drug trafficking"]', '10.7476/9788523218591', '9788523218591', 'https://books.scielo.org/id/x89sf', 'https://books.scielo.org/id/x89sf/pdf/alves-9788523218591.pdf', NULL, 'https://books.scielo.org/id/x89sf/cover/cover_thumbnail.jpeg', NULL, 15, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-x8xnt', 'x8xnt', 'Saúde para todos, já!', NULL, '["Lana Bleicher","Taís Bleicher"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Com 28 anos de existência, o Sistema Único de Saúde (SUS) marca o estabelecimento do direito à saúde pela Constituição Federal e inicia um processo intenso de revisão das estruturas sanitárias, de financiamento e acesso à saúde pública no Brasil. Nesse livro, o foco recai na apresentação do SUS, em quais são as suas atuais competências, princípios e campos de atuação, além de lançar um olhar mais atento nas questões relativa à saúde bucal e mental dentro deste modelo de saúde pública.', '["right to health","public health system","health care financing","health care access","oral health","mental health","health policy","Brazilian Constitution"]', '10.7476/9788523220051', '9788523220051', 'https://books.scielo.org/id/x8xnt', 'https://books.scielo.org/id/x8xnt/pdf/bleicher-9788523220051.pdf', NULL, 'https://books.scielo.org/id/x8xnt/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-x97jh', 'x97jh', 'Das letras às telas: a tradução intersemiótica de ensaio sobre a cegueira', NULL, '["Cleomar Pinheiro Sotta"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta dissertação apresenta uma leitura comparada entre o romance Ensaio sobre a cegueira (1995), do escritor português José Saramago, e sua adaptação cinematográfica, Blindness (2008), dirigida pelo cineasta brasileiro Fernando Meirelles. A narrativa de Saramago relata os conflitos vividos pelas personagens devido ao aparecimento de um estranho tipo de cegueira – branca e contagiosa – que atinge toda a população de uma cidade desconhecida, com exceção de uma mulher. Para compor essa inusitada situação, o autor se vale de inúmeros recursos, sobretudo da projeção de imagens, as quais podem ser classificadas como demoníacas, apocalípticas e analógicas, de acordo com as categorias estabelecidas pelo crítico Northrop Frye. Muitas dessas imagens, que retratam os sentimentos e os problemas decorrentes da perda da visão, foram selecionadas para a composição do longa-metragem. Tendo em vista que a literatura e o cinema, apesar dos traços em comum, são sistemas semióticos distintos, este trabalho tem por finalidade examinar o tratamento que as imagens presentes no romance de Saramago receberam em sua adaptação cinematográfica, observando semelhanças e diferenças entre a narrativa e o filme', '["Ensaio sobre a cegueira","José Saramago","Fernando Meirelles","intersemiotic translation","visual imagery","Northrop Frye","demon imagery","blindness","vision loss"]', '10.7476/9788579837104', '9788579837104', 'https://books.scielo.org/id/x97jh', 'https://books.scielo.org/id/x97jh/pdf/sotta-9788579837104.pdf', NULL, 'https://books.scielo.org/id/x97jh/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-x9cmm', 'x9cmm', 'A sagração da aparência: o jornalismo da moda na Bahia', NULL, '["Renata Pitombo Cidreira"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra resgata a discussão teórica sobre a moda, indo além do universo fashion e analisando a abordagem que este fenômeno recebe por parte dos meios de comunicação, sobretudo na Bahia, lançando um olhar interpretativo sobre os jornais A Tarde e Tribuna da Bahia. Analisa também os elementos que contribuem para uma possível aproximação entre a moda e a área da comunicação e o olhar pejorativo muitas vezes lançado ao fenômeno da moda, visto como fator de distinção social.', '["fashion journalism","fashion","Bahia","social distinction"]', '10.7476/9788523211547', '9788523208103', 'https://books.scielo.org/id/x9cmm', NULL, NULL, 'https://books.scielo.org/id/x9cmm/cover/cover_thumbnail.jpeg', 229, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-x9ggq', 'x9ggq', 'Introdução e orientações às boas práticas para as Coleções Biológicas Científicas Brasileiras', NULL, '["Luciane Marinoni","Elisandra de Almeida Chiquito","Chirlei Glienke","Clara Baringo Fonseca","Keila Elizabeth Macfadem Juarez","Daniel Silva Basílio","Diego Knop Henriques","Desirrê Alexia Lourenço Petters Vandresen","Gisele dos Santos Morais","Isaac Jorge","Alexandre Dias Pimenta","Anamaria Dal Molin","Aline da Silva Soares Souto","Cléverson Rannieri Meira dos Santos","CRISTIANA SILVEIRA SEREJO","Cristina Maria de Souza‐Motta","Derlene Attili‐Angelis","Fernanda P. Werneck","Fernando Rogério Carvalho","Guilherme Siniciato Terra Garbino","João Renato Stehmann","Leandro Lacerda Giacomin","Maria Aparecida de Jesus","Manuela da Silva","Marcelo Veronesi Fukuda"]', 'Sociedade Brasileira de Zoologia', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Computer Science', 'Em 2021, tendo consciência da importância das coleções biológicas para a conservação e para o conhecimento da biodiversidade brasileira, o Ministério da Ciência, Tecnologia e Inovação (MCTI) solicitou à Sociedade Brasileira de Zoologia que coordenasse o projeto “O papel das Redes de Coleções Zoológicas no aprimoramento e preenchimento de lacunas taxonômicas e geográficas em bases de dados de acesso aberto” junto ao Edital CESP do Global Biodiversity Information Facility (GBIF) (https://www.sibbr.gov.br/page/cesp/cesp-2021.html). O projeto que contou com o financiamento do GBIF, visou fortalecer as coleções zoológicas, fornecendo diretrizes comuns e proporcionando capacitação em ferramentas de gestão para os curadores. Como parceiro do Projeto, o Nó Português do GBFI apoiou as atividades de capacitação, particularmente nos temas de gestão de coleções, limpeza e qualidade de dados. Além do Nó do GBIF Portugal, participaram do Projeto os países Africanos de língua portuguesa: Angola (Nó do GBIF), São Tomé e Príncipe, Moçambique e Cabo Verde. Dando sequência às atividades do projeto, o MCTI, encomentou à SBZ a realização de um diagnóstico de todas as coleções biológicas científicas do Brasil. Este trabalho foi realizado em 2022 em cooperação com a Sociedade Botânica do Brasil (SBB), Sociedade Brasileira de Microbiologia (SBM), Sociedade Brasileira de Virologia (SBV) e sociedades constituintes do Fórum de Sociedades da área de Zoologia. O diagnóstico revelou assimetrias na forma como é feita a manutenção das coleções biológicas científicas, evidenciando a necessidade do estabelecimento de padrões mínimos de gestão e qualidade para orientar os curadores/gerentes/diretores e técnicos. Dessa forma, o presente e-book denominado “Introdução e Orientações às Boas Práticas para as Coleções Biológicas Científicas Brasileiras” tem como principal objetivo oferecer diretrizes para o aperfeiçoamento das coleções biológicas científicas do Brasil abordando aspectos administrativos, de infraestrutura, de recursos humanos e de qualidade necessários para a implementação dos diversos tipos de Coleções Biológicas. Essas recomendações serão a base para que, no futuro, as coleções biológicas científicas brasileiras, especialmente as botânicas e zoológicas, possuam uma linha-base de critérios e padrões a seguir e aperfeiçoar, e que possam, inclusive, receber um selo de qualidade avalizador de sua excelência.', '["zoological collections","best practices","collection management","curator training","data quality","data cleaning","GBIF","biodiversity conservation"]', '10.7476/9786587590042', '9786587590042', 'https://books.scielo.org/id/x9ggq', 'https://books.scielo.org/id/x9ggq/pdf/marinoni-9786587590042.pdf', NULL, 'https://books.scielo.org/id/x9ggq/cover/cover_thumbnail.jpeg', NULL, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-x9qvt', 'x9qvt', 'Religiosidade na Revolução Francesa', NULL, '["Ignasi Terradas Saborit"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro aborda o estudo da relação Religião-Revolução num caso paradigmático: a Revolução Francesa. Tentamos compreender as colocações e a mentalidade da época sem descuidar de uma teoria histórica do fenômeno teoria que nos parece próxima da tradição marxista. Ao mesmo tempo, nos empenhamos em proporcionar uma reflexão útil para a consciência que se tem dos fenômenos religiosos em países como o Brasil, onde a Religião é protagonista de destaque nas mudanças e conflitos sociais. [trecho retirado da introdução do livro]', '["religiosity","French Revolution","religion and revolution","historical consciousness","Marxist theory of religion","social conflict","religion in Brazil"]', '10.7476/9788599662984', '9788599662984', 'https://books.scielo.org/id/x9qvt', 'https://books.scielo.org/id/x9qvt/pdf/saborit-9788599662984.pdf', NULL, 'https://books.scielo.org/id/x9qvt/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-x9z8z', 'x9z8z', 'Ecopolítica das mudanças climáticas: o IPCC e o ecologismo dos pobres', NULL, '["Petronio de Tilio Neto"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'Este é um trabalho sobre a ecopolítica internacional das mudanças climáticas. Ele trata dos conflitos de interesses entre os Estados no que diz respeito a questões ambientais mais especificamente, no que diz respeito às alterações do clima terrestre. Nas últimas décadas e séculos o ser humano tem alterado a composição da atmosfera, fazendo com que o sistema climático se aqueça e se modifique. Portanto cabe ao ser humano entender o problema, avaliar suas conseqüências e desenvolver medidas de resposta. Para auxiliar nesses esforços na esfera internacional foi criado o IPCC, Painel Intergovernamental sobre Mudança do Clima. Sua função é dar as bases científicas necessárias para a tomada de decisões políticas que afetem o clima. Nesse sentido o IPCC está incumbido de tratar de questões relevantes para a política, sem no entanto interferir na tomada de decisões. Este estudo questiona justamente se o IPCC tem sido neutro como deveria ao expor os impactos das mudanças climáticas e ao apontar possíveis medidas de resposta. O recorte analítico selecionado para investigar essa questão é o Ecologismo dos Pobres, segundo o qual as sociedades humanas seriam marcadas pela desigualdade na distribuição dos benefícios e dos custos ambientais. Observando os relatórios do IPCC sob essa ótica foi possível encontrar indícios de que esse Painel talvez não seja tão neutro do ponto de vista político quanto afirma ser. Talvez ele não seja imune às disputas políticas entre os Estados. Como conseqüência o IPCC pode não ser a alternativa mais eficaz para responder às mudanças climáticas no âmbito internacional', '["environmental politics","climate change","IPCC","climate politics","global environmental governance"]', '10.7476/9788579820496', '9788579820496', 'https://books.scielo.org/id/x9z8z', 'https://books.scielo.org/id/x9z8z/pdf/tilio-9788579820496.pdf', NULL, 'https://books.scielo.org/id/x9z8z/cover/cover_thumbnail.jpeg', NULL, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-x9zb2', 'x9zb2', 'Entre experiências e saberes: transições de estudantes em mobilidade acadêmica', 'transições de estudantes em mobilidade acadêmica', '["Karla Maria Lima Figueiredo Bené Barbosa"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra é pautada por questões relacionadas ao universo da mobilidade acadêmica no cenário da internacionalização do ensino superior, analisando as transições de desenvolvimento, as estratégias de afiliação empreendidas e as experiências e influências na vida dos estudantes de graduação. O foco da obra volta-se para as práticas de internacionalização desenvolvidas em uma universidade pública baiana, para compreender como a mobilidade estudantil internacional colabora para a formação universitária e o desenvolvimento humano. Experienciar a mobilidade possibilita aos estudantes a interpretação de um outro mundo. Graças ao suporte teórico do internacionalismo simbólico, foi possível olhar e compreender as aquisições desenvolvimentais dos estudantes intercambistas, produzidas como um habitus internamente em renovação, que se enriquece de experiências novas, de transições e passagens.', '["academic mobility","internationalization of higher education","student transition","habitus","student exchange","undergraduate students","human development","university education","Brazilian public universities"]', '10.7476/9788555921629', '9786589524816', 'https://books.scielo.org/id/x9zb2', 'https://books.scielo.org/id/x9zb2/pdf/barbosa-9788555921629.pdf', 'https://books.scielo.org/id/x9zb2/epub/barbosa-9788555921629.epub', 'https://books.scielo.org/id/x9zb2/cover/cover_thumbnail.jpeg', 249, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xbcsk', 'xbcsk', 'Auxílio-acidente e saúde do trabalhador', NULL, '["Carlos Eduardo Soares de Freitas"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Neste livro, o autor nos apresenta o resultado de sua carreira junto à realidade dos trabalhadores na busca por seus direitos, especialmente o direito ao auxílio-acidente. Sua trajetória é iniciada como advogado sindicalista, na defesa de trabalhadores do polo petroquímico de Camaçari-BA, fato que despertou nele a necessidade de conhecer mais profundamente as demandas e os caminhos que os trabalhadores acidentados precisam trilhar para acessar o benefício concedido pelo INSS. Os interessados na obra encontrarão, portanto, um importante referencial para compreender o atual cenário jurídico, social e político em torno do acesso a esse direito do trabalhador, a partir do olhar de um pesquisador envolvido há mais de 25 anos com o tema', '["INSS","employee health","occupational accidents","workers'' rights","labor movement","petrochemical workers","Camaçari"]', '10.7476/9788523218751', '9788523218751', 'https://books.scielo.org/id/xbcsk', 'https://books.scielo.org/id/xbcsk/pdf/freitas-9788523218751.pdf', NULL, 'https://books.scielo.org/id/xbcsk/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xc796', 'xc796', 'Um manicômio em colapso: da aridez do abandono à fluidez da liberdade', NULL, '["Fernando Sfair Kinker"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Neste livro, Fernando Kinker reflete sobre a experiência de transformação de um hospital psiquiátrico localizado em uma cidade do interior nordestino. Para isso relata o processo de intervenção federal que lá se deu em 2005 e discute o papel do manicômio na sociedade contemporânea.', '["psychiatric hospitals","hospital closures","mental health services","federal intervention","social change"]', '10.7476/9786557080863', '9786557080252', 'https://books.scielo.org/id/xc796', NULL, NULL, 'https://books.scielo.org/id/xc796/cover/cover_thumbnail.jpeg', 121, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xccnw', 'xccnw', 'Escrita infantil: junção e tradição discursiva', NULL, '["Lúcia Regiane Lopes-Damásio"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Resultado de pesquisas realizadas na Universidade Estadual Paulista (Unesp), da graduação à pós-graduação, esta obra apresenta, de forma leve e objetiva, um modo de olhar para a escrita infantil, capaz demonstrar a riqueza com que essa escrita se apresenta a quem se dispõe a vê-la sem as lentes da gramática projetada para a escrita padrão. Para reconhecer as relações entre mecanismos de junção e tradições de textos, a abordagem teórico-metodológica aqui propõe a conjugação de aspectos linguísticos e discursivos. Nesse espaço, os mecanismos de junção deixam de ser tomados exclusivamente como categorias linguísticas e ganham estatuto de rastros da circulação do sujeito por sua imagem da escrita. Esses rastros permitem o reconhecimento, no material escrito, da movimentação do sujeito para a construção dos sentidos na textualização. Nesta obra, a riqueza com que a escrita infantil se mostra ao leitor deixará clara a importância da investigação proposta, não unicamente para a compreensão do caráter heterogêneo da/dessa escrita, mas também para futuras proposições que favoreçam o seu ensino.', '["children''s writing","discourse traditions","textualization","subjectivity in writing","meaning-making","writing instruction"]', '10.7476/9786557143032', '9786557143032', 'https://books.scielo.org/id/xccnw', 'https://books.scielo.org/id/xccnw/pdf/lopes-9786557143032.pdf', NULL, 'https://books.scielo.org/id/xccnw/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xchrm', 'xchrm', 'Entre o ouvido e a voz', NULL, '["Rodrigo Spina de Oliveira Castro"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro tem como objetivo primeiro compreender a relação entre o sentido da audição e as vocalidades do ator contemporâneo. O estudo percorreu aspectos evolutivos, fisiológicos, cognitivos e psíquicos, para que, em um segundo momento, fossem realizadas experiências práticas com diversos atores. O trabalho foi centrado no conceito de Encontro Vocal, que vincula toda emissão da voz ao que o ator escuta de um outro, pelo qual ele recebe novos materiais pelas ressonâncias no espaço, dilatando suas percepções de forma integral, redimensionando sua poética por meio de uma conexão sensível entre as fisiologias em estado de criação, em estímulos sonoros percebidos e trocados. Um segundo conceito, aqui chamado Ser Substantivo, abarca um território de investigação íntima e vertical, que antecede a organização formal das vocalidades no corpo do ator, por meio da sensibilização auditiva. Além desses conceitos, alguns outros temas, como silêncio, respiração, comunicação e a palavra cênica, tangenciaram a análise. Como objeto de estudos de diversos pesquisadores da voz, esses temas foram aqui revisitados pela perspectiva da audição.', '["voice","auditions","actor''s voice","silence","breathing","vocal physiology","voice perception","actor training"]', '10.7476/9788526816640', '9788526815742', 'https://books.scielo.org/id/xchrm', NULL, NULL, 'https://books.scielo.org/id/xchrm/cover/cover_thumbnail.jpeg', 222, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xcwmn', 'xcwmn', 'Nascimento Prematuro: repercussões no desenvolvimento integral', NULL, '["Méio, Maria Dalva Barbosa Baker","Morsch, Denise Streit"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Este volume é fruto do intenso e comprometido trabalho do Ambulatório de Seguimento do Instituto Nacional de Saúde da Mulher, da Criança e do Adolescente Fernandes Figueira (IFF/Fiocruz), um dos primeiros ambulatórios especializados no acompanhamento de crianças egressas de internação neonatal do Brasil, que ao longo de décadas tem não só cuidado de crianças e de suas famílias como também formado pessoas. Foi acompanhando essas crianças, ouvindo as histórias e dificuldades de seus familiares e, ao mesmo tempo, percebendo a necessidade de fornecer um arcabouço teórico para profissionais que trabalham com o seguimento especializado de crianças que Maria Dalva Barbosa Baker Méio e Denise Streit Morsch tiveram motivação e inspiração para organizar e escrever, junto com outros especialistas, esta obra.', '["preterm birth","neonatal intensive care","follow-up care","child development","family support"]', '10.7476/9786557082195', '9786557081822', 'https://books.scielo.org/id/xcwmn', NULL, NULL, 'https://books.scielo.org/id/xcwmn/cover/cover_thumbnail.jpeg', 303, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xdm8s', 'xdm8s', 'Quadros e programas institucionais em políticas públicas', NULL, '["Delma Pessanha Neves","Ramonildes Alves Gomes","Pedro Fonseca Leal"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O conjunto de textos agregados nesta coletânea incide sobre reflexões em torno do tema políticas públicas, a partir de investimentos de pesquisa, demonstrativos dos múltiplos espaços de definição de regras para circulação de recursos e de formulação de ideários voltados para construção de comportamentos esperados. Por eles, valoriza-se a criação de redes interdependentes de aparatos institucionais correspondentes aos objetivos delineados. Considera-se, ainda, a formação de agentes sociais capazes de operar na formulação e realimentação de ideais que permitam que os objetivos sejam reconhecidos na capilaridade das práticas cotidianas.', '["public policy","institutional framework","policy programs","institutional networks","social actors","policy feedback","everyday practices"]', '10.7476/9788578792787', '9788578792787', 'https://books.scielo.org/id/xdm8s', 'https://books.scielo.org/id/xdm8s/pdf/neves-9788578792787.pdf', NULL, 'https://books.scielo.org/id/xdm8s/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xf7vy', 'xf7vy', 'Plantas medicinais', NULL, '["Mara Zélia de Almeida"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'other', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'Plantas Medicinais colabora com a preservação e multiplicação das informações obtidas em trabalhos comunitários acerca do uso de plantas para fins medicinais, com o devido respeito às tradições da herança cultural africana na medicina do Brasil. As indicações terapêuticas tradicionais indicam plantas para fins medicinais que extrapolam em muito a terapêutica convencional, assumindo, em determinados momentos, um caráter místico, embasado em crenças culturais inerentes ao grupo étnico. A visão do homem, como ser integral, respeitado em seu momento de fragilidade, quando algum mal de origem psíquica ou somática lhe aflige, destaca-se como a principal ótica para o entendimento deste trabalho.', '["medicinal plants","traditional medicine","African cultural heritage","ethnobotany","community knowledge","cultural beliefs"]', '10.7476/9788523212162', '9788523212162', 'https://books.scielo.org/id/xf7vy', 'https://books.scielo.org/id/xf7vy/pdf/almeida-9788523212162.pdf', NULL, 'https://books.scielo.org/id/xf7vy/cover/cover_thumbnail.jpeg', NULL, 23, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xfkcq', 'xfkcq', '(Re)descobriram o Ceará? Representações dos sítios históricos de Icó e Sobral: entre areal e patrimônio nacional', NULL, '["José Clewton do Nascimento"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '(Re)descobriram o Ceará? foi premiado pelo VI Prêmio Brasileiro Política e Planejamento Urbano e Regional da ANPUR como melhor tese de doutorado defendida no período de fevereiro de 2007 a março de 2009. Esta obra, desenvolvida cuidadosamente por José Clewton do Nascimento, propõe uma discussão acerca das transformações do Estado do Ceará, sejam elas de caráter urbano, social, cultural ou representativo. É proposta, aqui, uma análise crítica do cotidiano das cidades, do patrimônio e do turismo, tendo como ponto de partida as cidades sertanejas cearenses de Icó e Sobral, ambas tombadas pelo IPHAN.', '["initial coin offerings","Sobral, Ceará","Ceará","historic sites","heritage","national heritage","heritage tourism","IPHAN","urban transformation","everyday life","representation of the past"]', '10.7476/9788523211509', '9788523207823', 'https://books.scielo.org/id/xfkcq', NULL, NULL, 'https://books.scielo.org/id/xfkcq/cover/cover_thumbnail.jpeg', 446, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xft4h', 'xft4h', 'Domingos Caldas Barbosa: descrição da Quinta de Belas', NULL, '["Luiza Sawaya","Vítor Serrão","Correia, Ana Isabel"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta edição traz a lume a importante obra de Domingos Caldas Barbosa que permanecia praticamente esquecida do público contemporâneo, mesmo dos estudiosos brasileiros e portugueses: sua preciosa descrição da célebre Quinta de Belas. A edição conta com Glossário Botânico, de autoria de Ana Isabel Correia, textos críticos de Luiza Sawaya e Vítor Serrão, e caderno de imagens.', '["plant descriptions","18th-century botany","colonial Brazil","botanical illustration","history of botany"]', '10.7476/9788595463271', '9788595463271', 'https://books.scielo.org/id/xft4h', 'https://books.scielo.org/id/xft4h/pdf/sawaya-9788595463271.pdf', NULL, 'https://books.scielo.org/id/xft4h/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xg9wp', 'xg9wp', 'Psicologia social e pessoalidade', NULL, '["Mary Jane Paris Spink","Pedro Figueiredo","Jullyane Chagas Barboza Brasilino"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro apresenta onze ensaios que exercitam a analítica de nossos modos humanos de viver. Ou seja, não se trata apenas de buscar as várias maneiras de conceituar o ser humano, mas de ver nas palavras/saberes as ações/fazeres que juntos se materializam no efeito de ser pessoa.', '["social psychology","personal identity","personhood","human existence","lifestyle","concept of the human being"]', '10.7476/9788579820571', '9788579820571', 'https://books.scielo.org/id/xg9wp', 'https://books.scielo.org/id/xg9wp/pdf/spink-9788579820571.pdf', NULL, 'https://books.scielo.org/id/xg9wp/cover/cover_thumbnail.jpeg', NULL, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xgjbb', 'xgjbb', 'O Lagarto e a Rosa no asfalto: odontologia dos desejos e das vaidades', NULL, '["Adauto Oliveira Emmerich","Luís David Castiel"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Os belos sorrisos que estampam as propagandas não deixam entrever o quão complexas podem ser as relações da odontologia com a sociedade contemporânea. A ciência e a clínica odontológica têm entre si e com a sociedade capitalista consumista relações biopolíticas, marcadas por disputas epistêmicas e de poder. Nesse contexto, novos produtos e procedimentos médico-odontológicos são crescentemente oferecidos como mercadorias e desejados por razões de ordem estética e cosmética. Enquanto isso, fica cada vez mais de lado a discussão sobre as necessidades de saúde pública e as iniquidades de acesso aos bens e serviços odontológicos, acentuando-se um comprometimento ético-político neoliberal da prática odontológica. Para compreender a odontologia e seus dispositivos na sociedade atual – ou da modernidade tardia –, os autores optaram por uma abordagem no campo multidisciplinar dos social studies of science. O resultado de suas análises pode ser conferido neste livro, que coloca o desafio de reconciliar, em uma perspectiva analítica, as intenções teóricas e a prática da odontologia, seus interesses políticos e suas bases científicas.', '["biopolitics","consumerism","esthetic dentistry","access to dental care","public health","neoliberalism","power relations","social studies of science","late modernity","dental ethics"]', '10.7476/9788575415733', '9788575414217', 'https://books.scielo.org/id/xgjbb', NULL, NULL, 'https://books.scielo.org/id/xgjbb/cover/cover_thumbnail.jpeg', 120, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xgjh9', 'xgjh9', 'Ética sexual y estética de la existencia en la antigua Grecia: reflexiones sobre la homosexualidad desde Focault', NULL, '["Rubén Darío Montoya Gómez"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2012, '2012-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este texto se pregunta ¿cuál es la propuesta de Foucault respecto a la experiencia de la homosexualidad actual? La hipótesis de trabajo surge de la siguiente deducción: si la experiencia de la homosexualidad genera una ética sexual y una estética de la existencia, tanto en la Antigua Grecia como en la actualidad, entonces la interrogación por la homosexualidad conlleva a una pregunta por la constitución del sujeto. Para abordar esta cuestión, es necesario entender el análisis del autor sobre la ética sexual en la Antigua Grecia centrada en la relación amorosa entre hombres libres. A partir de la noción griega de una estética de la existencia, es posible reflexionar sobre los peligros que acechan a los movimientos homosexuales con la entrada en el ámbito de lo público, la adquisición de derechos y una política de la identidad. Estos movimientos se han integrado a las instituciones sociales hegemónicas a las que pretendían resistir y al dispositivo de la sexualidad al que pretendían oponerse. En esa línea, se encuentran actualmente los estudios de género, LGBTI y queer replanteando los modos de resistencia a partir del pensamiento de Foucault y la estilización de la libertad, la identidad y los placeres.', '["Michel Foucault","homosexuality","ancient Greece","sexual ethics","aesthetics of existence","subjectivation","gay rights movement","queer theory","identity politics","public sphere","pleasure"]', '10.7476/9789585003965', '9789585003965', 'https://books.scielo.org/id/xgjh9', 'https://books.scielo.org/id/xgjh9/pdf/montoya-g%C3%B3mez-9788579820205.pdf', NULL, 'https://books.scielo.org/id/xgjh9/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xgzng', 'xgzng', '''Nosso remédio é a palavra'': uma etnografia sobre o modelo terapêutico de Alcoólicos Anônimos', NULL, '["Edemilson Antunes de Campos"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Os assim chamados ‘doentes alcoólicos’ produzem continuamente falas sobre eles mesmos, não apenas porque o alcoolismo é um problema social e médico das sociedades contemporâneas, mas também porque as associações de ‘adictos’, tais como Alcoólicos Anônimos (A.A.), são um fenômeno em franco desenvolvimento, que, a cada dia, desafiam as ciências sociais e médicas. A obra trata do modo como os integrantes de grupos de mútua ajuda de A.A. vivem e gerenciam a chamada doença alcoólica e como lutam contra as recaídas. Enfoca o modelo terapêutico desenvolvido por tais grupos, tomando por base pesquisa etnográfica realizada na zona leste da cidade de São Paulo – com ênfase nos significados atribuídos ao alcoolismo –, nas relações sociais nas quais o alcoólico está inserido e na repercussão na esfera familiar.', '["Alcoholics Anonymous","self-help groups","alcoholism","treatment model","meaning of illness","family impact of alcoholism","São Paulo"]', '10.7476/9788575413418', '9788575411902', 'https://books.scielo.org/id/xgzng', NULL, NULL, 'https://books.scielo.org/id/xgzng/cover/cover_thumbnail.jpeg', 192, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xhjwd', 'xhjwd', 'El interés público en América Latina. Reflexiones desde la educación legal clínica y el trabajo probono', NULL, '["Torres Villarreal, María Lucía","Paola Marcela Iregui Parra","Sebastián Senior Serrano"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'El derecho se entiende hoy como una herramienta idónea para producir cambios en las sociedades y atender las necesidades y desafíos modernos, lo cual era casi impensable hace algunos años; se concibe como un medio para formar profesionales, pero, ante todo, abogados que son conscientes de su rol transformador en un contexto social con amplias necesidades. Por ello, la preocupación actual de las universidades y organizaciones sociales en el mundo, es formar líderes propositivos, apropiados de su papel como ciudadanos, con gran sentido social y de pertenencia, con destacadas habilidades para incidir en la formación de leyes, sentencias y políticas públicas, y resolver problemas cotidianos de grandes y pequeñas comunidades y emprender litigios a lo largo y ancho del mundo. Así, las universidades han empezado a actualizar sus currículos y las formas de enseñar el Derecho, implementando nuevos modelos pedagógicos que brindan a los futuros profesionales elementos necesarios para responder a las necesidades de su contexto social y del mundo moderno. En este libro, profesores de América Latina y España reflexionan alrededor del trabajo ProBono, la educación legal clínica y el litigio estratégico, como herramientas para la defensa del interés público, la transformación social, el acceso a la justicia de los grupos vulnerables y la protección de los derechos humanos.', '["public interest","clinical legal education","pro bono services","strategic litigation","access to justice","vulnerable populations","human rights","social change","legal education curriculum","Latin America"]', '10.7476/9789587386806', '9789587386936', 'https://books.scielo.org/id/xhjwd', NULL, NULL, 'https://books.scielo.org/id/xhjwd/cover/cover_thumbnail.jpeg', 564, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xhr84', 'xhr84', 'Informações e registros em saúde e seus usos no SUS', NULL, '["Bianca Borges da Silva Leandro","Flávio Astolpho Vieira Souto Rezende","José Mauro da Conceição Pinto"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'Integrante da coleção Fazer Saúde da Editora Fiocruz, a obra aborda as constantes mudanças nos sistemas de informação em saúde. Iniciativas como aplicativos na área da saúde, utilização de sistemas de informação em saúde via web, o desenvolvimento do Programa Telessaúde Brasil Redes, a expansão do cartão nacional de saúde (CNS), o desenvolvimento e avanços dos prontuários e registros eletrônicos são algumas das estratégias desenvolvidas nas esferas municipal, estadual e federal que permeiam o cotidiano de trabalho de muitos profissionais da saúde. Organizado por pesquisadores da Fiocruz, o livro ressalta que, para que as informações e registros em saúde tenham um papel estratégico no Sistema Único de Saúde (SUS), são essenciais a reflexão e a discussão sobre os processos de trabalho dos profissionais da área, a partir dos campos de sistemas de informação e da gestão de documentos nos serviços de saúde.', '["health information systems","health records","electronic health records","Unified Health System (SUS)","health apps","web-based health information system"]', '10.7476/9786557080177', '9786557080030', 'https://books.scielo.org/id/xhr84', NULL, NULL, 'https://books.scielo.org/id/xhr84/cover/cover_thumbnail.jpeg', 176, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xjbf8', 'xjbf8', 'Biossegurança: uma abordagem multidisciplinar', NULL, '["Pedro Teixeira","Silvio Valle"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Primeira publicação brasileira sobre biossegurança chega à segunda edição com novos capítulos e atualizações. Aborda desde a história das revoluções sanitárias, que levaram a Humanidade a enfrentar epidemias e desenvolver as noções de transmissão, contágio e prevenção de doenças, até questões das últimas descobertas científicas e tecnológicas. Aplicações da internet em biossegurança e acidentes em unidades de assistência médica estão entre os novos temas em debate. Discute, ainda, a criação de mapas de riscos, segurança em biotérios, ergonomia e biossegurança em laboratórios, política de biossegurança, biotecnologia e doenças emergentes.', '["biosafety","epidemics","disease transmission","disease prevention","medical accidents","risk mapping","laboratory biosafety","biosafety policy","biotechnology","emerging infectious diseases"]', '10.7476/9788575413067', '9788575412022', 'https://books.scielo.org/id/xjbf8', NULL, NULL, 'https://books.scielo.org/id/xjbf8/cover/cover_thumbnail.jpeg', 442, 20, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xjcw9', 'xjcw9', 'Produção do cuidado no Programa Saúde da Família: olhares analisadores em diferentes cenários', NULL, '["Marluce Maria Araújo Assis","Maria Ângela Alves do Nascimento","Túlio Batista Franco","Maria Sálete Bessa Jorge"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'O livro discute as políticas públicas na área de cultura, no período dos anos 60 aos anos 90, demonstrando como os símbolos afro-brasileiros foram sendo ressignificados, a partir do estabelecimento de novas demandas, seja pela política institucional ou pelos movimentos negros. Trata-se de um estudo pioneiro, principalmente quando analisadas a dinâmica da sociedade brasileira e as mudanças na adoção da simbologia de origem africana por distintos atores sociais.', '["Family Health Strategy","health care production","public health policy"]', '10.7476/9788523208776', '9788523208776', 'https://books.scielo.org/id/xjcw9', 'https://books.scielo.org/id/xjcw9/pdf/assis-9788523208776.pdf', NULL, 'https://books.scielo.org/id/xjcw9/cover/cover_thumbnail.jpeg', NULL, 11, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xjx2y', 'xjx2y', 'Traçando caminhos em uma sociedade violenta: a vida de jovens infratores e de seus irmãos não-infratores', NULL, '["Simone Gonçalves de Assis"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1999, '1999-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Objetiva aprofundar o conhecimento sobre a violência praticada por jovens, com base, dentre outras, na seguinte pergunta: por que, na mesma família, somente alguns desenvolvem comportamento delinquente? Foram escolhidos Rio de Janeiro e Pernambuco, com incidência elevada de infrações juvenis, para olhar mais de perto o universo daqueles que cometeram delitos e de suas famílias - que, muitas vezes, não estão envolvidas na criminalidade. Foram entrevistados 61 adolescentes infratores internos em quatro instituições (três no Rio, uma em Recife) e 31 de seus irmãos ou primos que afirmaram nunca terem cometidos atos infracionais. Parte de seus depoimentos está publicada nesta obra que busca compreender tais jovens, suas angústias e anseios na vivência do presente e construção do futuro.', '["juvenile delinquency","violent youth","family influence on delinquency","juvenile detention","adolescent life","Rio de Janeiro","Pernambuco"]', '10.7476/9788575412800', '9788575412800', 'https://books.scielo.org/id/xjx2y', 'https://books.scielo.org/id/xjx2y/pdf/assis-9788575412800.pdf', NULL, 'https://books.scielo.org/id/xjx2y/cover/cover_thumbnail.jpeg', NULL, 23, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xktw6', 'xktw6', 'Entre controvérsia e hegemonia: os transgênicos na Argentina e no Brasil', 'os transgênicos na Argentina e no Brasil', '["Renata Motta"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A autora faz um estudo comparativo da expansão do cultivo de produtos geneticamente modificados nos dois países, que se tornaram grandes produtores de soja e se inseriram na economia global. O estudo mostra os caminhos e questiona por que os governos de esquerda tomaram rumo contrário ao esperado pelos ambientalistas e movimentos camponeses e de agricultura familiar (a partir de 2003, no Brasil, e em 2012, na Argentina) e cederam à pressão do agronegócio. Foram ouvidos ativistas de movimentos sociais envolvidos nas lutas contra as sementes transgênicas, cientistas, ambientalistas, organizações de defesa do consumidor e jornalistas. A partir desta base, a pesquisadora utilizou referenciais teóricos das ciências sociais e outros, numa perspectiva interdisciplinar. O prefácio de Marcelo Firpo Porto, pesquisador da Fundação Oswaldo Cruz, situa bem o trabalho. “Fica claro o quanto as lógicas da democracia representativa e da tecnociência, em nome de um conhecimento especializado dito universal, funcionam totalmente atreladas aos interesses de mercado e influenciam importantes políticas públicas. Ao mesmo tempo, servem para silenciar críticas e desvalorizar a construção de alternativas, nesse caso outro modelo de agricultura familiar vinculado à agroecologia, à reforma agrária e à soberania alimentar”, destaca Firpo. Renata Motta trata do papel do Estado no capitalismo contemporâneo, visto em alguns diagnósticos como administrador dos mercados financeiros e menos como garantidor de direitos. E afirma a necessidade de uma luta política emancipatória, por acreditar que, sem mobilização social, o capitalismo global trará ainda mais desigualdades e diminuição de direitos.', '["genetically modified crops","transgenic seeds","soybean cultivation","agribusiness","left-wing governments","land reform","food sovereignty","agroecology","peasant movements","social movements","state and capitalism","public policy"]', '10.7476/9786557082980', '9788575416181', 'https://books.scielo.org/id/xktw6', 'https://books.scielo.org/id/xktw6/pdf/motta-9786557082980.pdf', NULL, 'https://books.scielo.org/id/xktw6/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xkvy4', 'xkvy4', 'Saúde e ambiente sustentável: estreitando nós', NULL, '["Maria Cecília de Souza Minayo","Ary Carvalho de Miranda"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2002, '2002-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'A obra apresenta conceitos que estruturam a relação entre saúde e meio ambiente no Brasil, tomando como base os dez anos da Conferência das Nações Unidas sobre o Meio Ambiente e Desenvolvimento (Rio-92), na qual foi aprovada a Agenda 21 - documento que contém os compromissos para mudança nos padrões de desenvolvimento deste século. O livro contém reflexões de especialistas de diversas áreas do conhecimento, que avaliam a atual situação brasileira e apresentam sugestões para serem utilizadas na elaboração de um Programa Nacional de Desenvolvimento em consonância com a Agenda 21. A coletânea está dividida em cinco partes: ambiente, espaço, território: o olhar da saúde; dialogando com o risco; qualidade de vida e promoção da saúde; processos produtivos, consumo e degradação da saúde e do ambiente; indicadores em saúde e ambiente: construção conceitual.', '["health-environment relationship","sustainable development","Agenda 21","national development programs","environmental health","quality of life","health promotion","environmental risk","Brazil"]', '10.7476/9788575413661', '9788575413661', 'https://books.scielo.org/id/xkvy4', 'https://books.scielo.org/id/xkvy4/pdf/minayo-9788575413661.pdf', NULL, 'https://books.scielo.org/id/xkvy4/cover/cover_thumbnail.jpeg', NULL, 29, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xky8j', 'xky8j', 'Desamparo psíquico nos filhos de dekasseguis no retorno ao Brasil', NULL, '["Cizia Célia Fernandes Pereira Resstel"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'O fenômeno dekassegui tem se destacado no Brasil pelo expressivo contingente de descendentes de japoneses que se desloca para o Japão, em busca de trabalho e de uma poupança financeira, e retorna novamente. Muitos refazem esse ciclo mais de uma vez, em sucessivas idas e vindas, caracterizando um movimento pendular. Esse livro, derivado de uma dissertação de mestrado, aborda a experiência de retorno ao Brasil, do migrante dekassegui, particularmente dos filhos desses migrantes, que acompanharam seus pais nessa saga migratória, ainda pequenos, alguns tendo nascidos no Japão. São relatados e analisados casos de crianças e adolescentes, destacando-se suas dificuldades e desafios no processo de integração ou de reintegração à cultura brasileira, que emergem principalmente no contato deles com o ambiente escolar. O desamparo psíquico no processo de adaptação/readaptação dos filhos de dekasseguis na chegada ao Brasil pôde ser identificado nas crianças e também nos próprios pais dekasseguis. Os pais sentem-se desamparados antes mesmo de retornarem para o Brasil. São inúmeras as dificuldades da família dekassegui na chegada ao Brasil, potencializadas por um sentimento de estranhamento do ambiente que antes era bastante familiar e de um estranhamento de si mesmo. Além disso, os pais se defrontam com a questão da identidade cultural de seus filhos, fortemente enraizada na cultura japonesa, o que não se tornava tão evidente quando viviam no Japão. A língua será o principal indicador das raízes mais profundas da identidade cultural dos filhos e o desafio maior a ser enfrentado. Também o fator idade, o tempo de permanência no exterior e o grau de escolaridade em que essas crianças se encontram no ato da imigração acabam contribuindo para as dificuldades de adaptação/readaptação à escola. No entanto, apesar de muitas dificuldades e desafios a serem enfrentados, os dekasseguis e seus filhos trazem consigo, no retorno, um capital cultural inestimável que precisa ser valorizado e aproveitado.', '["Japanese immigrants in Brazil","return migration","immigrant children","psychological support","cultural identity","school reintegration","cultural capital","Japanese Brazilians","immigrant families","language barriers","childhood and adolescence","intergenerational migration"]', '10.7476/9788579836749', '9788579836749', 'https://books.scielo.org/id/xky8j', 'https://books.scielo.org/id/xky8j/pdf/resstel-9788579836749.pdf', NULL, 'https://books.scielo.org/id/xky8j/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xm83s', 'xm83s', 'Atenção primária à saúde na coordenação do cuidado em regiões de saúde', NULL, '["Patty Fidélis de Almeida","Adriano Maia dos Santos","Mariluce Karla Bomfim de Souza"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'Resultado de estudos realizados em três municípios sede (Feira de Santana, Santo Antônio de Jesus e Vitória da Conquista), o título apresenta contribuições teóricas de investigadores no debate sobre Atenção Primária à Saúde (APS) para subsidiar diferentes aspectos sobre o tema. O livro também apresenta os resultados da pesquisa realizada no estado da Bahia, apontando os principais desafios e possibilidades para coordenação do cuidado em municípios sede de regiões de saúde.', '["primary care","care coordination","health regions","regional health coordination","health system challenges","Bahia"]', '10.7476/9788523218768', '9788523218768', 'https://books.scielo.org/id/xm83s', 'https://books.scielo.org/id/xm83s/pdf/almeida-9788523218768.pdf', NULL, 'https://books.scielo.org/id/xm83s/cover/cover_thumbnail.jpeg', NULL, 14, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xmznq', 'xmznq', 'Palavra banto em Minas', NULL, '["Sônia Maria De Melo Queiroz"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A memória dos africanos de línguas e culturas banto no Brasil, muito pouco difundida entre a população em geral, vem sendo preservada em comunidades negras hoje designadas quilombos, nas quais ainda se podem encontrar falares e cantares com base lexical de origem banto. Nesses falares e cantares, podemos ouvir a palavra dos ancestrais transmitida em línguas rituais resultantes do contato entre africanos e portugueses e preservada como forma de resistência diante da imposição da língua e cultura europeia pelo Estado. Estão reunidas neste livro todas as palavras de provável origem banto encontradas nos vocabulários e glossários elaborados por pesquisadores a partir da observação em comunidades onde se fala essa mescla linguística em território mineiro. Também identificamos os registros dessas palavras emdicionários e glossários brasileiros, na literatura angolana e em dicionários de quicongo, quimbundo e umbundo, as três línguas banto mais faladas no Brasil. A publicação deste glossário em forma de livro é o resultado de uma coleta que buscou realizar uma arqueologia do contato entre línguas africanas do grupo banto e a língua portuguesa no Brasil.', '["Bantu languages","lexical borrowing","quilombola communities","Afro-Brazilian languages","glossary","Minas Gerais","language contact","cultural resistance","ritual language"]', '10.7476/9786580010035', '9786580010035', 'https://books.scielo.org/id/xmznq', 'https://books.scielo.org/id/xmznq/pdf/queiroz-9786580010035.pdf', NULL, 'https://books.scielo.org/id/xmznq/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xnfq4', 'xnfq4', 'Habitação e poder: da fundação da casa popular ao Banco Nacional da Habitação', NULL, '["Sérgio de Azevedo","Luís Aureliano Gama de Andrade"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'É objetivo deste estudo explorar os aspectos que têm constituído o cerne da política de habitação popular nas últimas três décadas. Para tal, privilegia-se a análise da Fundação da Casa Popular e do Banco Nacional da Habitação, que são, no período em pauta, a matriz da política habitacional.[...]', '["housing policy","popular housing","housing banks","social housing"]', '10.7476/9788579820557', '9788579820557', 'https://books.scielo.org/id/xnfq4', 'https://books.scielo.org/id/xnfq4/pdf/azevedo-9788579820557.pdf', NULL, 'https://books.scielo.org/id/xnfq4/cover/cover_thumbnail.jpeg', NULL, 29, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xns62', 'xns62', 'Salas abertas: formação de professores e práticas pedagógicas em comunicação alternativa e ampliada nas salas de recurso multifuncionais', NULL, '["Leila Regina d’Oliveira de Paula Nunes","Carolina Rizzotto Schirmer"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O presente livro se constitui em uma importante publicação para nossa Rede Pública Municipal de Ensino, principalmente por abordar uma experiência de formação que se caracterizou pela valorização de saberes e práticas pedagógicas de professores que atuam em um espaço que ganha centralidade no processo de inclusão: a Sala de Recursos Multifuncionais.', '["teacher professional development","teaching practice","augmentative and alternative communication","multifunctional resource rooms","inclusive education","special educational needs","municipal public schools"]', '10.7476/9788575114520', '9788575114520', 'https://books.scielo.org/id/xns62', 'https://books.scielo.org/id/xns62/pdf/nunes-9788575114520.pdf', NULL, 'https://books.scielo.org/id/xns62/cover/cover_thumbnail.jpeg', NULL, 14, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xpd29', 'xpd29', 'Cartas e escrita: práticas culturais, linguagem e tessitura da amizade', NULL, '["Maria Rosa Rodrigues Martins de Camargo"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Neste livro – apoiando-se em cartas escritas por grandes nomes da literatura brasileira, como as de Mário de Andrade a Manuel Bandeira e Carlos Drummond de Andrade, as de Anita Malfatti, de Portinari, de Fernando Sabino e de tantos outros -, Maria Rosa de Camargo nos oferece um belo estudo sobre a prática epistolar de pessoas comuns que, em tese, não representariam lugares sociais de importância na história de uma nação. A autora faz uma bela análise sobre como essas pessoas per­cebem a “ideologia do cotidiano” e, muito além disso, registram “vestígios de sua versão do mundo e da cultura”. Ao adentrar nas relações sociais e nas artimanhas da escrita de cartas pes­soais, esta obra revela competência ao persuadir e envolver o leitor com uma análise que transita entre o fazer científico e a criação literária, oferecendo-nos um texto exemplar, valorado sobretudo por sua notável elegância e simplicidade.', '["epistolary writing","friendship","Brazilian literature","everyday life","persuasion","cultural practices","language","Mário de Andrade","Manuel Bandeira","Carlos Drummond de Andrade","Anita Malfatti","Fernando Sabino"]', '10.7476/9786557145180', '9786557145180', 'https://books.scielo.org/id/xpd29', 'https://books.scielo.org/id/xpd29/pdf/camargo-9786557145180.pdf', NULL, 'https://books.scielo.org/id/xpd29/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xpjfm', 'xpjfm', 'Trabalho de campo: contribuições do curso de Geografia-Licenciatura da UFFS ao ensino e à pesquisa', NULL, '["Éverton de Moraes Kozenieski"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro aborda algo caro à ciência geográfica: o trabalho de campo. Trata-se de uma prática amplamente difundida no fazer dos geógrafos e das geógrafas e uma estratégia de ensino, pesquisa e extensão com tradição e repercussão, cuja característica possibilita produzir conhecimentos com base na aproximação direta do (a) pesquisador (a), estudante e extensionista com o mundo. Esta publicação pretende contribuir com o debate a partir da confluência de, pelo menos, dois objetivos: documentar práticas e oferecer reflexões teóricas. “Trabalho de Campo: contribuições do curso de Geografia-Licenciatura da UFFS ao ensino e à pesquisa”, estruturado em 14 capítulo, visa homenagear os dez anos de criação dos cursos de Geografia da Universidade Federal da Fronteira Sul (UFFS). Portanto, é um modo de demarcar a simbólica passagem dos 10 anos de Geografia na Fronteira Sul. Também é um registro da memória do curso, enfatizando uma dimensão importante do modo de “fazer” Geografia da UFFS. Os textos, escritos por docentes e discentes egressos(as), documentam e rememoram a construção do curso por meio das contribuições das práticas de campo.', '["fieldwork","geography education","geography teacher education","Universidade Federal da Fronteira Sul","teaching practice","research practices","extension","institutional memory"]', '10.7476/9786550190149', '9786550190149', 'https://books.scielo.org/id/xpjfm', 'https://books.scielo.org/id/xpjfm/pdf/kozenieski-9786550190149.pdf', NULL, 'https://books.scielo.org/id/xpjfm/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xqkmm', 'xqkmm', 'Análise de sobrevivência: teoria e aplicações em saúde', NULL, '["Marília Sá Carvalho","V. Andreozzi","Cláudia Torres Codeço","Dayse Pereira Campos","Maria Tereza Serrano Barbosa","Sílvia Emiko Shimakura"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Mathematics', 'O livro Análise de Sobrevida ganha nova edição. Agora, porém, ele se chama Análise de Sobrevivência, termo mais utilizado em Portugal, onde o livro vem sendo bastante adotado. Nesta segunda edição, todos os capítulos foram reescritos e alguns foram desdobrados em dois, com atualizações e incorporação de novos temas. Embora tenha uma linguagem acessível, não se trata de uma obra somente introdutória: ela inclui desenvolvimentos bastante recentes, como modelos para tratamento de eventos múltiplos e modelos de efeitos aleatórios. A análise de sobrevivência consiste em técnicas estatísticas empregadas para estudar o tempo até a ocorrência de algum evento de saúde, que pode ser o óbito ou a cura, por exemplo. Esse conjunto de técnicas permite verificar de que forma uma variável – por exemplo, a adesão ao tratamento – influencia o tempo até a falha terapêutica de uma droga. Baseados em problemas e pesquisas reais, os exercícios de modelagem de dados de sobrevivência encontrados no livro utilizam o pacote estatístico R, um software livre', '["survival analysis","time-to-event data","health outcomes","random effects models","medication adherence"]', '10.7476/9788575413029', '9788575412169', 'https://books.scielo.org/id/xqkmm', NULL, NULL, 'https://books.scielo.org/id/xqkmm/cover/cover_thumbnail.jpeg', 432, 42, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xqzgh', 'xqzgh', 'Soberania e ingerência na Amazônia brasileira', NULL, '["Petronio de Tilio Neto"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '[...] É o objetivo deste trabalho levantar e introduzir alguns problemas de interesse científico e humanístico com relação aos temas, refletir um pouco, e talvez propor caminhos para a elucidação de alguns problemas que possam surgir durante esse percurso. Trata-se, em todo caso, de uma análise preliminar, a ser aprofundada no devido tempo e com a exigida competência.', '["sovereignty","state interference","Brazilian Amazon","territorial sovereignty"]', '10.7476/9788579820472', '9788579820472', 'https://books.scielo.org/id/xqzgh', 'https://books.scielo.org/id/xqzgh/pdf/de-9788579820472.pdf', NULL, 'https://books.scielo.org/id/xqzgh/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xrrzx', 'xrrzx', 'Arquitetura Mackenzie 100 anos FAU-Mackenzie 70 anos: pionerismo e atualidade', NULL, '["Angélica Tanus Benatti Alvim","Eunice Helena Sguizzardi Abascal","Eduardo Castedo Abrunhosa"]', 'Editora Mackenzie', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Engineering', 'Palavra do ReitorEm 2017, a Universidade Presbiteriana Mackenzie (UPM) completa 65 anos de existência.Nesse momento de comemorações e alegrias para a Universidade, o Curso de Arquitetura, criado originalmente na escola de engenharia do então mackenzie College, completa 100 anos, e a Faculdade de Arquitetura e urbanismo festeja 70 anos de uma relevante e sólida atuação.A história da universidade remonta ao século XiX, quando missionários e educadores presbiterianos fundaram a escola Americana, introduzindo no Brasil práticas pioneiras e inovações pedagógicas.Sobre esses fundamentos foi erguido, ainda no século XIX, o mackenzie College, com cursos preparatórios e superiores, destacando-se a escola de Engenharia, criada em 1896 -a mais antiga do país, de natureza privada, comunitária e confessional.em 1952, foi implantada a universidade mackenzie, já contando com seis décadas de ensino superior, com sólida tradição de ensino e notável sintonia com a realidade socioeconômica e tecnológica de são Paulo e do Brasil.A criação do Curso de Arquitetura, em 1917, destaca a formação de inúmeros Engenheiros-Arquitetos de expressão e de uma longa luta de reconhecimento profissional do Arquiteto.dessa dupla missão, de autonomia e de reconhecimento, participou intensamente o Arquiteto Christiano stockler das neves, criador do Curso e mentor da fundação de uma unidade acadêmica em 1947, ao lado de três outras unidades que compartilhavam o mesmo status -Engenharia, Ciências Econômicas e Filosofia, Ciências e Letras.desde sua criação em 1947, a contribuição social da Faculdade de Arquitetura, pioneira no estado de são Paulo, tornou-se visível com a relevante produção arquitetônica dos docentes e arquitetos por ela formados, que, com suas obras e ações, marcaram não somente a paisagem urbana das cidades brasileiras, mas o pensamento, o ideário e as práticas diversificadas, que identificam o exercício da profissão.na atualidade, a excelência dos cursos oferecidos pela Faculdade de Arquitetura e urbanismo da universidade Presbiteriana mackenzie (FAu-mackenzie), tanto na Graduação quanto na Pós-Graduação, é assegurada pela qualificação notável do seu corpo docente, pelo padrão singular de suas instalações, laboratórios e biblioteca, bem como pelo conjunto de Arquitetos e Urbanistas de grande expressão nos âmbitos nacional e internacional, que tem formado ao longo dos anos.Grande é nossa satisfação ao apresentar este livro organizado para celebrar o aniversário do Curso de Arquitetura e da FAu-mackenzie, e que oferece ao leitor um panorama da gênese, da transformação e dos desígnios dessa histórica e singular escola.', '["history of architecture education","engineering school history","urban landscape","São Paulo"]', '10.7476/9788582937266', '9788582937266', 'https://books.scielo.org/id/xrrzx', 'https://books.scielo.org/id/xrrzx/pdf/alvim-9788582937266.pdf', NULL, 'https://books.scielo.org/id/xrrzx/cover/cover_thumbnail.jpeg', NULL, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xrsvx', 'xrsvx', 'Avaliação nutricional na atenção básica: reflexões sobre práticas e saberes', NULL, '["Aline Alves Ferreira","Denise Cavalcante de Barros","Úrsula Viana Bagni"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Mais um título da Coleção Fazer Saúde, o livro traz sete artigos de 11 autores, todos nutricionistas de formação. A publicação é voltada tanto para profissionais da saúde da Atenção Básica, quanto estudantes e demais interessados. As organizadoras contextualizam a situação alimentar e nutricional da população brasileira: complexa, caracterizada pela diminuição da desnutrição, aumento do sobrepeso e obesidade e pela má alimentação. Diante deste quadro, a Atenção Básica se apresenta como estratégica parra a concepção e realização de ações de promoção da saúde e cuidado integral. A publicação traz um conjunto de conteúdos estratégicos e didáticos, com o objetivo de fomentar a promoção da saúde e o cuidado integral nesta área. Reúne a experiência acumulada nesse campo e compartilha conteúdos da avaliação nutricional ainda pouco explorados, em uma perspectiva ampliada e aplicada à Atenção Básica no Sistema Único de Saúde (SUS). Nas palavras das organizadoras, ao apresentar os conteúdos “de forma didática e simples, procuramos preencher as lacunas encontradas na prática do serviço no campo da nutrição e, desta forma, potencializar o protagonismo dos profissionais da saúde que juntos constroem as ações, superam os obstáculos e contribuem para melhorar as condições nutricionais e alimentares da população no seu território”.', '["nutritional assessment","primary care","health promotion","comprehensive care","overweight and obesity","malnutrition","Unified Health System (SUS)","nutritionists"]', '10.7476/9786557080771', '9788575416167', 'https://books.scielo.org/id/xrsvx', NULL, NULL, 'https://books.scielo.org/id/xrsvx/cover/cover_thumbnail.jpeg', 127, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xsghg', 'xsghg', 'Escuta de crianças e adolescentes: reflexões, sentidos e práticas', NULL, '["Leila Maria Torraca de Brito"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A presente coletânea resulta de pesquisas em que predomina o tema escuta de crianças e adolescentes. Tem como foco a análise de necessidades, significados, relevâncias e objetivos, assim como procedimentos e práticas usados para se escutar, ou não, crianças e adolescentes em situações que podem ser encaminhadas ao sistema de justiça.', '["listening to children","juvenile justice","children''s rights","juvenile delinquency","listening practices"]', '10.7476/9788575114360', '9788575112205', 'https://books.scielo.org/id/xsghg', NULL, NULL, 'https://books.scielo.org/id/xsghg/cover/cover_thumbnail.jpeg', 196, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xskrp', 'xskrp', 'Introducción al derecho internacional penal', NULL, '["Héctor Olásolo Alonso"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'La presente obra recoge una colección de ensayos escritos desde mi llegada a la Universidad del Rosario, en Bogotá, en febrero de 2013. En ellos se aborda un conjunto de principios que considero fundamentales para la comprensión y aplicación del derecho internacional penal. El título elegido, pretende reflejar esta realidad. El lector encontrará un giro hacia un análisis más conceptual e interdisciplinario del fundamento y función del derecho internacional penal en la sociedad global. Este giro aparece desde el propio título del trabajo, que refleja cómo, a diferencia de trabajos anteriores, el énfasis del presente estudio se encuentra en la cuestión relativa al recurso por la sociedad internacional a un concepto jurídico que hasta bien entrado el siglo XX se encontraba exclusivamente en la esfera de los ordenamientos jurídicos nacionales: la responsabilidad penal en que incurre la persona humana al llevar a cabo ciertas omisiones o actos ilícitos.', '["international criminal law","international society","global society","human responsibility","interdisciplinary analysis"]', '10.7476/9789587386226', '9789587386219', 'https://books.scielo.org/id/xskrp', NULL, NULL, 'https://books.scielo.org/id/xskrp/cover/cover_thumbnail.jpeg', 220, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xstm7', 'xstm7', 'Formação de leitores surdos e a educação inclusiva', NULL, '["Sandra Eli Sartoreto de Oliveira Martins"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Ensinar crianças surdas a ler é o grande desafio que este livro discute. Afinal, ao longo da história da educação especial é grande a expectativa que se estabelece no processo de alfabetização da criança surda, tanto por parte de seus familiares quanto dos profissionais que a acompanham. Esta obra debate como o surdo, ao se constituir a partir das relações sociais e de outras manifestações de linguagens (oral, expressão corporal e facial, gestos e fragmentos de fala), consegue partilhar situações de produção da linguagem, por meio da leitura. Ao considerar as crianças surdas como não indiferentes à criação cultural do mundo da escrita, a autora revela preocupação com sua inclusão e com o respeito a seus direitos, percebendo-as como cocriadoras da cultura. Para ela, se não há restrição ao acesso aos bens culturais, entre os quais a língua escrita, e portanto ao ato cultural de ler, pressupõe-se que a língua falada não será para o surdo uma língua estrangeira, e sim, à medida que pode ser compartilhada, também sua própria língua. Com vasto material empírico e análise cuidadosa e focada nos aspectos da prática educativa, este livro é particularmente útil para educadores que atuam no ensino regular e são chamados a participar da educação inclusiva.', '["deaf children","literacy","inclusive education","deaf education","special education","sign language","written language","cultural participation","deaf identity"]', '10.7476/9786557145272', '9786557145272', 'https://books.scielo.org/id/xstm7', 'https://books.scielo.org/id/xstm7/pdf/martins-9786557145272.pdf', NULL, 'https://books.scielo.org/id/xstm7/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xtf6m', 'xtf6m', 'História e saúde: políticas, assistência, doenças e instituições na Bahia', NULL, '["Ricardo dos Santos Batista"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta coletânea é composta por textos que tratam da história da saúde na Bahia, escritos por pesquisadores com formação em História e em História das Ciências. Outrora objeto de atenção de profissionais da medicina e da sociologia, os estudos sobre história e saúde se expandiram desde as últimas décadas do século XX e ganharam cada vez mais espaço entre os historiadores.', '["history of health","health policy","health care","disease","health institutions","Bahia","history of medicine","history of public health"]', '10.7476/9786588211175', '9788578873462', 'https://books.scielo.org/id/xtf6m', 'https://books.scielo.org/id/xtf6m/pdf/silva-9786588211175.pdf', 'https://books.scielo.org/id/xtf6m/epub/silva-9786588211175.epub', 'https://books.scielo.org/id/xtf6m/cover/cover_thumbnail.jpeg', 212, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xtmmc', 'xtmmc', '“Fumo de negro”: a criminalização da maconha no pós-abolição', NULL, '["Luísa Gonçalves Saad"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta obra resulta de uma pesquisa cuidadosa sobre concepções científicas, razões políticas e mecanismos sociais que colaboraram para a proibição da maconha no Brasil no século XX. A autora rastreia polêmicas, evidenciando como a progressiva criminalização em torno dos usos da erva criaram terreno para a associação da planta a estigmas atribuídos à população negra no pós-abolição. Ao percorrer teses médicas, a autora também faz-nos perceber as inquietações, desafios e planos eugenistas presentes no processo de criminalização da cannabis, revelando os sentidos políticos das conclusões científicas.', '["cannabis prohibition","criminalization of drug use","post-abolition Brazil","Black population","racial stigma","eugenics","medical discourse","politics of science","drug policy history","20th century"]', '10.7476/9786556302973', '9788523218126', 'https://books.scielo.org/id/xtmmc', 'https://books.scielo.org/id/xtmmc/pdf/saad-9786556302973.pdf', NULL, 'https://books.scielo.org/id/xtmmc/cover/cover_thumbnail.jpeg', NULL, 21, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xtzvc', 'xtzvc', 'Abordagens teóricas e práticas inovadoras no cuidado e na prevenção ao HIV entre adolescentes no Brasil', NULL, '["Inês Dourado"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'O livro tem como base a experiência da primeira fase do estudo PrEP15-19, que ocorreu entre 2018 e 2021, em Belo Horizonte, Salvador e São Paulo. O estudo investigou a efetividade de uma tecnologia de prevenção da infecção pelo HIV denominada Profilaxia Pré-Exposição ao HIV (PrEP), entre adolescentes Homens que fazem Sexo com Homens (HSH) e Travestis e Mulheres Trans (TrMT). O interesse do presente material, porém, vai além. Os diversos capítulos ensinam desde teorias que instruem a pesquisa até aspectos raramente compartilhados: como acessar uma população tão pouco presente nos serviços (não sem razões!)? Como criar vínculos? Como manter a adesão? Como estimular a participação? Como utilizar as novas tecnologias e mídias? Como construir um diálogo efetivo? Essas são contribuições imprescindíveis para o trabalho com esses jovens, mas certamente aplicáveis a outras populações de interesse.', '["HIV prevention","HIV pre-exposure prophylaxis","adolescents","men who have sex with men","transgender women","transgender men","participant retention","health care access"]', '10.7476/9786556308920', '9786556305707', 'https://books.scielo.org/id/xtzvc', 'https://books.scielo.org/id/xtzvc/pdf/magno-9786556308920.pdf', NULL, 'https://books.scielo.org/id/xtzvc/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xv48s', 'xv48s', 'A presença de Bobbio: América espanhola, Brasil, Península Ibérica', NULL, '["Alberto Filippi","Celso Lafer"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Obra fundamental para o pensamento democrático moderno, este livro é composto por ensaios do pensador italiano Alberto Filippi e do professor brasileiro Celso Lafer, que examinam e revelam a influência do pensamento de Norberto Bobbio fora da Itália. Filippi aborda os eixos fundamentais da obra de Bobbio e suas influências na produção intelectual na Europa e na América, enquanto Lafer se debruça na contribuição do pensamento de Bobbio no Brasil e em Portugal. Uma homenagem póstuma a Bobbio, um dos maiores teóricos do século XX, professor italiano que conseguiu aliar a moderna Filosofia do Direito, a Teoria Geral da Política e a apaixonada defesa dos direitos fundamentais, única garantia que tem a sociedade civil no plano nacional e internacional para levar adiante a socialização positiva das idéias de justiça e de liberdade.', '["Norberto Bobbio","democratic thought","Latin America","Brazil","Iberian Peninsula","philosophy of law","fundamental rights","civil society","freedom and justice"]', '10.7476/9788539302727', '9788571395718', 'https://books.scielo.org/id/xv48s', NULL, NULL, 'https://books.scielo.org/id/xv48s/cover/cover_thumbnail.jpeg', 174, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xvt5y', 'xvt5y', 'Neutrinos solares e o método científico', NULL, '["P. C. de Holanda"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Physics and Astronomy', 'Prêmio ABEU 2023 – Ciências Naturais – 2º lugar. O programa de pesquisa em física dos neutrinos solares representa uma ótima ilustração da aplicação do método científico. Tal programa se inicia com uma proposta experimental de detecção dos neutrinos criados em reações nucleares que ocorrem no interior do Sol, e a detecção desses neutrinos confirmaria o modelo de geração de energia solar. Logo com os primeiros resultados, entretanto, um problema se apresentou: os neutrinos solares não estavam sendo detectados com a frequência esperada. A resolução desse problema envolveu uma grande comunidade de pesquisadores e mais de quatro décadas de pesquisa. Este livro apresenta a história desse programa e, em paralelo, utiliza parte das discussões ocorridas na comunidade científica para ilustrar pontos recentes levantados pela Filosofia da Ciência sobre os fundamentos da atividade científica. Tópicos como realismo, falseabilidade de hipóteses, valores na ciência, por exemplo, são discutidos por meio de exemplos extraídos do programa de pesquisa em neutrinos solares.', '["solar neutrinos","solar neutrino problem","scientific method","philosophy of science","realism","falsifiability","values in science","solar power generation","neutrino detection"]', '10.7476/9788526816466', '9788526815520', 'https://books.scielo.org/id/xvt5y', NULL, NULL, 'https://books.scielo.org/id/xvt5y/cover/cover_thumbnail.jpeg', 157, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xvx85', 'xvx85', 'Trabalho e trabalhadores no Nordeste: análises e perspectivas de pesquisas históricas em Alagoas, Pernambuco e Paraíba', NULL, '["Tiago Bernardo de Oliveira"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Ao longo das últimas quatro décadas, a história social do trabalho se tornou um dos mais consolidados ramos da historiografia brasileira. Seus temas, objetos, temporalidades e enfoques teórico-metodológicos se diversificaram, permitindo confrontar distorções e ampliar questões acerca da história da classe trabalhadora do Brasil e de suas relações com as outras classes e com o Estado. Parte dessa diversidade encontra-se reunida neste livro, composto por capítulos que tratam de balanços historiográficos e de aspectos das experiências históricas de classe de trabalhadores e trabalhadoras escravizados, libertos, “livres”, urbanos, rurais, sindicalizados ou não, de Alagoas, Pernambuco e Paraíba. Trata-se de uma contribuição coletiva, que almeja servir tanto ao público acadêmico, em especial a estudantes de graduação e de pós-graduação, quanto aos trabalhadores e trabalhadoras, agentes de sua própria história.', '["social history of work","working class","labor history","Northeast Brazil","Alagoas","Pernambuco","Paraíba","enslaved workers","trade unions","class relations","state and labor"]', '10.7476/9788578793333', '9788578793333', 'https://books.scielo.org/id/xvx85', 'https://books.scielo.org/id/xvx85/pdf/oliveira-9788578793333.pdf', NULL, 'https://books.scielo.org/id/xvx85/cover/cover_thumbnail.jpeg', NULL, 11, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xwcxz', 'xwcxz', 'Educação e alteridade', NULL, '["Ettiène Guérios","Tânia Stoltz"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '[RETIRADO/WITHDRAWN] A emancipação do ser passa pela experiência de alteridade e, nesse sentido, tem na educação uma possibilidade de construção desse processo. Somos visíveis a nós mesmos pelos olhos dos outros. A cultura está, assim, na raiz do que somos, porque a intersubjetividade se dá em um mundo sensível onde eu e os outros estamos situados e interrelacionados. Este livro tem como objetivo fomentar o debate a partir de diferentes enfoques teóricos e pesquisas empíricas sobre a relação educação e alteridade, de caráter eminentemente interdisciplinar.', '["otherness","education","intersubjectivity","emancipation","culture","self and other","interdisciplinarity"]', '10.7476/9788576003694', '9788576003694', 'https://books.scielo.org/id/xwcxz', NULL, NULL, 'https://books.scielo.org/id/xwcxz/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xwhf5', 'xwhf5', 'Teoria quântica: estudos históricos e implicações culturais', NULL, '["Olival Freire","Osvaldo Frota Pessoa Junior","Joan Lisa Bromberg"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Physics and Astronomy', 'vieram ao Brasil para trabalhar com Bohm, enquanto Léon Rosenfeld veio para estabelecer o contraponto entre a interpretação causal e a visão da complementaridade patrocinada pelo físico dinamarquês Niels Bohr.Ainda na década de 1960 foi a vez de Klaus Tausk, professor da USP, envolver-se em acirrada controvérsia com físicos italianos e com Rosenfeld sobre o problema da medição na Teoria Quântica.Pouco depois, o físico brasileiro José Leite Lopes, exilado em Estrasburgo, na França, junto com o físico francês Michel Paty, promoviam evento, que gerou o livro Quantum mechanics -a half century later, que contribuiu para criar um espaço favorável à pesquisa sobre os fundamentos da Teoria Quântica.Recentemente, os desenvolvimentos teóricos sobre o efeito descoerência e o experimento tipo "gato de Schrödinger", que testou pela primeira vez esse efeito, contam entre seus protagonistas com os físicos brasileiros Amir Caldeira e Luiz Davidovich.Os capítulos deste livro estão organizados em quatro partes.A primeira, intitulada História da teoria quântica -desenvolvimentos e fundamentos, reúne artigos com uma abordagem eminentemente histórica sobre aspectos da pesquisa em Teoria Quântica na segunda metade do século XX.A segunda parte, Implicações filosóficas da teoria quântica, está integrada por textos essencialmente filosóficos, versando sobre a interpretação da Teoria Quântica.As Implicações culturais e educacionais da teoria quântica, terceira parte, referem-se a fenômenos, como o "misticismo quântico," a presença da quântica no teatro e o ensino dessa teoria física.Por fim, a última parte, Construção da teoria quântica: história e tendências de pesquisa, está composta por trabalhos históricos que exploram o período da construção da Teoria no início do século XX, bem como trabalhos que mesclam abordagens históricas com possibilidades atuais de desenvolvimento da pesquisa em seus fundamentos.O livro compreende 21 capítulos e 28 autores, divididos entre brasileiros e estrangeiros, em proporções aproximadamente iguais.Reúne desde pesquisadores-sênior a estudantes de pós-graduação.Os trabalhos aqui reunidos foram apresentados em versões preliminares, no workshop que dá origem ao livro.As versões preliminares foram submetidas a um processo de arbitragem e seleção, conduzido pelos organizadores do volume, de modo que esses textos representam um esforço coletivo de discussão e elaboração que teve início naquele workshop e que se prolongou por quase um ano e meio.', '["history of quantum theory","interpretation of quantum mechanics","quantum foundations","measurement problem","decoherence","Schrödinger''s cat","quantum mysticism","quantum mechanics education","Niels Bohr","Léon Rosenfeld","philosophy of quantum mechanics"]', '10.7476/9788578791261', '9788578791261', 'https://books.scielo.org/id/xwhf5', 'https://books.scielo.org/id/xwhf5/pdf/freire-9788578791261.pdf', NULL, 'https://books.scielo.org/id/xwhf5/cover/cover_thumbnail.jpeg', NULL, 16, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xwyxg', 'xwyxg', 'Psicanálise em face ao desamparo e seus destinos', NULL, '["Érico Bruno Viana Campos","Josiane Cristina Bocchi","Ana Maria Loffredo"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'O desamparo é uma experiência fundamental e estruturante da condição humana. Está ligado ao que Freud chamou de Urangst, ou angústia originária, isto é, origem de todas as angústias subsequentes. Após o nascimento, o desamparo decorre da situação de máxima dependência dos cuidados ambientais e está ligado à fragilidade do neonato, à sua mortalidade, a tudo que significa ameaça de perda, trauma ou ferimento da integridade narcísica. Ser inserido no mundo da linguagem com suas mensagens enigmáticas torna o desamparo ainda mais nítido: ele se mantém durante toda a vida e está associado ao que Freud chamou de rochedo da castração, ou seja, a tudo que é inelutável e irredutível na condição humana. Nunca seremos tudo que gostaríamos de ser. O encontro consigo e com o outro em sua alteridade vai sempre suscitar alguma forma de tradução, metabolização ou sublimação. A ilusão de completude narcísica vai sempre se chocar com a realidade da falta, com a realidade de ser lançado na experiência de ser, sem garantias e sem proteção; confrontado, desde o início e sem trégua ao luto originário, ao imperativo de renunciar às ambições de tudo possuir, tudo poder e tudo ser. Embora irredutível, através do amor fati, o desamparo pode se transformar em desafio: há nele, desde o princípio um apelo a dar e a encontrar sentidos e laços sociais. A experiência originária de desamparo é assim: nunca termina de ser feita, mas é justamente ao se rever que encontra seu verdadeiro sentido.', '["abandonment","Sigmund Freud","castration","loss","lack","love of fate","psychoanalysis","human condition","social bonds"]', '10.7476/9786557140567', '9786557140567', 'https://books.scielo.org/id/xwyxg', 'https://books.scielo.org/id/xwyxg/pdf/campos-9786557140567.pdf', NULL, 'https://books.scielo.org/id/xwyxg/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xxmyz', 'xxmyz', 'Mal de Fome e não de raça: gênese, constituição e ação política da educação alimentar. Brasil, 1934-1946', NULL, '["Eronides da Silva Lima"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2000, '2000-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Escrito com base em tese merecedora de prêmio conferido pela Associação de Nutrição do Estado do Rio de Janeiro, este livro contempla novos ângulos de visão e de análise no plano da produção do conhecimento e da prática no campo da alimentação e nutrição, a partir da recuperação de dois importantes períodos no conjunto da literatura especializada. Enfatiza, entre outros aspectos, a delimitação das linhas básicas da Política Alimentar Nacional da época em questão e os reflexos que esta produziu na atualidade. Obra que contém fonte de dados significativos não apenas para aqueles que vivem a perscrutar o sentido e a natureza da educação alimentar como modalidade específica de conhecer e educar, assegurando uma visão disciplinar ampliada para os que militam nas ciências da nutrição e nas políticas subjacentes de alimentação e saúde.', '["food education","history of nutrition","national food policy","hunger","food and race","history of nutrition science"]', '10.7476/9788575416112', '9788575416112', 'https://books.scielo.org/id/xxmyz', 'https://books.scielo.org/id/xxmyz/pdf/lima-9788575416112.pdf', NULL, 'https://books.scielo.org/id/xxmyz/cover/cover_thumbnail.jpeg', NULL, 14, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xxvc9', 'xxvc9', 'A capoeira pelas lentes da pesquisa histórica: olhares e fatos', 'olhares e fatos', '["Luís Vítor Castro Júnior","Denise de Almeida Oliveira"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro "A capoeira pelas lentes da pesquisa histórica: olhares e fatos" reúne textos de pesquisadores capoeiristas que exploram a capoeira em suas múltiplas nuances, abordando temas como oralidades, memórias, sociabilidades, cenas históricas, musicalidade e representações de gênero, com o objetivo de contribuir para o campo da capoeira através de pesquisas históricas e homenagear a memória de Frede Abreu.', '["capoeira","historical research","oral history","memory","sociability","musicality","gender representation","Afro-Brazilian culture"]', '10.7476/9786556309026', '9786556306773', 'https://books.scielo.org/id/xxvc9', 'https://books.scielo.org/id/xxvc9/pdf/castro-9786556309026.pdf', NULL, 'https://books.scielo.org/id/xxvc9/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xy95h', 'xy95h', 'Política e identidade cultural na américa latina', NULL, '["José Luís Bendicho Beired","Carlos Alberto Sampaio Barbosa"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'uma análise comparativa das políticas econômicas no contexto da Grande Depressão dos anos 1930', '["cultural identity","economic policy","Great Depression","Latin America","comparative analysis"]', '10.7476/9788579831218', '9788579831218', 'https://books.scielo.org/id/xy95h', 'https://books.scielo.org/id/xy95h/pdf/beired-9788579831218.pdf', NULL, 'https://books.scielo.org/id/xy95h/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xz2k6', 'xz2k6', 'Inside ticks: morphophysiology, toxicology and therapeutic perspectives', NULL, '["Maria Izabel Camargo‐Mathias"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Immunology and Microbiology', 'Escrito inteiramente em inglês, o presente livro foi concebido por especialistas em morfologia pertencentes à Central Brasileira de Estudos em Morfologia de Carrapatos (BCSTM) da Universidade Estadual Paulista, campus de Rio Claro (SP). O objetivo é esclarecer a morfo-histologia do carrapato, por meio de uma compilação de estudos sobre técnicas histológicas e histoquímicas; biologia, morfologia e taxonomia das principais espécies de carrapatos estudadas histologicamente; histologia de órgãos de carrapato, técnicas histológicas aplicadas para analisar os efeitos acaricidas em órgãos de carrapatos; e novas perspectivas sobre glândulas salivares de carrapatos para seleção de compostos com propriedades farmacológicas. Os capítulos são complementados por ilustrações.', '["ticks","tick morphology","tick taxonomy","tick salivary glands"]', '10.7476/9788595462861', '9788595462861', 'https://books.scielo.org/id/xz2k6', 'https://books.scielo.org/id/xz2k6/pdf/camargo-9788595462861.pdf', NULL, 'https://books.scielo.org/id/xz2k6/cover/cover_thumbnail.jpeg', NULL, 42, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xz97z', 'xz97z', 'Veredas do drama', NULL, '["Cássia Maria Farias. LOPES","João Alberto Lima Sanches"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A obra é a 8ª publicação coletiva do grupo de pesquisa Dramaturgia: mídias, teoria, crítica e criação (Dramatis). Contém textos que abordam questões relacionadas à produção dramatúrgica em suas diversas formas e abordagens teóricas. Essas múltiplas discussões acerca do drama na atualidade são resultado de um encontro de diversas vozes - de pesquisadores e artistas - que proporciona um amplo espaço de discussão sobre o drama contemporâneo, explorando suas diferentes facetas teóricas e criativas. A obra utiliza a metáfora das veredas no ecossistema do cerrado brasileiro para representar as múltiplas vertentes de criação e pesquisa no drama atual.', '["contemporary drama","dramaturgy","dramatic theory","theatre criticism","drama creation","Cerrado","veredas"]', '10.7476/9786556308760', '9786556304861', 'https://books.scielo.org/id/xz97z', NULL, NULL, 'https://books.scielo.org/id/xz97z/cover/cover_thumbnail.jpeg', 229, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xzbv7', 'xzbv7', 'Accompanied Selfrehabilitation', NULL, '["Alberto Fergusson"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'en', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Every once in a great while, there arises a young psychiatrist with entirely new rehabilitation ideas for helping patients retrieve their lives from psychosiso Usually such ideas initially cause significant negative reactions from peers but a handful of sturdy physicians continued on to show the world that something different is possible such as George Brooks of Vermont in the U.S., E.E. Antinnen of Finland, and Franco Basaglia of Italy. Now we have to add to this illustrious list, the name of Alberto Fergusson of Colombia, South America. (Extrae of the Forward) Prof Courtenay M. Harding', '["self-rehabilitation","psychosis","psychiatric rehabilitation","Basaglia","deinstitutionalization","community mental health","history of psychiatry"]', '10.7476/9789587386127', '9789587386110', 'https://books.scielo.org/id/xzbv7', NULL, NULL, 'https://books.scielo.org/id/xzbv7/cover/cover_thumbnail.jpeg', 103, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xzbw6', 'xzbw6', 'Saúde global: uma breve história', NULL, '["Marcos Cueto"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Neste livro, são analisados conceitos sobre a saúde global sempre levando-se em conta que o olhar histórico é fundamental para compreender os desafios das políticas de saúde. O termo saúde global costuma ser usado em resposta a eventos novos, como epidemias internacionais que atingem países ricos e pobres. Mas, afinal, saúde global e saúde internacional são ou não diferentes? O professor e pesquisador Marcos Cueto não se dedica a encerrar o debate, mas sim a estudar os termos saúde internacional e saúde global, investigando a trajetória de mudanças e continuidades das agências e programas internacionais envolvidos com a saúde da população durante o período de 1850 a 2010. Para ele, “este livro expressa a esperança de que o estudo da história da saúde global seja de utilidade para os encarregados da elaboração de políticas públicas e para os estudiosos dos sistemas de saúde em todos os países, auxiliando-os no controle das doenças alimentadas pela pobreza”.', '["global health","global health history","international health","international health organizations","international health programs","health policy","poverty-related diseases","public health"]', '10.7476/9788575415245', '9788575414613', 'https://books.scielo.org/id/xzbw6', NULL, NULL, 'https://books.scielo.org/id/xzbw6/cover/cover_thumbnail.jpeg', 120, 21, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xzdnf', 'xzdnf', 'Avaliação em saúde: dos modelos teóricos à prática na avaliação de programas e sistemas de saúde', NULL, '["Zulmira Hartz","Lígia Maria Vieira-da-Silva"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'contexto muito favorável para o lançamento do livro Avaliação em Saúde: dos modelos teóricos à prática na avaliação de Programas e Sistemas de Saúde, organizado pelas professoras Zulmira Maria de Araújo Hartz e Ligia Maria Vieira da Silva e contando com a participação de mais de uma dezena de destacados colaboradores nacionais e internacionais.Além do desenvolvimento da área sugerido pelo título, o leitor seguramente perceberá duas grandes contribuições dos seus autores.A primeira decorre da abrangência dos seus objetos, ou seja, não se restringe à avaliação de ações, serviços e estabelecimentos de saúde, ousando avançar para a avaliação de programas, sistemas e políticas de saúde.A segunda corresponde ao questionamento da avaliação de "caixa preta", ou seja, a que ignora o contexto e os passos intermediários no alcance de produtos e resultados.Nesse sentido, apresenta abordagens criativas para a sua superação.Cada capítulo deste livro fornece indicações preciosas para pesquisadores, gestores, técnicos e cidadãos interessados em avaliações que não desperdicem o senso comum mas que, também, não sejam reféns de autoenganos, falsas consciências, equívocos desnecessários e ideologias.Ainda que os valores e crenças estejam presentes nas práticas sociais, inclusive na prática científica, o exercício permanente da crítica, do diálogo e da discussão, de um lado, e a explicitação de categorias, conceitos, teorias, modelos teóricos, métodos e técnicas de investigação,', '["health assessment","program evaluation","health policy evaluation","black-box evaluation","evaluation model","evaluation theory and practice","health service evaluation"]', '10.7476/9788575415160', '9788575415160', 'https://books.scielo.org/id/xzdnf', 'https://books.scielo.org/id/xzdnf/pdf/hartz-9788575415160.pdf', NULL, 'https://books.scielo.org/id/xzdnf/cover/cover_thumbnail.jpeg', NULL, 76, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-xzk58', 'xzk58', 'Racismo e saúde: perspectivas antropológicas contemporâneas', 'perspectivas antropológicas contemporâneas', '["Castro, Rosana","Rodrigues, Ana Cláudia"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Racismo e Saúde: Perspectivas Antropológicas Contemporâneas, organizado por Rosana Castro e Ana Cláudia Rodrigues, reúne nove capítulos de pesquisadoras e pesquisadores negros que investigam como o racismo estrutura práticas, políticas e saberes no campo da saúde no Brasil. As etnografias analisam desigualdades historicamente produzidas e intensificadas pela pandemia de covid-19, ao mesmo tempo em que evidenciam ações e mobilizações de enfrentamento. A obra oferece uma contribuição atualizada para compreender os efeitos do racismo e fortalecer práticas de cuidado e políticas públicas mais equitativas.', '["racism","health","health disparities","COVID-19 pandemic","Black researchers","ethnography of health","health care practices","health policy","public health equity","Brazil"]', '10.7476/9786557083024', '9786557082072', 'https://books.scielo.org/id/xzk58', NULL, NULL, 'https://books.scielo.org/id/xzk58/cover/cover_thumbnail.jpeg', 267, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-y28hq', 'y28hq', 'A etnocenologia e seu método: pesquisa contemporânea em artes cênicas', NULL, '["Adailton Ferreira dos Santos"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A obra integra a coleção Pesquisa em Arte e se insere num processo de estudos sobre formas e padrões de pesquisa em artes cênicas. Um dos temas centrais abordados corresponde ao conjunto de eventos em torno dos quais se deu a constituição de uma nova disciplina científica: a etnocenologia. O autor baseia-se em três constantes para analisá-la: a relação sujeito/ objeto; o aparato linguístico a que se refere essa relação e o quadro epistêmico geral.', '["subject-object relationship","epistemic frameworks","artistic research"]', '10.7476/9788523211523', '9788523208264', 'https://books.scielo.org/id/y28hq', NULL, NULL, 'https://books.scielo.org/id/y28hq/cover/cover_thumbnail.jpeg', 231, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-y28rt', 'y28rt', 'Missão prevenir e proteger: condições de vida, trabalho e saúde dos policiais militares do Rio de Janeiro', NULL, '["Maria Cecília de Souza Minayo","Edinilsa Ramos de Souza"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro supre uma carência bibliográfica nos estudos de segurança pública e é fruto de um estudo sociológico que investigou as condições de vida, trabalho e saúde dos policiais militares do estado do Rio de Janeiro, que é a alma mater de todas as outras corporações, constituídas posteriormente – fator que permite a generalização de diversas questões suscitadas aqui.Procura oferecer um entendimento desde a natureza da função da Polícia Militar na sociedade através da análise de sua história sob o aspecto de seus antecedentes, sua instituição e institucionalização, seus integrantes e suas funções legais, no passado e no presente. Avalia também as conseqüências das condições de trabalho impostas ao policial militar com o objetivo direto de produzir informações que ultrapassem preconceitos alimentados, durante décadas, com ressentimentos entre policiais e cientistas da área de humanidades, permitindo, justamente, a pluralidade e a relativização das verdades defendidas por cada um, a partir de suas subjetividades.', '["military police","Rio de Janeiro Military Police","working conditions","police health","public security","police history","subjectivity"]', '10.7476/9788575413395', '9788575413395', 'https://books.scielo.org/id/y28rt', 'https://books.scielo.org/id/y28rt/pdf/minayo-9788575413395.pdf', NULL, 'https://books.scielo.org/id/y28rt/cover/cover_thumbnail.jpeg', NULL, 51, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-y2ycg', 'y2ycg', 'Godard, imagens e memórias: reflexões sobre história(s) do cinema', NULL, '["José Francisco Serafim"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta obra reúne diversos estudiosos da área que exploram o filme História(s) do cinema, um divisor de água na filmografia de Jean-Luc Godard. Este filme é uma obra multiforme, de aproximadamente 270 minutos de duração. Segundo Serafim, ele “mostra uma visão particular do cinema, sobretudo ficcional, mesclando gêneros, formatos e suportes, sem falar da presença de uma trilha sonora, que mistura músicas variadas, sons dos filmes apresentados, ruídos diversos e, claro, as vozes – primeiro, a do próprio cineasta e, logo mais, distintas vozes que vêm acompanhá-lo”.', '["Jean-Luc Godard","Histoire(s) du cinéma","film history","memory","images","documentary film"]', '10.7476/9788523208233', '9788523208233', 'https://books.scielo.org/id/y2ycg', NULL, NULL, 'https://books.scielo.org/id/y2ycg/cover/cover_thumbnail.jpeg', 225, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-y33r4', 'y33r4', 'O verbal e o não verbal', NULL, '["Vera Teixeira de Aguiar"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'PARADIDÁTICOS - SÉRIE: LINGUAGENS E REPRESENTAÇÕES Ênfase à relevância das outras linguagens (além da verbal) na trajetória da História da Civilização, esta obra aborda questões centrais para a compreensão da natureza e da função das linguagens das imagens, da moda ou da propaganda, e suas relações com a linguagem verbal. São observados trabalhos de Pablo Picasso, Carlos Drummond de Andrade e Fernando Pessoa, entre outros, e textos do cotidiano, com apresentação de conceitos básicos para que se atribuam sentidos ao complexo mundo dos signos e códigos.', '["verbal language","nonverbal communication","visual language","fashion","propaganda","language and representation","Pablo Picasso","Carlos Drummond de Andrade","Fernando Pessoa","everyday texts"]', '10.7476/9788539303458', '9788571395602', 'https://books.scielo.org/id/y33r4', NULL, NULL, 'https://books.scielo.org/id/y33r4/cover/cover_thumbnail.jpeg', 109, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-y38z5', 'y38z5', 'Riscos sobre música: ensaios – repetições – provas', NULL, '["Flo Menezes"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Neste livro, Flo Menezes reúne seus principais textos e retoma a discussão estética sobre a música nova, além de publicar análises inéditas em forma de manuscritos de algumas das principais composições para a cena musical moderna. Os temas estão organizados em três partes: Ensaios, Repetições e Provas, nas quais o autor discorre sobre as vanguardas históricas, a música eletroacústica e sobre algumas de suas obras.', '["contemporary music","avant-garde music","electroacoustic music","music aesthetics","musical analysis"]', '10.7476/9788595462885', '9788595462885', 'https://books.scielo.org/id/y38z5', 'https://books.scielo.org/id/y38z5/pdf/menezes-9788595462885.pdf', NULL, 'https://books.scielo.org/id/y38z5/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-y3gm9', 'y3gm9', 'Diferencias entre las reglas de exclusión probatoria colombiana e internacional penal. Análisis en tres casos de injerencias en comunicaciones privadas', NULL, '["Joel M F Ramirez Mendoza"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Al estudiar la regla o cláusula de exclusión probatoria dentro del ordenamiento interno colombiano, se entiende que la regla general es la prohibición de aducir elementos de prueba que sean resultado de injerencias arbitrarias en la intimidad de las personas; por excepción, estas solamente se pueden practicar después de orden judicial, so pena de que los resultados sean excluidos del proceso. Sin embargo, en la práctica hay casos que presentan un desarrollo diferente a lo que han venido planteando la legislación y la jurisprudencia nacional, y ello se ilustrará a través de tres casos de referencia. En contraste, la regla de exclusión ha tenido un tratamiento diferente a la luz del derecho internacional, principalmente en el derecho internacional humanitario, derecho internacional de los derechos humanos y el derecho internacional penal. Siendo así, el planteamiento y principal objeto de esta obra se enfoca en la siguiente interrogación: ¿cuáles son las diferencias entre el derecho nacional y el derecho internacional sobre la regla de exclusión? La búsqueda de la respuesta impone revisar la consistencia de la posición de la Corte Constitucional cuando afirma que la regla que contiene el Estatuto de Roma es equiparable a la regla de exclusión nacional, según la Sentencia C-578 de 2002.', '["exclusionary rule","admissibility of evidence","Colombian criminal procedure","international criminal law","Rome Statute","Colombian Constitutional Court","international humanitarian law","human rights law","court orders"]', '10.7476/9789587386585', '9789587386585', 'https://books.scielo.org/id/y3gm9', 'https://books.scielo.org/id/y3gm9/pdf/ramirez-9789587386585.pdf', NULL, 'https://books.scielo.org/id/y3gm9/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-y3tvp', 'y3tvp', 'Progresso e moral na filosofia da história de Kant', NULL, '["Bruno Nadai"]', 'Editora UFABC', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Podemos discernir algum padrão racional de desenvolvimento histórico em meio ao constante vai e vem dos fatos e acontecimentos? Será que podemos admitir a ideia de que nós, seres humanos, estamos em constante progresso em direção a um mundo melhor? Em que bases e com quais pressupostos podemos dizer que a humanidade progride moralmente? Para além do desenvolvimento civilizatório e das instituições políticas mundo afora, podemos encontrar algum progresso das relações humanas baseadas no princípio de que devemos obedecer apenas leis que nós mesmos estabelecemos? Este livro procura responder a tais perguntas por meio da reconstrução da ideia de uma história filosófica formulada por Immanuel Kant. O leitor está convidado a percorrer conosco algumas das principais obras deste autor, para que possamos nos posicionar sobre o assunto! Adiantamos que, diferentemente do que muitos manuais ensinam, a imagem que emerge aqui é a de um Kant menos formalista, mais atento às condições de realização da razão no mundo.', '["Immanuel Kant","philosophy of history","moral progress","historical progress","interpersonal relationships","Kant''s works"]', '10.7476/9788568576885', '9788568576656', 'https://books.scielo.org/id/y3tvp', 'https://books.scielo.org/id/y3tvp/pdf/nadai-9788568576885.pdf', 'https://books.scielo.org/id/y3tvp/epub/nadai-9788568576885.epub', 'https://books.scielo.org/id/y3tvp/cover/cover_thumbnail.jpeg', 425, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-y3xsb', 'y3xsb', 'Memorabilia: o lado espacial da memória (na esteira de Merleau-Ponty)', NULL, '["Luís António Umbelino"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro trata de um tema específico: a dimensão espacial da memória. Mais especificamente, o oriente deste trabalho é o de ponderar a que ponto e de que modo(s) o tema da memória, que nos habituamos a considerar do lado do tempo, comporta (e por ventura originariamente) um lado espacial definidor, uma dimensão constitutivamente espacial.', '["memory","Merleau-Ponty","phenomenology of memory","time and memory","spatiality"]', '10.7476/9786586213232', '9788574555447', 'https://books.scielo.org/id/y3xsb', NULL, NULL, 'https://books.scielo.org/id/y3xsb/cover/cover_thumbnail.jpeg', 238, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-y3zhj', 'y3zhj', 'Grilhões invisíveis: as dimensões da ideologia, as condições de subalternidade e a educação em Gramsci', NULL, '["Anita Helena Schlesener"]', 'Editora UEPG', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '"Este livro de Anita Helena Schlesener mostra uma pesquisadora em plena maturidade da sua reflexão teórica. Anita tem livros importantes sobre Gramsci de Turim, textos que já nos fazem perceber como o pensamento de Gramsci agia com força no debate ideológico, na crítica radical da ordem social vigente na Itália e na Europa. Por sua vez, o livro que o leitor agora manuseia discute um tema crucial dentro do campo teórico/prático da tradição inaugurada por Karl Marx, a educação, mas traz a contribuição e mediação de Gramsci para pensar elementos de construção da hegemonia burguesa, como a linguagem e a própria educação. Mas a finalidade mesmo é abordar o tema difícil, mas essencial, de uma educação emancipatória para o mundo atual, um mundo inteiramente dominado pelo capital e que expõe sem qualquer pudor a sua horrível face da regressão cultural e da barbárie tecnológica e que mesmo assim mantem também o domínio ideológico."', '["Antonio Gramsci","education","ideology","subalternity","hegemony","bourgeois hegemony","language","emancipatory education","cultural regression","capitalism","Italian Marxism"]', '10.7476/9788577982349', '9788577982349', 'https://books.scielo.org/id/y3zhj', 'https://books.scielo.org/id/y3zhj/pdf/schlesener-9788577982349.pdf', NULL, 'https://books.scielo.org/id/y3zhj/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-y4nzp', 'y4nzp', 'Para além das fronteiras: a política linguística brasileira de promoção internacional do português', NULL, '["Leandro Rodrigues Alves Diniz"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Neste livro, Leandro Rodrigues Alves Diniz desafia o leitor a circular para além das fronteiras territoriais e simbólicas que em geral se nos dão a ver nas políticas linguísticas de promoção da língua portuguesa no exterior, pensando-as como espaços que só podem ser compreendidos a partir de um exercício de destotalização. O autor tece uma fina análise dos desenhos de internacionalização que essas ações de expansão da língua portuguesa delineiam no mapa do mercado das línguas no mundo, a um só tempo situando o leitor acercadas relações ideológicas, de poder e econômicas que atravessam esse mercado, e convidando-o a uma leitura sempre crítica e posicionada. Trata-se, assim, de um texto indispensável aos que se interessam pelos movimentos políticos de promoção internacional de uma língua ? indissociáveis de seus processos de ensino-aprendizagem ?, incluindo linguistas, linguistas aplicados, internacionalistas e professores de línguas, em particular, de Português como Língua Adicional.', '["Portuguese language","language policy","linguistic market","Portuguese as a foreign language","Portuguese as a second language","language ideology","power relations","language teaching and learning"]', '10.7476/9786558580461', '9788542302981', 'https://books.scielo.org/id/y4nzp', NULL, NULL, 'https://books.scielo.org/id/y4nzp/cover/cover_thumbnail.jpeg', 276, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-y4qry', 'y4qry', 'Introdução à filosofia de Bergson', NULL, '["Paulo César Rodrigues"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A proposta de tocar vez a vez em temas percorridos ao longo dos livros de Bergson, cercando de perto os pontos essenciais das análises a que os temas foram submetidos, se mostra muito acertada. Ela permite ao leitor acompanhar o movimento em espiral que gira em torno do mesmo fenômeno, a temporalidade, segundo contextos diversos de sua manifestação, e o aprofunda, aproximando-se do que é em última instância um núcleo inefável. Trata-se de seguir as consequências, filosóficas e vitais, da redescoberta do tempo como duração, isto é, do ininterrupto “advento de novidade” que é o real e que, por isso mesmo, garante a dimensão de contingência e imprevisibilidade do futuro. Pensar em duração consiste, portanto, num modo especial de fazer filosofia, cuja potência crítica e positiva ainda está por ser explorada. Encontramos, no livro em mãos, uma excelente apresentação do filósofo, cuja função, preparada com cuidado e dedicação, será certamente cumprida, projetando mais e melhores leitores dessa obra tão essencial.', '["Henri Bergson","duration","time","philosophy of time","contingency"]', '10.7476/9786557143025', '9786557143025', 'https://books.scielo.org/id/y4qry', 'https://books.scielo.org/id/y4qry/pdf/rodrigues-9786557143025.pdf', NULL, 'https://books.scielo.org/id/y4qry/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-y4w7q', 'y4w7q', 'E as cangaceiras? As representações sociais e o imaginário do feminino cangaço no cinema', NULL, '["Caroline de Araújo Lima"]', 'EDUNEB', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A originalidade do livro de autoria de Caroline de Araújo Lima, fruto de sua pesquisa de doutorado, encontra-se tanto na escolha temática de um recorte do cinema brasileiro sobre o cangaço, quanto na perspectiva de voltar as suas lentes para compreender como as mulheres cangaceiras estão representadas nesses filmes. Trata-se, assim, de reconstituir, através do método da decomposição/ recomposição, as sagas recriadas pelo cinema.', '["cangaço","representation of women in film","Brazilian cinema","social representations","gender and masculinity"]', '10.7476/9788585813703', '9788585813505', 'https://books.scielo.org/id/y4w7q', 'https://books.scielo.org/id/y4w7q/pdf/lima-9788585813703.pdf', 'https://books.scielo.org/id/y4w7q/epub/lima-9788585813703.epub', 'https://books.scielo.org/id/y4w7q/cover/cover_thumbnail.jpeg', 215, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-y4x7f', 'y4x7f', 'Gilberto Freyre e José Lins do Rego: diálogos do senhor da casa-grande com o menino de engenho', NULL, '["Cauby Dantas"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Gilberto Freyre é o principal formulador do ideário regionalista nordestino. Nos textos de interpretação sociológica que produziu, desde o início da década de 1920, já aparecem as matrizes temáticas que estarão presentes nos romances de José Lins do Rego, escritos na década seguinte, consubstanciando, assim, um rico desdobramento estético daquele regionalismo e, ao mesmo tempo, uma interseção entre sociologia e literatura que abordamos a partir de ensaios, romances e cartas destes dois autores, onde sociologia e romance, conceitos e afetos e ideologias se fundem na compreensão, ora empática, ora nostálgica, ora dramática, de uma sociabilidade que remonta às raízes imemoriais de nossa sociedade.', '["Gilberto Freyre","José Lins do Rego","sociology and literature","sociological interpretation","sociability","nostalgia"]', '10.7476/9788578793296', '9788578793296', 'https://books.scielo.org/id/y4x7f', 'https://books.scielo.org/id/y4x7f/pdf/dantas-9788578793296.pdf', NULL, 'https://books.scielo.org/id/y4x7f/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-y58xs', 'y58xs', 'Açúcar amargo: arquitetura e arqueologia industrial do século XVI ao XIX', NULL, '["Esterzilda Berenstein de Azevedo"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro reúne uma enorme documentação histórica, cadastral e fotográfica sobre a agroindústria açucareira do século XVI ao XIX. Resultado da dissertação de mestrado e a tese de doutorado da autora, a primeira parte da obra sobre o período do século XVI ao XVIII dos grandes engenhos do Recôncavo, movidos por rodas-d’água; enquanto a segunda, tem como foco o século XIX e as transformações por que passou a agroindústria com o advento do vapor, novas técnicas de purga e a crise que enfrentou com a competição de açúcar do Caribe. Um livro indispensável para a compreensão da história do maior ciclo econômico brasileiro, suas relações sociais, processos de extração da sacarose de cana e o cenário da sua produção. Historicamente rigoroso, mas, ainda assim, agradável e pronto para ser desfrutado.', '["sugarcane industry","sugar mills","industrial architecture","industrial archaeology","water wheel","steam power","sugar refining","Recôncavo","economic history","interpersonal relationships"]', '10.7476/9786556303697', '9786556302478', 'https://books.scielo.org/id/y58xs', NULL, NULL, 'https://books.scielo.org/id/y58xs/cover/cover_thumbnail.jpeg', 435, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-y5qbg', 'y5qbg', 'Mulheres, poder e ciência política: debates e trajetórias', NULL, '["Flávia Biroli","Luciana Tatagiba","Carla Almeida","Cristina Buarque De Hollanda","Vanessa Elias de Oliveira"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro tem como objetivo compreender, de diferentes perspectivas, o lugar das mulheres na ciência e na política, ontem e hoje. Investiga como elas foram e são invisibilizadas nesses espaços de poder, sobretudo no Brasil. E como vão, paulatina e arduamente, conquistando seu lugar (ainda desigual, mas maior do que no passado não tão distante). Analisa, também, o papel e a presença das mulheres na construção, na autonomização e na expansão do campo disciplinar da ciência política no Brasil e na América Latina, oferecendo uma contribuição preciosa para o conhecimento da história da disciplina, raramente contada a partir da experiência feminina.', '["women in political science","women in politics","gender and power","invisibility of women","history of political science","women in academia","gender inequality","Brazil","Latin America","women''s autonomy"]', '10.7476/9786586253702', '9786586253344', 'https://books.scielo.org/id/y5qbg', NULL, NULL, 'https://books.scielo.org/id/y5qbg/cover/cover_thumbnail.jpeg', 376, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-y5tvh', 'y5tvh', 'Psicologia e teoria crítica: descolonização, interseccionalidade e a crise do Capitalismo - Volume 1', NULL, '["Barros, Carlos César","Costa, José Fernando Andrade","Macêdo, Stefanie de Almeida"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra é resultado do II Colóquio Psicologia e Teoria Crítica: Crise e crítica do Capitalismo – Descolonização e Interseccionalidade, que aconteceu em outubro de 2020. A organização foi realizada pelo Grupo de Pesquisa Psicologia e Teoria Crítica (Feirafurt), da Universidade Estadual de Feira de Santana (UEFS). Para além dos debates sobre a evidente crise do capitalismo, processos de descolonização e interseccionalidade, o volume traz diálogos importantes sobre Identidade e Território, bem como sobre a relação entre Subjetividade e Libertação.', '["critical theory","crisis of capitalism","decolonization","intersectionality","territory and identity"]', '10.7476/9788555921094', '9786589524328', 'https://books.scielo.org/id/y5tvh', NULL, NULL, 'https://books.scielo.org/id/y5tvh/cover/cover_thumbnail.jpeg', 198, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-y69j9', 'y69j9', 'Consulta de Enfermagem à criança com deficiência e doenças raras', NULL, '["Costa, Laura Emmanuela Lima","Silva, Rudval Souza da"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'A obra aborda uma temática relevante - e pouco discutida - que visa contribuir com a formação e atuação da enfermaria no cenário da Atenção Básica e Especializada, a partir de sua atuação nos centros especializados à criança com deficiência e doenças raras. O livro pretende provocar reflexões que possam inspirar e direcionar a(o) enfermeira(o) na sua prática, no campo da Enfermagem em reabilitação. Apresenta, ainda, recomendações de dados atualizados, pesquisa e documentos oficiais do Ministério da Saúde.', '["nursing consultation","children with disabilities","rare diseases","specialized care centers","nursing recommendations"]', '10.7476/9786556308814', '9786556304786', 'https://books.scielo.org/id/y69j9', 'https://books.scielo.org/id/y69j9/pdf/costa-9786556308814.pdf', NULL, 'https://books.scielo.org/id/y69j9/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-y6mws', 'y6mws', 'As virtudes da república: reflexões sobre o político', NULL, '["Salgado, Karine","Almeida, Philippe Oliveira de"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Por que a república e suas virtudes? A queda do Muro de Berlim, ao final da década de 1980, foi interpretada por muitos como o início de uma era pós-ideológica, triunfo da pax americana. Contudo, a crise política que se espraiou pelo mundo na última década pôs a nu as fissuras da ordem vigente. O desencanto, gradualmente, mina o appetitus societatis – o ímpeto (fundamental à preservação de toda e qualquer comunidade política) que leva os indivíduos a se engajarem em um projeto coletivo de organização social. Assim, compomos uma massa, mas não um povo. Se a vitalidade de um Estado evidencia-se pela capacidade do jogo de alternância de poder para absorver (e fortalecer-se com) a pluralidade e a divergência, em nossa sociedade, hoje, os ódios ideológicos terminaram por minar o sentimento de pertença a um espaço comum. Nessa conjuntura, é imprescindível que a Academia resgate a discussão teórico-filosófica a propósito do republicanismo, estrutura política cujos contornos buscam, justamente, assegurar o laço social em meio à multiplicidade de formas de vida e de opiniões, desvelando objetivos comuns pelos quais vale a pena lutar. Assim, os capítulos que compõem este livro perpassam pelos mais relevantes momentos da história ocidental no intuito de, ao perscrutar as reflexões e experiências pretéritas, da Antiguidade à Contemporaneidade – passando pelo Medievo, Renascimento e Modernidade –, oferecer um cabedal importante para uma visão mais crítica e, simultaneamente, propositiva para a república hoje. O público-alvo são intelectuais, professores e estudantes de diversas áreas do conhecimento dedicados a refletir sobre a república, mas também o público em geral, interessado no debate e carente de informações e reflexões que, efetivamente, possam apontar caminhos de resposta ao desafio contemporâneo.', '["republicanism","political philosophy","political community","ideological polarization","political pluralism","social cohesion","history of political thought","Western political history"]', '10.7476/9786558581598', '9786558581222', 'https://books.scielo.org/id/y6mws', NULL, NULL, 'https://books.scielo.org/id/y6mws/cover/cover_thumbnail.jpeg', 188, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-y6ww8', 'y6ww8', 'A universidade crítica: o ensino superiro na república populista', NULL, '["Luiz Antônio Cuñha"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Luis Antônio Cunha reconstrói o processo de transformação do ensino superior no Brasil no período de 1954-1954, em suas determinações sociais e econômicas. Ao lado dos aspectos morfológicos do ensino superior no período (expansão, integração e modernização), o autor explicita a consciência dos agentes envolvidos com esse processo de transformação, particularmente o Estado, os professores e os estudantes, estes últimos organizados por entidades como a SBPC e o sistema UNE/UEEs/DCEs/DAs.', '["higher education","populism","university reform","Brazilian higher education history","state and higher education","higher education expansion","higher education modernization","student movement","UNE","professors","critical university"]', '10.7476/9788539304554', '9788571397729', 'https://books.scielo.org/id/y6ww8', NULL, NULL, 'https://books.scielo.org/id/y6ww8/cover/cover_thumbnail.jpeg', 224, 27, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-y6xsn', 'y6xsn', 'Vozes engajadas: a atuação política do professorado primário da Bahia (1889-1930)', NULL, '["Antonieta Miguel"]', 'EDUNEB', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta obra é resultado da pesquisa O professorado primário da Bahia: formação acadêmica, normatização legal e atuação política (1889-1930). O interesse pela história do professorado baiano advém da minha insatisfação com as imagens construídas da docência pela sociedade. É necessário refletir em que medida se repetem, inclusive pelos próprios professores, as visões estigmatizadas e carregadas de intenções sobre a função do magistério, com suas hierarquias internas, escalas de importância e julgamentos apressados, ou conhecer como caminhos originais foram abertos por professores ao longo do tempo, demarcando resistências e soerguendo os pilares da profissão.', '["primary school teachers","history of teaching profession","teacher professional development","teacher professionalization","teacher law","Bahia"]', '10.7476/9786588211632', '9786588211472', 'https://books.scielo.org/id/y6xsn', 'https://books.scielo.org/id/y6xsn/pdf/miguel-9786588211632.pdf', 'https://books.scielo.org/id/y6xsn/epub/miguel-9786588211632.epub', 'https://books.scielo.org/id/y6xsn/cover/cover_thumbnail.jpeg', 352, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-y742k', 'y742k', 'O demoníaco na literatura', NULL, '["Antônio Carlos de Melo Magalhães","Eli Brandão da Silva","Salma Ferraz","Raphael Novaresi Leopoldo"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Do Horeb, do Gólgota e do Vaticano, trilogia espantosa, que fizeste?[...', '["the demonic","horror in literature","literary representation of the devil","Horeb","Calvary"]', '10.7476/9788578791889', '9788578791889', 'https://books.scielo.org/id/y742k', 'https://books.scielo.org/id/y742k/pdf/magalhaes-9788578791889.pdf', NULL, 'https://books.scielo.org/id/y742k/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-y7btb', 'y7btb', 'Menores em tempo de maioridade: do internato-prisão à vida social', NULL, '["Sônia Altoé"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'prisão à vida social Sonia Altoé Menores em tempo de maioridade do internato-prisão à vida social Sonia', '["juvenile detention centers","adolescence","juvenile justice","social reintegration"]', '10.7476/9788599662953', '9788599662953', 'https://books.scielo.org/id/y7btb', 'https://books.scielo.org/id/y7btb/pdf/altoe-9788599662953.pdf', NULL, 'https://books.scielo.org/id/y7btb/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-y7d2j', 'y7d2j', 'Por dentro da criação', NULL, '["Márcia Ivana de Lima e Silva"]', 'Editora da UFRGS', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Por dentro da criação é o registro do percurso criativo dos alunos do Programa de Pós-Graduação em Letras da UFRGS, da linha de pesquisa “Estudos Literários Aplicados: Leitura, Ensino e Escrita Criativa”. Os textos de Altair Martins, Ana Claudia Costa dos Santos, Carla Cardoso Fonseca, Diego Grando, Marcelo Juchem, Marie-Hélène Paret Passos, Maria Marta Orofino e Richard Serraria apresentam os caminhos percorridos pelos autores para a produção de sua obra. Cada Memorial criativo retoma acertos e erros do percurso, revelando as cicatrizes da escrita. É o olhar de cada autor para a trajetória e para o objeto, na tentativa de reconstituir a realidade na qual a obra se construiu, explorando as diversas dimensões temporais e espaciais do processo de criação. Este livro é um convite para que o leitor entre no ateliê do autor e acompanhe sua caminhada rumo ao trabalho concluído, afastando completamente a ilusão de que uma obra nasce pronta, sem esforço, sem pesquisa, sem retomadas, sem avanços e recuos. É, igualmente, uma prova de que a arte produz conhecimento, porque pode mudar o modo como vemos o mundo e como nos relacionamos com aqueles que nos cercam.', '["creative writing","writing process","literary creation"]', '10.7476/9786557251232', '9788538605003', 'https://books.scielo.org/id/y7d2j', NULL, NULL, 'https://books.scielo.org/id/y7d2j/cover/cover_thumbnail.jpeg', 346, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-y7fvr', 'y7fvr', 'Diálogos entre ciência e divulgação científica: leituras contemporâneas', NULL, '["Cristiane de Magalhães Porto","Antônio Marcos Pereira Brotas","Simone Terezinha Bortoliero"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra aborda a relação da ciência e sua divulgação, estabelecendo diálogos entre pesquisadores dos mais diversos temas sobre ciência e suas interfaces, levantando questões práticas, como a relação da ciência com a cultura, e analisando questões curiosas, como a presença da ciência nas músicas de Gilberto Gil e a abordagem que a mídia brasileira dá a assuntos como o bioetanol e as células-tronco.', '["science communication","science and culture","Gilberto Gil","bioethanol","stem cells","science and society"]', '10.7476/9788523211813', NULL, 'https://books.scielo.org/id/y7fvr', 'https://books.scielo.org/id/y7fvr/pdf/porto-9788523211813.pdf', NULL, 'https://books.scielo.org/id/y7fvr/cover/cover_thumbnail.jpeg', NULL, 15, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-y89xh', 'y89xh', 'Linguagens documentárias e vocabulários semânticos para a web: elementos conceituais', NULL, '["José Antônio Moreiro González"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta publicação aborda a representação conceitual dos documentos dentro do ambiente determinado pela web e pela interatividade. Dividida em onze capítulos, a obra traz desde as bases epistemológicas da representação da informação, até um detalhamento acerca da taxonomia ligada às linguagens documentarias.', '["document languages","semantic vocabulary","World Wide Web","information representation","epistemology of information","interactivity"]', '10.7476/9788523218829', '9788523208240', 'https://books.scielo.org/id/y89xh', NULL, NULL, 'https://books.scielo.org/id/y89xh/cover/cover_thumbnail.jpeg', 130, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-y9sxc', 'y9sxc', 'Violência e saúde', NULL, '["Maria Cecília de Souza Minayo"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Neste livro busco introduzir uma reflexão sobre as articulações entre o tema da violência e suas repercussões na saúde dos brasileiros.Trabalho em três vertentes: a primeira, no campo sociológico de conceituação da violência; a segunda, na articulação entre violência e saúde; a terceira nas propostas de atuação.Por mais que tentasse, não foi possível oferecer ao leitor uma visão muito simplificada da questão, uma vez que o tema é complexo, polissêmico e controverso.Busquei, então, um texto claro e fácil de ser compreendido por qualquer pessoa que, como eu, tem perguntas e busca respostas para este fenômeno.Confesso que, depois de mais 17 anos pesquisando e estudando, continuo sem entender muitos de seus aspectos e tenho mais dúvidas que certezas sobre as manifestações da violência.Portanto, advirto a quem me acompanhar nesta leitura, que minha exposição contém idéias, conceitos, classificações e interpretações passíveis de serem refutadas por outros estudiosos, sem que nem eu nem eles tenhamos condições de nos colocar como portadores da verdade sobre o tema.Para realizar este trabalho, iniciei com uma discussão mais ampla que abrange aspectos históricos, culturais, sociológicos e até econômicos, uma vez que, em suas relações, a violência se apresenta ora como manifestação da dinâmica e da trajetória de O Claves, do qual desde a origem sou a coordenadora científica, é um dos exemplos das iniciativas acadêmicas hoje existentes no país.Tem a vantagem de se constituir como equipe institucionalizada, o que garante a sua continuidade.O incremento da violência na realidade brasileira vem repercutindo intensamente no pensamento intelectual do país, sobretudo a partir da década de 1990.Estudos bibliográficos realizados por nós mostram que 95% da produção acadêmica sobre o tema ocorreram depois de 1980.O tema, no âmbito da reflexão em saúde pública, tem história, nomes e tradições que vêm desde os anos 70, concentrandose primeiramente na Faculdade de Saúde Pública de São Paulo (FSP/USP) e na Universidade Estadual de Campinas (Unicamp).A Fiocruz, até a criação do Claves, colaborava com poucos estudos, e os existentes tinham apenas um cunho epidemiológico descritivo e eram realizados com dados secundários.O fato de o Claves estar exclusivamente voltado para pesquisar este assunto dinamizou a produção institucional e foram abertos vários campos de pesquisa empírica, tornando-o o mais produtivo do país.Em que pesem os esforços dos pesquisadores e das instituições, a reflexão brasileira a respeito da violência social e do impacto da violência na saúde dos brasileiros é ainda incipiente.Os estudos se restringem quase sempre a diagnósticos de situações pontuais, e apenas nos últimos dez anos os resultados das investigações vêm sendo apropriados pelos serviços de saúde.', '["violence","violence and health","conceptualization of violence","violence prevention","violence prevention programs","public health"]', '10.7476/9788575413807', '9788575413807', 'https://books.scielo.org/id/y9sxc', 'https://books.scielo.org/id/y9sxc/pdf/minayo-9788575413807.pdf', NULL, 'https://books.scielo.org/id/y9sxc/cover/cover_thumbnail.jpeg', NULL, 99, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-y9zwc', 'y9zwc', 'Ativismo institucional: criatividade e luta na burocracia brasileira', NULL, '["Abers, Rebeca Neaera"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O burocrata. O ativista. A imagem que vem à cabeça é a do funcionário observando, da janela de sua sala com ar condicionado, um protesto na rua. E se os dois adjetivos se referirem à mesma pessoa? E se o Estado, tido como espaço frio e anônimo, guardar em seus bastidores o calor vibrante da experimentação, as controvérsias, as interpretações, os fios que se ligam a complexas redes internas e externas? E se as instituições, descritas pela ciência política em geral como contextos determinantes – até mesmo restritivos – da ação dos indivíduos, mostrarem-se habitadas por atores com agência? E se os servidores públicos não agirem nem como tecnocratas autocentrados, nem com a idealização dos heróis, mas se revelarem empenhados em avançar valores de igualdade e justiça? E se tudo isso já vinha acontecendo, de modo invisível, em cenários diversos do Estado, esperando apenas que as lentes da pesquisa se direcionassem a eles e que se inaugurassem percepções, questões e conceitos teóricos? Este livro é um convite à criatividade: à que foi demonstrada no ambiente inóspito da burocracia; à que foi exigida na pesquisa e na compreensão do inesperado; e, agora, à do leitor, para que possa ter outra perspectiva do Estado e, a partir do que aqui se vislumbra, abrir-se ao imprevisível. Em um piscar de olhos, o contexto já mudou, a história é desafiada e as ações ativistas podem aparecer com outros contornos, de onde menos se imagina.', '["institutional activism","bureaucracy","public sector employees","creativity","state actors","agency","justice and equality","state-society relations"]', '10.7476/9786558461593', '9786558461593', 'https://books.scielo.org/id/y9zwc', 'https://books.scielo.org/id/y9zwc/pdf/abers-9786558461593.pdf', NULL, 'https://books.scielo.org/id/y9zwc/cover/cover_thumbnail.jpeg', NULL, 57, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ybbg4', 'ybbg4', 'Aprendizagem e comportamento humano', NULL, '["Tânia Gracy Martins do Valle","Ana Cláudia Bortolozzi Maia"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Neste livro o leitor poderá compreender os processos de aprendizagem e comportamento na vertente pedagógica e clínica, considerando as diferentes pesquisas e reflexões teóricas apresentadas, sustentadas pelas contribuições dos estudos das Habilidades Sociais, dos pressuspostos teóricos da Psicologia Histórico-Cultural e da Análise do Comportamento tendo como pano de fundo a inclusão social e escolar. O livro pode ser um material de consulta importante para pesquisadores e interessados no tema', '["learning process","human behavior","social skills","historical-cultural psychology","behavior analysis","social inclusion","inclusive education","pedagogy","clinical psychology"]', '10.7476/9788579831225', '9788579831225', 'https://books.scielo.org/id/ybbg4', 'https://books.scielo.org/id/ybbg4/pdf/valle-9788579831225.pdf', NULL, 'https://books.scielo.org/id/ybbg4/cover/cover_thumbnail.jpeg', NULL, 49, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yc8gx', 'yc8gx', 'Questões teóricas e formação profissional em comunicação e educação', NULL, '["Eliana Nagamini"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O primeiro volume da série inicia com estudos sobre a "Construção epistemológica na interface Comunicação e Educação", em que são operados termos como Educomunicação, Mídiaeducação, Transmidiação ou Comunicação/Educação. Trazem contribuições teóricas que, para além dos conceitos utilizados, procuram refletir acerca das interfaces envolvidas nos vínculos da Comunicação com a Educação. Já os "Processos educacionais e comunicacionais para formação do profissional de Comunicação" discutem metodologias afeitas ao aprender e ensinar na graduação e cursos de extensão.', '["educommunication","media education","transmedia","communication and education","epistemological construction","communication education","teaching methods","undergraduate education","extension course"]', '10.7476/9788574554396', '9788574554396', 'https://books.scielo.org/id/yc8gx', 'https://books.scielo.org/id/yc8gx/pdf/nagamini-9788574554396.pdf', NULL, 'https://books.scielo.org/id/yc8gx/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ycb4h', 'ycb4h', 'Desplazamiento lingüístico y revitalización: reflexiones y metodologías emergentes', NULL, '["Marleen Haboud","Carlos Sánchez Avendaño","Fernando Garcés"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2020, '2020-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Desde distintas miradas, este libro escudriña las muchas facetas que tiene la diversidad y los retos que enfrentamos al tratar de entenderlas y aceptarlas. Incentivados por la lingüística, los procesos educativos, el contacto lingüístico, el translingüísmo, y la creciente vulnerabilidad lingüística, analizamos múltiples situaciones de lenguas en desplazamiento, reflexionamos sobre algunas de las respuestas que se han ido generando y que apuntan a la revitalización lingüístico-cultural a largo plazo, y ponemos en la mesa de discusión teorías, conceptos y metodologías que consideramos aportarán a la investigación y a la acción, desde nuestras propias realidades. Esperamos que este libro nos lleve a reflexionar y a posicionarnos frente a las innumerables inequidades sociales, lingüísticas y culturales que nos rodean y sobre todo, que nos incentive a vivir en la diversidad con todos y cada uno de nuestros sentidos.', '["language revitalization","linguistic diversity","language contact","translingualism","linguistic vulnerability","language teaching","cultural revitalization","social inequities"]', '10.7476/9789978105726', '9789978105726', 'https://books.scielo.org/id/ycb4h', 'https://books.scielo.org/id/ycb4h/pdf/haboud-9789978105726.pdf', NULL, 'https://books.scielo.org/id/ycb4h/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ycbnw', 'ycbnw', 'Abelhas: morfologia e função de sistemas', NULL, '["Carminda da Cruz Landim"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'Este livro trata da morfologia e funções das abelhas, apresentando e descrevendo em detalhes seus organismos. O leitor encontrará temas como ontogênese dos ovários, formação da blastoderme, gastrulação, pupação e metamorfose, os quais estão divididos em três partes: Aparelho reprodutor e gametogênese, Embriogênese e imaturos e Sistemas dos adultos. A obra é rica em imagens, o que contribui para a compreensão dos processos.', '["bees","bee morphology","bee anatomy","bee reproduction","blastoderm formation","gastrulation","pupation","metamorphosis","gametogenesis","embryonic development","immature stages"]', '10.7476/9788539304301', '9788571399273', 'https://books.scielo.org/id/ycbnw', NULL, NULL, 'https://books.scielo.org/id/ycbnw/cover/cover_thumbnail.jpeg', 408, 124, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ycbrt', 'ycbrt', 'A relação entre o Estado e os sindicatos sob uma perspectiva territorial', NULL, '["Amir El Hakim de Paula"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'A tese refletiu sobre a relação entre o Estado e os sindicatos no Brasil por meio de uma análise geográfica. Para tal êxito, nos pautamos em apreender como eram as territorialidades dos sindicatos-revolucionários sob a vigência de um Estado Liberal que, por meio de uma legislação sindical menos coercitiva, possibilitava uma organização dos trabalhadores sem restrição territorial, embora, em contrapartida, agisse de forma violenta, ao prender os principais militantes operários, fechar os jornais e as sedes dos sindicatos. Procuramos também compreender o que significou, principalmente na vigência do Estado Liberal, a presença de um sindicalismo mais combativo, o sindicalismo-revolucionário, que tinha entre suas premissas a autogestão, o federalismo e a ação direta, propiciando várias formas de territorialidades seja, entre os sindicatos de uma mesma categoria ou quando várias entidades de diversas categorias se uniam na organização daquilo que à época eram conhecidas pelos operários como \"greves de solidariedade\". Posteriormente, nossa análise volta-se a compreensão dessa relação entre o Estado e os sindicatos quando da formação de um Estado Corporativo no Brasil, com o predomínio de uma legislação sindical mais limitante, obrigando essas entidades a realizarem uma ação territorial menos plural, restrita quase que, exclusivamente, à área municipal. Percebemos que as ações territoriais dos sindicatos tiveram grande alteração na passagem de um Estado Liberal para outro de tipo Corporativista, graças ao forte controle estatal sobre essas entidades. Entendemos que essas análises possibilitam outra compreensão acerca da relação entre o Estado e os sindicatos no Brasil, evidenciando o papel que as ações territoriais tiveram na luta cotidiana desses trabalhadores.', '["trade unions","corporatism","early 20th century Brazil","labor repression","union pluralism","social movements"]', '10.7476/9788568334676', '9788568334676', 'https://books.scielo.org/id/ycbrt', 'https://books.scielo.org/id/ycbrt/pdf/paula-9788568334676.pdf', NULL, 'https://books.scielo.org/id/ycbrt/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ycppf', 'ycppf', 'A urdidura do magistério primário na Corte Imperial: um professor na trama de relações e agências', NULL, '["Angélica Borges"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Com objetivo de analisar aspectos do magistério Oitocentista na Corte Imperial, este livro observa a vida profissional de Candido Matheus de Faria Pardal, professor no Colégio de D. Pedro II, apontado como signatário do Manifesto dos Professores da Corte de 1871, além de ter sido autor de livros escolares e diretor de escolas municipais, com intensa dedicação à docência. Partindo dessa trajetória, o livro intenta compreender as estratégias para constituir-se mestre e acompanha os passos de conformação do magistério como carreira, em um recorte que se estende da década de 1830 até a última década do Império. Os capítulos permitem entender melhor as experiências constituídas na escola e além dela, destacando as relações entre professores, governantes, alunos e outros atores, em um momento de intensificação do processo de escolarização na sociedade da Corte.', '["primary education","imperial court","teacher professionalization","school textbooks","municipal schools","student enrollment","teacher-student relationship","Brazilian Empire"]', '10.7476/9786587949208', '9786587949208', 'https://books.scielo.org/id/ycppf', 'https://books.scielo.org/id/ycppf/pdf/borges-9786587949208.pdf', NULL, 'https://books.scielo.org/id/ycppf/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ycrrp', 'ycrrp', 'Violência e cidadania: práticas sociológicas e compromissos sociais', NULL, '["José Vicente Tavares dos Santos","Alex Niche Teixeira","Maurício Bastos Russo"]', 'Editora da UFRGS', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro é resultado de uma série de estudos sociológicos realizados pelo Grupo de Pesquisa Violência e Cidadania da UFRGS, desde a década de 1990, partindo de uma conjuntura política e teórica que levou a pesquisar novas questões sociais globais, em particular as dimensões da violência, do crime e do controle social, vivenciando um movimento teórico fecundo, mundializado e inovador de uma prática sociológica na Era da Mundialização das Conflitualidades. O deslocamento do olhar sociológico para a sociedade global possibilitou a passagem para uma sociologia das conflitualidades no processo da mundialização. Os temas analisados indicam que uma sociologia das conflitualidades, no tempo atual, deve ser situada no contexto dos efeitos do processo de mundialização da sociedade e da economia, os quais produzem transformações na estrutura e no espaço social das diversas regiões do planeta, desencadeando novos conflitos sociais e novas formas de conflitualidades. A questão das conflitualidades, das formas de violência, das metamorfoses do crime, da crise das instituições de controle social configura-se pela emergência de lutas sociais protagonizadas por outros agentes sociais com diversas identidades oponentes e pautas de reivindicações. Ainda mais, o aumento dos processos estruturais de exclusão social pode vir a gerar a expansão das práticas de violência como norma social particular, vigente em vários grupos sociais enquanto estratégia de resolução de conflitos, ou meio de aquisição de bens materiais e de obtenção de prestígio social, significados esses presentes em múltiplas dimensões da violência social e política contemporânea. Estamos em presença de um social heterogêneo, no qual nem indivíduos nem grupos parecem reconhecer valores universais. Esse contexto dá origem a múltiplas lógicas de ação coletiva e a forças sociais diversas, em uma sociedade fragmentada e heterogênea.', '["violence","citizenship","sociology of conflict","globalization","social control","crime","social exclusion","social movements","collective action","social stratification","social identity"]', '10.7476/9788538603863', '9788538603863', 'https://books.scielo.org/id/ycrrp', 'https://books.scielo.org/id/ycrrp/pdf/santos-9788538603863.pdf', NULL, 'https://books.scielo.org/id/ycrrp/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yczgx', 'yczgx', 'O viver na “cidade do bem”: tensões, conflitos e acomodações na Vila Operária de Luiz Tarquínio, na Boa Viagem – Bahia (1892-1946/47)', NULL, '["Marilécia Oliveira Santos"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esse livro é resultado da tese de doutorado na UFMG e explora os sentidos e significados que a Vila Operária de Boa Viagem, criada em 1892 na cidade de Salvador/Bahia, teve para os atores, envolvidos na experiência. As normas de conduta estabelecidas pela Empresa permitiram conhecer os recursos adotados e como moradores as vivenciaram. Na construção da memória da vila e do seu idealizador Luiz Tarquínio, que teve papel importante. Apresenta ainda os efeitos na sociedade baiana de uma experiência de sociedade planejada e voltada para a indústria.', '["workers'' housing","urban planning history","collective memory","industrialization","Salvador, Bahia"]', '10.7476/9786588211120', '9788578873387', 'https://books.scielo.org/id/yczgx', 'https://books.scielo.org/id/yczgx/pdf/santos-9786588211120.pdf', 'https://books.scielo.org/id/yczgx/epub/santos-9786588211120.epub', 'https://books.scielo.org/id/yczgx/cover/cover_thumbnail.jpeg', 311, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yd2xx', 'yd2xx', 'Colonialismo, modernidade e política', NULL, '["Partha Chatterjee"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta é uma compilação de textos de autoria do indiano Partha Chaterjee, responsável pela publicação de dezenas de obras engajadas em temas políticos. Grande parte do livro fala de problemas, questões e situações globais tendo como exemplo episódios que marcaram a história da Índia no decorrer dos séculos.', '["colonialism","modernity","politics","Indian history","Partha Chatterjee","global challenges"]', '10.7476/9788523217280', '9788523203146', 'https://books.scielo.org/id/yd2xx', NULL, NULL, 'https://books.scielo.org/id/yd2xx/cover/cover_thumbnail.jpeg', 173, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
