INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ygb3s', 'ygb3s', 'Trajetórias e perspectivas da formação de educadores', NULL, '["Raquel Lazzari Leite Barbosa"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Obra que apresenta temas como a multidisciplinaridade na formação de educadores, a prática dos professores na construção da cidadania, a promoção de uma escola pública com qualidade e democracia, a produção acadêmica e a construção e a incorporação de saberes "reflexivos" a uma política de formação docente", reunindo diversos trabalhos apresentados no 7º Congresso Estadual Paulista sobre a Formação de Educadores (CEPFE). Trata-se da reunião de 38 artigos, de autoria de educadores, que levam à reflexão da relação entre os níveis de ensino - universitário, médio e fundamental - o repensar histórico desses níveis, a dimensão político-social na formação do educador e o significado da produção de conhecimento voltada para o universo educacional.', '["teacher professional development","multidisciplinarity","citizenship education","public schools","school quality","democratic education","academic production","reflective knowledge","teacher education policy","educational attainment","knowledge production"]', '10.7476/9788539303434', '9788571395640', 'https://books.scielo.org/id/ygb3s', NULL, NULL, 'https://books.scielo.org/id/ygb3s/cover/cover_thumbnail.jpeg', 582, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yhmqn', 'yhmqn', 'A poética do suicídio em Sylvia Plath', NULL, '["Ana Cecília Carvalho"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Em fevereiro de 1963, aos trinta anos de idade, a escritora americana Sylvia Plath se suicidou em Londres, onde morava com seus dois filhos, poucos meses depois de ter se separado de seu marido, o poeta inglês Ted Hughes. A morte de Plath aconteceu em meio a uma intensa produção poética, que haveria de incluí-la, por fim, entre as autoras mais importantes do século XX. Uma abordagem psicanalítica da obra da escritora revelará elementos que nos permitem reconhecer uma espécie de toxidez da escrita. Esse aspecto aponta a presença de impulsos destrutivos que operam no interior do processo criativo. Na articulação entre vida, obra e morte, este livro procura ressaltar os modos pelos quais esses impulsos relacionam-se aos limites da escrita literária em sua dupla face funcional e disfuncional.', '["Sylvia Plath","suicide","poetics","psychoanalytic literary criticism","writing and death","creative process","destructive impulses","Ted Hughes","women poets"]', '10.7476/9786558581550', '9786558581031', 'https://books.scielo.org/id/yhmqn', NULL, NULL, 'https://books.scielo.org/id/yhmqn/cover/cover_thumbnail.jpeg', 335, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yhtws', 'yhtws', 'Hannah Arendt e a banalidade do mal', NULL, '["Nádia Souki"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 1998, '1998-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Hannah Arendt e a banalidade do mal se dirige tanto aos conhecedores do pensamento arendtiano quanto àqueles que desejam conhecê-lo, colocando-se na fronteira entre as áreas de filosofia, política, história, sociologia e direito. É no contexto da reflexão sobre o julgamento do criminoso de guerra nazista Adolf Eichmann que Arendt funda o conceito de banalidade do mal, tema que se torna tão atual nos nossos tempos.', '["Hannah Arendt","banality of evil","Eichmann trial","political philosophy","Holocaust","Nazi war criminals","moral responsibility","totalitarianism"]', '10.7476/9786558580119', '9788570411501', 'https://books.scielo.org/id/yhtws', NULL, NULL, 'https://books.scielo.org/id/yhtws/cover/cover_thumbnail.jpeg', 167, 79, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yhzv4', 'yhzv4', 'O percurso da indianidade na literatura brasileira : matizes da figuração', NULL, '["Luzia Aparecida Oliva dos Santos"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O percurso da indianidade na literatura brasileira: matizes da figuração faz uma viagem pela Literatura Brasileira em busca da imagem do índio em seus diversos matizes. Dezoito obras são analisadas pela perspectiva da figuração, que define a presença do nativo brasileiro pela linguagem e a colore de acordo com a época e com as estratégias de cada autor. O percurso se estende da Carta de Achamento, de Pero Vaz de Caminha, até a publicação de Maíra (1976), de Darcy Ribeiro. As análises consideram as diferentes convenções ideológicas e de estilo dos vários movimentos culturais, que promovem o diálogo entre o indianismo e o indigenismo literário brasileiro. O propósito didático consiste em subsidiar os leitores por meio de um roteiro de leitura, que abriga o pensamento científico, conjugado com a presença de trechos das obras, elementos relevantes para a compreensão do universo representativo literário', '["Brazilian literature","representation of indigenous peoples","indigenism","Indianism","colonial encounter","Pero Vaz de Caminha","Darcy Ribeiro","reading guide"]', '10.7476/9788579830204', '9788579830204', 'https://books.scielo.org/id/yhzv4', 'https://books.scielo.org/id/yhzv4/pdf/santos-9788579830204.pdf', NULL, 'https://books.scielo.org/id/yhzv4/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
