ications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yjb8w', 'yjb8w', 'Precisamos falar como nativos? Língua inglesa, transgressão e liberdade', NULL, '["Levi Silva Santos"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro é um convite para quem ensina ou aprende inglês a repensar ideias cristalizadas sobre “falar corretamente” ou “como um nativo”. Com base em uma pesquisa com futuros(as) professores(as), a obra propõe um ensino mais crítico e inclusivo, que valoriza sotaques, identidades e realidades diversas. Ancorado no Inglês como Língua Franca (ILF), e em teorias da Pedagogia Crítica e Pós-Método, o autor questiona mitos linguísticos ainda presentes na sala de aula e oferece caminhos práticos para um ensino mais livre, democrático e conectado ao mundo real.', '["English as a foreign language","English as a lingua franca","linguistic correctness","accent","linguistic identity","critical pedagogy","post-method pedagogy","inclusive language education","teacher professional development","transgression"]', '10.7476/9788574556413', '9788574556161', 'https://books.scielo.org/id/yjb8w', NULL, NULL, 'https://books.scielo.org/id/yjb8w/cover/cover_thumbnail.jpeg', 128, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yjxdq', 'yjxdq', 'Notas teórico-metodológicas de pesquisas em educação: concepções e trajetórias', NULL, '["Maria Elizabete Souza Couto","Raimunda Alves Moreira de Assis"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '"Este livro trata da pesquisa em educação a partir de diferentes concepções teórico-metodológicas (pesquisa etnográfica, pesquisa histórica, pesquisa de avaliação e pesquisa oral temática), oferecendo contribuições para o debate sobre a produção do conhecimento da área e suscitando discussões relevantes a respeito da relação entre a pesquisa, a docência, a formação do professor e do próprio pesquisador em educação."', '["educational research","ethnography","historical research","evaluation research","knowledge production","research and teaching relationship","teacher professional development","research training"]', '10.7476/9788574554938', '9788574554938', 'https://books.scielo.org/id/yjxdq', 'https://books.scielo.org/id/yjxdq/pdf/mororo-9788574554938.pdf', NULL, 'https://books.scielo.org/id/yjxdq/cover/cover_thumbnail.jpeg', NULL, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yjxnr', 'yjxnr', 'Design e ergonomia: aspectos tecnológicos', NULL, '["Luís Carlos Paschoarelli","Marizilda dos Santos Menezes"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A evolução tecnológica observada nas últimas décadas representa a materialização da criatividade humana no desenvolvimento de ambientes, produtos e sistemas, os quais trouxeram muitos benefícios, com destaque para o aumento na economia global, o aumento na expectativa de vida das pessoas, as possibilidades de comércio, interações e comunicações, entre outros.Mas essa mesma evolução também vem resultando em alguns problemas, os quais preocupam tecnólogos, pesquisadores e entidades de proteção aos consumidores sob, pelo menos, dois aspectos bastante pragmáticos: o impacto negativo de muitas dessas tecnologias sobre o meio ambiente e os problemas das interfaces tecnológicas, as quais geram constrangimentos, acidentes e frustração aos consumidores e usuários.Este segundo aspecto está em discussão desde o fi nal do século passado, quando os termos ergonomia, usabilidade, acessibilidade e design universal tomaram conta das questões científi cas em torno do design de produtos e sistemas.A discussão em torno desses temas, por vezes, parece antiquada para os dias atuais, mas de fato envolve questões ainda não respondidas pela comunidade científica.Ao design, ainda resta a questão: como a ergonomia pode contribuir para minimizar os impactos negativos da evolução tecnológica de produtos, sistemas e ambientes?', '["design","human factors","usability","accessibility","universal design","user frustration","consumer protection","environmental impact of technology","product design"]', '10.7476/9788579830013', '9788579830013', 'https://books.scielo.org/id/yjxnr', 'https://books.scielo.org/id/yjxnr/pdf/paschoarelli-9788579830013.pdf', NULL, 'https://books.scielo.org/id/yjxnr/cover/cover_thumbnail.jpeg', NULL, 14, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yjzmz', 'yjzmz', 'Brasil sem industrialização: a herança renunciada', NULL, '["Márcio Pochmann"]', 'Editora UEPG', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'Nos dias de hoje a economia dos serviços, sem a presença da industrialização, tem reproduzido o subdesenvolvimento, como nos países cujas ocupações em expansão não oferecem um horizonte decente e sustentável de futuro justo e democrático a todos. Mesmo nas indústrias de tecnologia das informações e comunicações, os empregos disponíveis são de pequena monta e parcela ainda precários, o que indica o quanto o tema da industrialização segue sendo central para qualquer país que almeja o desenvolvimento.', '["industrialization","service economy","underdevelopment","economic development","ICT sector","precarious employment"]', '10.7476/9788577982165', '9788577982165', 'https://books.scielo.org/id/yjzmz', 'https://books.scielo.org/id/yjzmz/pdf/pochmann-9788577982165.pdf', NULL, 'https://books.scielo.org/id/yjzmz/cover/cover_thumbnail.jpeg', NULL, 11, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yk7gk', 'yk7gk', 'A alfabetização das crianças das classes populares na escola pública: uma proposta de formação continuada de professores(as)', NULL, '["Marissandra Todero"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '“A alfabetização das crianças das classes populares na escola pública: uma proposta de formação continuada de professores(as)” propõe-se a contribuir com a discussão das políticas públicas de formação continuada, dentre elas o PNAIC, que vem para enfrentar o problema das crianças das classes populares que não conseguem se alfabetizar na escola pública. A obra originou-se de um estudo de caso, em uma escola pública estadual, com uma realidade socioeconômica desfavorecida e que tem um papel importante na comunidade. Organiza-se em seis capítulos. O primeiro, “Abrindo o diálogo”, encarrega-se de contextualizar e introduzir a temática. No segundo, o que se apresenta está bem explícito e resumido no próprio título, “A Alfabetização, seu contexto histórico e as legislações”. Trata-se de alguns conceitos e um breve panorama histórico sobre a alfabetização, além das legislações acerca da temática em diferentes épocas, desde a década de 1930 até a Constituição de 1988. No terceiro capítulo, “Educação popular na escola pública: desafios para a formação continuada de professores (as)”, são apresentados alguns suportes teóricos que levam o leitor a perceber a Educação Popular no contexto da escola pública, pensando-a como um espaço de experiências significativas de participação, diálogo e reflexão com os sujeitos que almejam a emancipação. No quarto capítulo, “Professoras e sua ação pedagógica no cotidiano escolar”, apresentam-se os dados da pesquisa relatada neste livro, que se realizou numa uma escola pública, situada em um bairro periférico de Erechim, que atende os filhos dos trabalhadores dessa comunidade. São vivências cotidianas no espaço escolar, práticas realizadas pelas professoras alfabetizadoras, das suas falas, da participação nos diferentes momentos escolares, na observação das práticas em sala de aula, dos dados coletados e de sua análise. As “Considerações Finais” constituem o sexto e último capítulo, no qual, obviamente, ocorre o fechamento do que se discutiu no decorrer da obra, destacando-se os principais aspectos e procurando apresentar uma proposta de intervenção para enriquecer o processo formativo das professoras alfabetizadoras.', '["literacy","literacy education","popular education","continuing teacher education","PNAIC","public schools","working-class children","teaching methods","history of literacy","emancipation","peripheral neighborhoods","Erechim"]', '10.7476/9786550190361', '9786550190361', 'https://books.scielo.org/id/yk7gk', 'https://books.scielo.org/id/yk7gk/pdf/todero-9786550190361.pdf', NULL, 'https://books.scielo.org/id/yk7gk/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yk8v9', 'yk8v9', 'Dinâmica do capital na produção de tecnologias de saúde', NULL, '["Gabriela Costa Chaves","Vitor Henrique Pinto Ido","Koïchi Kameda"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2026, '2026-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'O livro analisa como a dinâmica do capital influencia a produção e o acesso a tecnologias em saúde, discutindo os limites das políticas públicas diante de problemas como o desabastecimento de medicamentos e as desigualdades no acesso. Combinando teoria e análise de casos, aborda temas como a financeirização da indústria farmacêutica e a propriedade intelectual, além de examinar o abandono da produção de antibióticos. A obra propõe reflexões para o fortalecimento de políticas públicas voltadas à soberania e ao acesso equitativo à saúde.', '["capital dynamics","health technology access","financialization","intellectual property","drug shortages","public health policy","health equity","health sovereignty"]', '10.7476/9786557083031', '9786557082416', 'https://books.scielo.org/id/yk8v9', NULL, NULL, 'https://books.scielo.org/id/yk8v9/cover/cover_thumbnail.jpeg', 242, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ykf8q', 'ykf8q', 'A raposa e a águia: J.J. Seabra e Rui Barbosa na política baiana da primeira república', NULL, '["Silvia Noronha Sarmento"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra traz à tona a história de dois importantes personagens da política baiana. Rui Barbosa (1849-1923), a Águia de Haia, foi, segundo a autora, o grande herói baiano e brasileiro do período. Glorificado em vida, celebrado após a morte, Rui concentrou as aspirações de saber, justiça e liberdade de todo o país. Numa palavra, ele representava o bem. Confrontado a essa figura mítica, José Joaquim Seabra (1855-1942) encarnava a imagem do mal, a Raposa. Foi governador da Bahia por dois mandatos e percorreu mais de 50 anos de atividade política, desde o Império até o Estado Novo. Durante essa trajetória, despertou em grandes doses o amor e o ódio dos seus contemporâneos.', '["Rui Barbosa","First Brazilian Republic","Estado Novo","Brazilian Empire","political rivalry"]', '10.7476/9788523211530', '9788523211530', 'https://books.scielo.org/id/ykf8q', 'https://books.scielo.org/id/ykf8q/pdf/sarmento-9788523211530.pdf', NULL, 'https://books.scielo.org/id/ykf8q/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ykjh2', 'ykjh2', 'Trabalhar na Saúde: experiências cotidianas e desafios para a gestão do trabalho e do emprego', NULL, '["Ada Ávila Assunção","Jussara Brito"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Trabalhar na saúde engloba uma multiplicidade de atores e uma diversidade de processos nos serviços públicos, seja na Estratégia Saúde da Família, nos ambulatórios, nos hospitais ou nas emergências. Aos médicos e às equipes de enfermagem, somam-se os agentes comunitários de saúde. Mais: os recepcionistas, o pessoal da segurança e os porteiros das unidades de saúde também devem ser incluídos. Afinal, muitas vezes, esses trabalhadores desempenham o papel de hábeis negociadores, sobretudo porque, com frequência, o número de usuários que procuram os serviços de saúde excede os recursos materiais e humanos ali disponíveis. Uma análise, ao mesmo tempo, abrangente e detalhada sobre essa complexa realidade é o que oferece esta coletânea, que combina teoria e prática para lançar luz sobre uma série de questões polêmicas, como o sofrimento e o desgaste físico e psíquico vivenciados pelos trabalhadores da saúde; o paradoxo entre a missão de cuidar e a ausência de meios; e a necessidade de ‘invenções’ cotidianas para atender às expectativas dos usuários.', '["healthcare workers","work management","employment management","Family Health Strategy","health services","nurses","community health workers","receptionists","security personnel","resource constraints","work-related suffering","user expectations"]', '10.7476/9788575413760', '9788575412176', 'https://books.scielo.org/id/ykjh2', NULL, NULL, 'https://books.scielo.org/id/ykjh2/cover/cover_thumbnail.jpeg', 216, 15, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yksxj', 'yksxj', 'O ator e a câmera: investigações sobre o encontro no jogo do filme', NULL, '["Rafael Conde"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Sabe-se que toda obra de arte é uma interpretação objetiva de uma realidade desembaraçada ou não do real, mas também uma soma de subjetividades que se encontram e que se contaminam. Assim, para que o encenador chegue onde quer, ele precisa ter a liberdade de improvisar, de se desviar do caminho programado, de se sentir livre diante do impremeditável encontro no set. Saber qual ator vai acompanhá-lo nessa jornada e qual gramática deverá usar vai ajudá-lo a compreender e usufruir de alguns vários instantes que o conhecimento objetivo não consegue definir. O ator, por sua vez, se sentirá amparado, orientado e confiante para se arriscar na frente da câmera, sem se constranger diante desse olho frio que o perscruta e deseja.', '["film acting","improvisation","actor training","subjectivity in art","actor-director collaboration"]', '10.7476/9786558580126', '9788542302721', 'https://books.scielo.org/id/yksxj', NULL, NULL, 'https://books.scielo.org/id/yksxj/cover/cover_thumbnail.jpeg', 274, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ym6qv', 'ym6qv', 'A adoção em relações homoafetivas', NULL, '["Maria Cristina Rauch Baranoski"]', 'Editora UEPG', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro apresenta uma abordagem instigante sobre o ponto que mais gera controvérsias: a adoção de crianças e adolescentes por casais do mesmo sexo. A autora atenta muito mais ao direito assegurado constitucionalmente à convivência familiar de todos, quer dos que não vivem com a família biológica, quer dos que vivem uniões homoafetivas.', '["same-sex couples","adoption","same-sex unions","family coexistence","children and adolescents","same-sex marriage"]', '10.7476/9788577982172', '9788577982172', 'https://books.scielo.org/id/ym6qv', 'https://books.scielo.org/id/ym6qv/pdf/baranoski-9788577982172.pdf', NULL, 'https://books.scielo.org/id/ym6qv/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ymkx5', 'ymkx5', 'O jogo como prática de saúde', NULL, '["Marcelo Simão de Vasconcellos","Flávia Garcia de Carvalho","Inesita Soares de Araújo"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'O livro O jogo como prática de saúde é resultado de estudos iniciados em 2009 que buscaram articular três campos do conhecimento: a saúde, a comunicação e os jogos. Marcelo Simão de Vasconcellos, Flávia Garcia de Carvalho e Inesita Soares de Araujo nos trazem uma proposta inovadora: valorizar os jogos como prática humana e social e considerar seu potencial criativo para integrá-los às práticas de saúde. O ineditismo fez do livro o primeiro da coleção Fazer Saúde, que vem se somar às outras sete da Editora Fiocruz – Antropologia e Saúde; Bioética e Saúde; Criança, Mulher e Saúde; História e Saúde; Loucura e Civilização; Saúde dos Povos Indígenas; e Temas em Saúde. Os autores privilegiam a análise dos jogos digitais, amplamente disseminados nas sociedades contemporâneas, mas pouco estudados além de duas categorias – a de jogos educativos e a de instrumento de divulgação científica. Para isso, descrevem e discutem experiências como o uso de newgames sobre epidemias; os jogos voltados para grupos que vivenciam doenças de difícil abordagem, como crianças com Síndrome de Down ou autismo; e outros desenvolvidos pra pessoas idosas com o objetivo de reduzir o risco de Alzheimer. A discussão vai além do uso terapêutico dos jogos: trata da sua inserção em contextos sociais e culturais mais amplos e do envolvimento na experiência lúdica de grupos de referência.', '["video games","serious games","game-based learning","health communication","Alzheimer''s disease prevention","therapeutic use of games","play"]', '10.7476/9786557080801', '9788575415610', 'https://books.scielo.org/id/ymkx5', NULL, NULL, 'https://books.scielo.org/id/ymkx5/cover/cover_thumbnail.jpeg', 134, 11, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ympcj', 'ympcj', 'Cristãos nas terras do Cã: as viagens dos frades mendicantes nos séculos XIII e XIV', NULL, '["Rafael Afonso Gonçalves"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro aborda as sagas dos frades principalmente franciscanos e dominicanos, pertencentes a ordens mendicantes e que se arriscaram em perigosas viagens ao Oriente nos séculos XIII e XIV. Para o autor, não foram homens que se expuseram pelo simples prazer ou pela vontade de percorrerem aventurosamente terras desconhecidas e ignotas, antes foram homens cujo objetivo era marcadamente político-religioso, mas agindo dentro de uma nova configuração. Segundo o autor, esses missionários assumiram e definiram para si uma tarefa – a de expandir a fé cristã – que, embora longe de ser uma novidade, ganharia com eles praticamente um caráter duplo. Para dominicanos e franciscanos, viajar e observar a diversidade do mundo exterior, paisagens, povos e costumes não deviam ser tomados como algo pecaminoso, um afastamento das preocupações espirituais, mas sim como um caminho para encontrar as manifestações diversas de Deus no mundo sensível. Dessa forma, eles acabariam por redefinir o próprio sentido missionário, pois, para melhor difundir a fé, era preciso ser iniciado na doutrina cristã e nos seus preceitos e também estar preparado para os obstáculos que se encontrariam e para as variedades do mundo não conhecido, de suas línguas e de seus costumes, peculiaridades, estranhezas e maravilhas.', '["Franciscan Order","Dominican Order","mendicant orders","Christian missions","missionary travel","13th century","14th century","religious tourism","Christian-Muslim relations"]', '10.7476/9788539304820', '9788539304820', 'https://books.scielo.org/id/ympcj', 'https://books.scielo.org/id/ympcj/pdf/goncalves-9788539304820.pdf', NULL, 'https://books.scielo.org/id/ympcj/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yn', 'yn', 'Bahia: inquisição &amp; sociedade', NULL, '["Luiz Mott"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Um trabalho de mérito, que tem o condão de revelar verdades desconhecidas para os que se interessam pelo conhecimento, nu e cru, dos bastidores da história. “Bahia: Inquisição & Sociedade” é uma amostra selecionada do que representou a ação da Santa Inquisição em Salvador e pelo interior da Capitania. São oito artigos reunidos, publicados entre 1986 e 1995, em diferentes revistas científicas, apresentando um cardápio variado e amplo dos aspectos mais significativos do que representou esta instituição em terras baianenses, em seus quase trezentos anos de atuação entre nós.', '["Inquisition","Catholic Inquisition","Bahia","Salvador, Bahia","colonial Brazil","religious persecution","colonial society","history of the Inquisition"]', '10.7476/9788523208905', '9788523208905', 'https://books.scielo.org/id/yn', 'https://books.scielo.org/id/yn/pdf/mott-9788523208905.pdf', NULL, 'https://books.scielo.org/id/yn/cover/cover_thumbnail.jpeg', NULL, 33, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yn4vh', 'yn4vh', 'Los límites de la estratificación: en busca de alternativas', NULL, '["Carlos E. Sepúlveda","Denis López Camacho","Juan Miguel Gallego Acevedo"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2014, '2014-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra presenta un diagnóstico sobre las deficiencias técnicas del sistema actual de estratificación socioeconómica en la ciudad de Bogotá. Propone como um instrumento más eficiente para la clasificación socioeconómica la utilización de información catastral, em particular aquella relacionada con el avalúo catastral. Presenta una discusión sobre las consecuencias que trae esta nueva alternativa de clasificación sobre las tarifas y subsidios a los servicios públicos domiciliarios y propone posibles esquemas en caso de adoptarse uma clasificación ocioeconómica a través de la información catastral. El diagnóstico sobre la estratificación vigente y el desarrollo de alternativas de definición de subsidios cruzados en servicios públicos domiciliarios (spd), cumplen con un vacío en la literatura colombiana sobre métodos alternativos al sistema actual de estratificación, el cuál ha sido diagnosticado por expertos, académicos y hacedores de política como ineficiente, con riesgos sobre la estabilidad fiscal del sistema de tarifas y com consecuencias indirectas sobre los hogares y la localización urbana de los mismos. De igual forma abre uma agenda de debate e investigación sobre el uso de la información catastral en Bogotá y su aplicación a nivel nacional para focalizar mejor y facilitar el diseño de políticas sociales hacia los hogares, como los subsidios en spd, así como para el diseño de políticas de territorio al interior de las ciudades.', '["socioeconomic stratification","cadastral valuation","household classification","public utility tariffs","cross-subsidization","fiscal stability","urban social policy","territorial policy","Bogotá"]', '10.7476/9789587385373', '9789587385373', 'https://books.scielo.org/id/yn4vh', 'https://books.scielo.org/id/yn4vh/pdf/sepulveda-9789587385373.pdf', NULL, 'https://books.scielo.org/id/yn4vh/cover/cover_thumbnail.jpeg', NULL, 15, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yn5sj', 'yn5sj', 'A construção da igualdade-política e identidade homossexual no Brasil da “abertura”', NULL, '["Edward MacRae"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Os respeitáveis militantes e as bichas loucas 51 Em defesa do gueto', '["political equality","homosexual identity","gay rights","LGBT history"]', '10.7476/9788523219987', '9788523219987', 'https://books.scielo.org/id/yn5sj', 'https://books.scielo.org/id/yn5sj/pdf/macrae-9788523219987.pdf', NULL, 'https://books.scielo.org/id/yn5sj/cover/cover_thumbnail.jpeg', NULL, 24, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yn8f6', 'yn8f6', 'Comunicación, desarrollo y política', NULL, '["Nina Aguiar Mariño","Narcisa Medranda Morales"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2018, '2018-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Comunicación, política y desarrollo aborda una variedad de objetos de estudio, enfoques y metodologías utilizadas en el campo de los estudios de la comunicación en nuestra región. Las propuestas pretenden incorporar nuevos enfoques provenientes de múltiples disciplinas asociados a la comunicación desde una perspectiva crítica. A la vez, este compilado busca entender la comunicación no de manera instrumental, sino como un proceso complejo de significación social e interacción, con implicaciones políticas, tecnológicas, sociales y culturales. En este sentido, la Serie Estudios de la Comunicación, de la cual este libro es parte, busca fomentar la discusión, el debate y la producción científica desde diferentes ángulos o perspectivas, que conlleven a la resolución de problemas a través de la investigación aplicada o el desarrollo de ensayos teóricos que fortalezcan investigaciones de comunicación desde perspectivas transdisciplinarias.', '["communication and development","political communication","social meaning","social interaction","critical communication studies","transdisciplinarity"]', '10.7476/9789978104989', '9789978103203', 'https://books.scielo.org/id/yn8f6', 'https://books.scielo.org/id/yn8f6/pdf/aguiar-9789978104989.pdf', 'https://books.scielo.org/id/yn8f6/epub/aguiar-9789978104989.epub', 'https://books.scielo.org/id/yn8f6/cover/cover_thumbnail.jpeg', 144, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ynczj', 'ynczj', 'Ditaduras: memória, violência e silenciamento', NULL, '["Lucileide Costa Cardoso","Célia Costa Cardoso"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro é fundamentado nas categorias de ditadura, memória, violência e silenciamento. Os artigos presentes na publicação expressam questões epistemológicas e historiográficas que discutem o caráter dos regimes autoritários e suas influências na organização de políticas de memórias que definem o presente. Na primeira parte da obra, são enfatizados os trabalhos que dialogam mais diretamente com as relações entre memória e história, levando em consideração de que a história só poderá ser compreendida a partir do entendimento dessa dinâmica. Na segunda parte, foram reunidos os artigos que tratam diretamente da ditadura civil-militar brasileira e abordam seus aspectos políticos, econômicos e sociais. A terceira e última parte compreendem os artigos que tratam das realidades do Nordeste e, em particular, da Bahia, envolvendo redes repressivas e memórias resistentes de combate ao regime ao longo dos seus 21 anos.', '["dictatorship","memory","violence","silencing","authoritarian regimes","memory politics","memory and history","Brazilian military dictatorship","resistance memory","Bahia","Northeast Brazil"]', '10.7476/9788523220044', '9788523216443', 'https://books.scielo.org/id/ynczj', NULL, NULL, 'https://books.scielo.org/id/ynczj/cover/cover_thumbnail.jpeg', 670, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yndqk', 'yndqk', 'Ascensão e declínio da etnologia alemã (1884-1950)', NULL, '["Erik Petschelies"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Com rara erudição e grande sensibilidade, Erik acompanha 6 etnólogos e 15 expedições, identifica-se com os percalços e subjetividades deles em seus campos, refaz suas trajetórias e biografias, recupera bases filosóficas, analisa suas produções, investe na compreensão de seus contextos científicos, sem perder jamais a crítica e a necessária distância diante desse complexo processo de uma escola de antropologia em formação. O resultado é um verdadeiro mapa dessa produção intelectual, um trabalho que já nasce como um clássico para a história do pensamento alemão e da antropologia de uma maneira geral. (Lilia Moritz Schwarcz)', '["German ethnology","history of anthropology","German intellectual history","ethnologists","ethnographic expeditions"]', '10.7476/9788526816510', '9788526815926', 'https://books.scielo.org/id/yndqk', NULL, NULL, 'https://books.scielo.org/id/yndqk/cover/cover_thumbnail.jpeg', 624, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ynw9g', 'ynw9g', 'A medida do possível: saúde, risco e tecnobiociências', NULL, '["Luís David Castiel"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1999, '1999-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Discute os aspectos cruciais dos estudos sobre a saúde em nosso país, com um refinado tratamento não só dos aspectos científicos, filosóficos, éticos e políticos envolvidos nas práticas médicas. Também das teorias e pesquisas deste domínio sob a ótica de diferentes campos de saber, dentre os quais a antropologia do conhecimento científico, a filosofia da mente e as tecnobiociências. Adotando uma perspectiva transdisciplinar, o autor nos faz encarar o fato de os insofismáveis progressos tecnológicos dos diagnósticos e das terapêuticas - de que muitas vezes nos orgulhamos - se fazerem acompanhar de sérios indícios de crise, tanto ética, como política e filosófica, que não podemos desdenhar e que dizem respeito aos modelos teóricos e epistemológicos das ciências biomédicas e epidemiológicas.', '["health","risk","medical ethics","philosophy of mind","biomedical sciences","epidemiology","epistemology","medical practice","transdisciplinary perspectives","health policy"]', '10.7476/9788575412701', '9788575412701', 'https://books.scielo.org/id/ynw9g', 'https://books.scielo.org/id/ynw9g/pdf/castiel-9788575412701.pdf', NULL, 'https://books.scielo.org/id/ynw9g/cover/cover_thumbnail.jpeg', NULL, 31, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yp857', 'yp857', 'Representações culturais da América indígena', NULL, '["Ana Raquel Portugal","Liliana Regalado de Hurtado"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'publicação APRESENTAÇÃOOs povos indígenas têm sido representados ao longo dos séculos através de imagens e escritos que auxiliam na construção de sua memória histórica.No período anterior à chegada dos europeus, pinturas em paredes de templos, esculturas e outros meios foram utilizados para conservar narrativas mitológicas, descrições de costumes e do cotidiano das populações autóctones.No período da conquista, os europeus passaram também a descrever os povos americanos, depreciando-os ou buscando compreender suas características culturais.Nos dias de hoje, produções fílmicas e trabalhos de campo também ajudam a repensar a memória dessas populações.As representações simbólicas da América indígena nos permitem uma aproximação às várias histórias desses povos, que foram contadas de distintas formas de acordo com a época e os interesses vigentes.Estudos atuais resgatam a oralidade desses grupos étnicos descortinando suas crenças, costumes, símbolos, que possibilitam uma aproximação à sua realidade cultural.', '["indigenous peoples of the Americas","cultural representation","historical memory","indigenous oral tradition","pre-Columbian iconography","ethnographic fieldwork"]', '10.7476/9788579836299', '9788579836299', 'https://books.scielo.org/id/yp857', 'https://books.scielo.org/id/yp857/pdf/portugal-9788579836299.pdf', NULL, 'https://books.scielo.org/id/yp857/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ypf34', 'ypf34', 'Erário Mineral Vol. 1 e 2', NULL, '["Luís Gomes Ferreira","Júnia Ferreira Furtado"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2002, '2002-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Erário Mineral, de Luís Gomes Ferreira, foi editado pela primeira vez em Lisboa, em 1735, sendo um dos primeiros tratados de medicina brasileira escrito em língua portuguesa. O livro reúne as experiências de práticas médicas realizadas pelo cirurgião-barbeiro Luís Gomes Ferreira na capitania de Minas Gerais. Além de uma descrição pormenorizada dos principais males ali freqüentes, o autor também descreve os meios mais eficazes de cura que experimentou e faz um importante inventário dos medicamentos utilizados na época com suas respectivas funções. Nessa leitura, descobrimos que entre os remédios empregados encontravam-se vários utilizados pelos índios e incorporados pelos paulistas à medicina colonial. Parte preciosa do relato é constituída pelas minuciosas informações sobre as duras condições de vida e de trabalho a que os escravos estavam submetidos, o que facilitava a propagação das doenças. Dois glossários completam e enriquecem ainda mais esta edição, procedendo a um levantamento dos médicos e cirurgiões citados pelo autor.', '["colonial medicine","Brazilian medicine","barber-surgeons","Minas Gerais","indigenous remedies","medical dictionaries","18th-century medicine"]', '10.7476/9788575412404', '9788575412404', 'https://books.scielo.org/id/ypf34', 'https://books.scielo.org/id/ypf34/pdf/ferreira-9788575412404.pdf', NULL, 'https://books.scielo.org/id/ypf34/cover/cover_thumbnail.jpeg', NULL, 17, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ypfqm', 'ypfqm', 'A recepção de Lima Barreto em Portugal: documentação Fundação Biblioteca Nacional', NULL, '["João Marques Lopes"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este volume III da Coleção Brasil apresenta as reverberações da obra de Lima Barreto em Portugal. A edição, organizada e anotada por João Marques Lopes, estuda, com base em minucioso trabalho de pesquisa e cruzamento de informações e documentos (muitos deles, inéditos ou pouco conhecidos) presentes no Arquivo de Lima Barreto da Fundação Biblioteca Nacional (FBN) e em outras instituições, traz a público essa rica trajetória de Lima Barreto em terras portuguesas.', '["Lima Barreto","literary reception","unpublished documents"]', '10.7476/9786557146088', '9786557146088', 'https://books.scielo.org/id/ypfqm', 'https://books.scielo.org/id/ypfqm/pdf/lopes-9786557146088.pdf', NULL, 'https://books.scielo.org/id/ypfqm/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yph7n', 'yph7n', 'Práticas dialógicas de linguagem: possibilidades para o ensino de língua portuguesa', NULL, '["Isabel Cristina Michelan de Azevedo"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A presente obra registra parte das atividades que estão sendo realizadas no Programa Mestrado Profi ssional em Letras em Rede Nacional, PROFLETRAS, proposto pela Coordenação de Aperfeiçoamento de Pessoal de Nível Superior -Capes, em 2012, com o objetivo de capacitar professores de língua portuguesa para o exercício da docência no ensino fundamental.Com atual sede na Universidade Federal do Rio Grande do Norte, o Programa congrega universidades com polos nas regiões Norte, Nordeste, Sul, Sudeste e Centro-Oeste do Brasil, constituindo um conjunto integrado de instituições associadas que visam colaborar com a plena realização da proposta desse novo curso 1 .Considerando a grande meta de empoderar os docentes de valor pedagógico para contribuir com o enriquecimento das práticas profi ssionais, na esperança de aumentar o nível de qualidade de ensino dos estudantes do ensino fundamental, com o multiletramento de estudantes e professores e a construção de pedagogias que efetivem as aprendizagens, o trabalho realizado no PROFLETRAS alinha-se em função de objetivos específi cos, entre os quais destacamos o interesse em:1 As informações básicas relativas aos objetivos do PROFLETRAS estão disponíveis em: <http://www.capes.gov.br/educacao-a-distancia/profletras>.Acesso em: 10. out.2016.O último trabalho, "Novos letramentos e narrativas: as vozes das mulheres do Pontal da Barra", desenvolvido por Alessandra R. S. Miranda, discute as contribuições das narrativas de um grupo de integrantes da associação de mulheres bordadeiras do Pontal da Barra para a construção da identidade dessa comunidade, por meio da introdução de novos usos da escrita no contexto social local.A partir da análise das informações coletadas, observou-se a circulação de uma visão depreciativa da atividade profi ssional do fi lé, por parte das rendeiras, colaborando para manter o caráter monológico do discurso capitalista, pois, no avesso dessa história, existem grandes marcas explorando mão de obra barata: as mulheres atuam como força produtiva de baixo custo e, seus produtos, por elas depreciados, são valorizados pelas grifes que os comercializam no mercado, gerando altos lucros.Os textos reunidos neste livro reforçam a ideia de que o trabalho com a linguagem, especialmente com os gêneros do discurso, pode acontecer de maneira dinâmica, por meio da relação estabelecida entre os tipos de enunciados e suas funções na interação verbal que se estabelece em sociedade.As propostas sugeridas por professores e estudantes nesta obra comprovam o vínculo orgânico entre a utilização da linguagem e a atividade humana e indicam que não falamos no vazio, não produzimos enunciados fora das múltiplas e variadas esferas do agir humano.', '["Portuguese language teaching","PROFLETRAS","teacher professional development","multiliteracies","women weavers","women''s narratives","community identity","monological discourse","capitalist discourse","primary education","teaching practice"]', '10.7476/9788574554945', '9788574554945', 'https://books.scielo.org/id/yph7n', 'https://books.scielo.org/id/yph7n/pdf/azevedo-9788574554945.pdf', NULL, 'https://books.scielo.org/id/yph7n/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yqss9', 'yqss9', 'Violência de gênero em Sant’Anna do Catú no pós-abolição, Bahia (1890-1930)', NULL, '["Larissa Cheyenne Nepomuceno de Jesus"]', 'EDUNEB', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A obra investiga casos de violência física e sexual vividas por mulheres pobres e negras que viviam na cidade de Catú Bahia entre os anos de 1890 e 1930. Foram analisados processos policiais e historiagrafias. Além da relevância histórica do livro, tem-se também a importância política de afirmar o horror vividos por estas mulheres em um momento histórico que parece distante, mas hoje ainda existe.', '["gender-based violence","sexual violence","physical violence","Black women","low-income women","post-abolition period","police records","historiography","Bahia"]', '10.7476/9786588211953', '9786588211779', 'https://books.scielo.org/id/yqss9', 'https://books.scielo.org/id/yqss9/pdf/jesus-9786588211953.pdf', 'https://books.scielo.org/id/yqss9/epub/jesus-9786588211953.epub', 'https://books.scielo.org/id/yqss9/cover/cover_thumbnail.jpeg', 169, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ysnm8', 'ysnm8', 'Formação de professores: limites contemporâneos e alternativas necessárias', NULL, '["Lígia Márcia Martins","Newton Duarte"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Essa coletânea de textos produzidos por professores e alunos da linha de pesquisa Teorias Pedagógicas, Trabalho Educativo e Sociedade, do Programa de Pós-Graduação em Educação Escolar, da Universidade Estadual Paulista (UNESP), campus de Araraquara, traz uma contribuição original a um campo no qual muito tem sido publicado nas duas últimas décadas no Brasil, o da formação de professores. A especificidade dessa coletânea reside na abordagem historicizante e crítica tanto das diretrizes oficiais para a formação de professores como das teorias pedagógicas e respectivas propostas metodológicas nesse terreno. São nove textos, que vão desde um balanço crítico do legado deixado pelo século XX no que se refere à formação de professores até questões específicas relacionadas ao trabalho do professor, passando pela questão do debate contemporâneo sobre as teorias pedagógicas.', '["teacher professional development","pedagogical theory","teacher work","history of teacher education","20th century","critical pedagogy","educational methodology"]', '10.7476/9788579831034', '9788579831034', 'https://books.scielo.org/id/ysnm8', 'https://books.scielo.org/id/ysnm8/pdf/martins-9788579831034.pdf', NULL, 'https://books.scielo.org/id/ysnm8/cover/cover_thumbnail.jpeg', NULL, 73, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ystw7', 'ystw7', 'Suma de teologia: [Primeira parte – questões 84-89]', NULL, '["Aquino, Tomás De, Santo"]', 'SciELO', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'I N T R O D U Ç Ã O -10 -primeira parte deste plano, equivalente à primeira parte da Suma, estuda, por sua vez, o que cabe à essência divina, o que compete à distinção das pessoas e o que se refere ao surgir das criaturas a partir de Deus.Esta última seção é abordada também numa consideração tripartida que abrange a produção das criaturas, sua 4 A distinção das criaturas é estudada primeiro em geral e depois em particular.Quanto a este último aspecto aborda-se a distinção entre bem e mal e a distinção entre criatura espiritual e corporal.5 A este é chamada de anjo na Sagrada Escritura, a criatura puramente corporal e a criatura composta da corporal e da espiritual, isto é, o ente humano.6 Tomás de Aquino propõe-se estudar, de um lado, a natureza do ente humano e de outro, sua produção.7 O estudo da natureza humana ocupa as questões 75-89 da primeira parte da Suma.humana da parte da alma e não da parte do corpo, a não ser de acordo com a referência que o corpo tem para com a alma.8 ao corpo humano como tal; digamos, por exemplo, as questões O estudo da alma humana é organizado pelo recurso a uma II Tendo situado o bloco das questões 84-89 da primeira parte 18 Ver, por exemplo, A origem e o retorno J.I.', '["Thomas Aquinas","Summa Theologiae","human nature","human soul","human body","divine essence","good and evil","angels","human being"]', '10.7476/9786558240129', NULL, 'https://books.scielo.org/id/ystw7', 'https://books.scielo.org/id/ystw7/pdf/aquino-9786558240129.pdf', NULL, 'https://books.scielo.org/id/ystw7/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ytpcw', 'ytpcw', 'Crescimento econômico no estado de São Paulo: uma análise espacial', NULL, '["Rodrigo de Souza Vieira"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'Esta dissertação procura investigar, de modo empírico, os determinantes do crescimento dos municípios do Estado de São Paulo. Com base principalmente no trabalho de Glaeser, Scheinkman & Shleifer (1995), o trabalho procura relacionar o crescimento local com seus determinantes econômicos, sociais e geográficos, tais como educação, emprego e composição setorial. O trabalho estende a metodologia utilizada pelos autores, uma vez que adota técnicas de econometria espacial, buscando mensurar efeitos de aglomeração e spillovers de crescimento. Além disso, no modelo adotado, são utilizadas diferentes formas de matrizes de pesos espaciais, com o objetivo de identificar aquela que melhor se adequa ao padrão apresentado pelos dados.', '["local economic growth","growth determinants","municipalities","São Paulo state","spatial econometrics","agglomeration economies","growth spillovers","spatial weight matrix","education","employment","sectoral structure"]', '10.7476/9788579830136', '9788579830136', 'https://books.scielo.org/id/ytpcw', 'https://books.scielo.org/id/ytpcw/pdf/vieira-9788579830136.pdf', NULL, 'https://books.scielo.org/id/ytpcw/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
