count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yvqhq', 'yvqhq', 'Colonização agrária no Norte do Paraná: processos geoeconômicos e sociogeográficos de desenvolvimento de uma zona subtropical do Brasil sob a influência da plantação de café', NULL, '["Gerd Kohlhepp"]', 'EDUEM', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O estudo de Gerd Kohlhepp constitui referência imprescindível para a descrição e compreensão do precesso de colonização agrária do Norte paranaense e oferece um excelente fundamento para a reflexão sobre seus desdobramentos até hoje. A obra não tem apenas o sentido hitórico, que por si mesmo já a justificaria, de registrar um produto de altíssimo nível científico da Geografia de tradição alemã; mais que isso, ela ainda torna acessivel a paranaenses, breasileiros e toda a comunidade lusófona umj desses textos de fundação do Brasil sob perspectiva e contribuição estrangeira, que hoje, ao se tornarem visíveis, ajudam a refletir sobre as características contemporaneas da sociedade local e sobre os caminhos futuros que ela pode tomar - ou não - nas próximas décadas.', '["agricultural colonization","North Paraná","coffee plantations","geoeconomics","social geography","regional development","colonial Brazil","subtropical regions"]', '10.7476/9788576286554', '9788576286554', 'https://books.scielo.org/id/yvqhq', 'https://books.scielo.org/id/yvqhq/pdf/kohlhepp-9788576286554.pdf', NULL, 'https://books.scielo.org/id/yvqhq/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yvx5q', 'yvx5q', 'Saúde de migrantes e refugiados', NULL, '["Deisy de Freitas Lima Ventura"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Mais um título da coleção Fazer Saúde, o livro aborda um dos temas mais urgentes da contemporaneidade: a situação de migrantes e refugiados no Brasil e em diversas partes do mundo e da mobilidade humana internacional. Com um enfoque atualizado e preciso sobre o tema, o título é "fruto da produção híbrida de uma migrante boliviana e trabalhadora do Sistema Único de Saúde e de uma pesquisadora de alto nível no fascinante campo da saúde global", destaca o professor Paulo Buss, ex-presidente da Fiocruz. A primeira é a cirugiã-dentista Veronica Quispe Yujra, mestre em Patologia pela Universidade Federal de São Paulo (Unifesp) e fundadora do coletivo Sí, Yo Puedo!, espaço de acolhimento que promove a integração de migrantes em São Paulo. A outra autora, a advogada Deisy Ventura, é doutora em Direito Internacional pela Universidade de Paris I Pantheón-Sorbonne (França) e professora titular da Faculdade de Saúde Pública da Universidade de São Paulo (USP). Em cinco capítulos, as pesquisadoras abordam a situação atual da mobilidade humana no mundo e da imigração no Brasil, a saúde como um direito humano para as comunidades de migrantes e refugiados, além de resumos sobre as experiência realizadas na Secretaria de Saúde do município de São Paulo, que contemplou rodas de conversas e sensibilização entre gestores e trabalhadores da saúde em unidades com grande fluxo de migrantes internacionais. A coleção Fazer Saúde pretende contribuir para a qualificação de profissionais, pesquisadores e gestores do SUS, estimulando o diálogo entre conhecimentos científicos, educação, inovações tecnológicas, saberes e práticas em saúde. A obra vai ao encontro dos preceitos da coleção, destacando a necessidade de acolhimento aos migrantes e refugiados como um fator de enriquecimentos para a sociedade, expressando, portanto, um projeto de fortalecimento de um SUS multicultural, "um SUS que respeite, que acolha e cuide de todo e qualquer tipo de diferença humana", afirmam as autoras.', '["immigrant health","international migration","right to health","Brazilian immigrants","cultural diversity in health care","immigrant integration","São Paulo"]', '10.7476/9786557080597', '9788575416327', 'https://books.scielo.org/id/yvx5q', NULL, NULL, 'https://books.scielo.org/id/yvx5q/cover/cover_thumbnail.jpeg', 116, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yw42p', 'yw42p', 'Doença, Sofrimento, Perturbação: perspectivas etnográficas', NULL, '["Luiz Fernando Dias Duarte","Ondina Fachel Leal"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1998, '1998-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Primeiro volume da coleção, reúne trabalhos de 17 autores, abrangendo de maneira plural as perspectivas teóricas da área. Tem como foco principal as abordagens que evidenciam a significação ou a dimensão qualitativa, subjetiva do processo de ''enfermar''. Como o interesse não era o de produzir um volume exíguo de vertentes analíticas, a obra é composta por capítulos que se apóiam em dados oriundos de inquéritos, com tratamento qualitativo; alguns valorizam a história, enfatizando a perspectiva comparativa; ainda, outros estão explicitamente influenciados pela etnometodologia e fenomenologia. O fio condutor fica por conta do que, cada vez mais, se convenciona chamar ''metodologias qualitativas''.', '["illness","suffering","perturbations","ethnographic perspective","qualitative research","meaning of illness","ethnography of illness","phenomenology"]', '10.7476/9788575412572', '9788575412572', 'https://books.scielo.org/id/yw42p', 'https://books.scielo.org/id/yw42p/pdf/duarte-9788575412572.pdf', NULL, 'https://books.scielo.org/id/yw42p/cover/cover_thumbnail.jpeg', NULL, 39, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yw7ns', 'yw7ns', 'Agente comunitário de saúde: o ser, o saber, o fazer', NULL, '["Joana Azevedo da Silva","Ana Sílvia Whitaker Dalmaso"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2002, '2002-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'Analisa as questões relativas ao agente comunitário de saúde, decorrentes da grande disseminação dos Programas de Saúde da Família. Estudando o agente comunitário de saúde que atua no Projeto Qualis/PSF, no município de São Paulo, este livro examina a construção de identidades profissionais e caracteriza o perfil das áreas metropolitanas. Por meio de uma reflexão sobre a identidade dos profissionais dos programas de saúde, os agentes comunitários, e sobre suas dificuldades para viabilizar uma política de reorientação do modelo de assistência à saúde, este livro demonstra sua importância como discussão essencial para sustentar e continuar os Programas de Saúde da Família, buscando recursos disponíveis nas próprias comunidades.', '["community health agents","Family Health Strategy","professional identity","metropolitan areas","community-based care","São Paulo"]', '10.7476/9788575416136', '9788575416136', 'https://books.scielo.org/id/yw7ns', 'https://books.scielo.org/id/yw7ns/pdf/silva-9788575416136.pdf', NULL, 'https://books.scielo.org/id/yw7ns/cover/cover_thumbnail.jpeg', NULL, 42, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yw9zf', 'yw9zf', 'Empreendedorismo: registros de estudos teórico-empíricos no semiárido', NULL, '["Agostinha Mafalda Barra de Oliveira"]', 'EdUFERSA', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'Este livro constitui-se de uma coletânea de sete registros de estudos teórico-empíricos sobre empreendedorismo, realizados entre os anos de 2013 a 2016. Os três primeiros registros abordam a importância e a eficácia da educação empreendedora nas IES, com delineamentos de pesquisa bem diferentes. Os dois registros seguintes tratam o empreendedorismo sob uma perspectiva micro e relacionam o perfil empreendedor com suas características pessoais e sociais ou os classificam pela sua motivação para empreender. Por fim, os dois últimos registros já adotam uma perspectiva mais macro e verificam o papel do empreendedorismo e de uma de suas instituições de fomento para o desenvolvimento econômico.', '["entrepreneurship","entrepreneurship education","higher education institutions","entrepreneur profile","entrepreneurial motivation","economic development","semi-arid region"]', '10.7476/9786587108667', '9786587108667', 'https://books.scielo.org/id/yw9zf', 'https://books.scielo.org/id/yw9zf/pdf/oliveira-9786587108667.pdf', NULL, 'https://books.scielo.org/id/yw9zf/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ywd5x', 'ywd5x', 'Hepatite C e tireoide', NULL, '["Luís Jesuino De Oliveira Andrade","Gabriela Correia Matos de Oliveira"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Neste livro os autores apresentam as principais alterações da tireoide secundárias à hepatite C. Elaborado com a participação de colaboradores do mais alto conhecimento científico, profissionais dedicados à pesquisa e com vasta experiência no assunto. Por sua abrangência, torna-se uma leitura interessante para todos os profissionais de saúde.', '["hepatitis C","thyroid gland","thyroid dysfunction","chronic hepatitis C"]', '10.7476/9786586213737', '9786586213461', 'https://books.scielo.org/id/ywd5x', NULL, NULL, 'https://books.scielo.org/id/ywd5x/cover/cover_thumbnail.jpeg', 247, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ywnsk', 'ywnsk', 'Tolerância intolerante / De mal a pior', NULL, '["Silva Filho, Waldomiro J."]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro se destina àquelas pessoas que querem entender este século que nasce sob o signo contraditório da esperança e da tragédia: uma esperança em uma sociedade mais igual e menos violenta, uma tragédia caracterizada por retrocessos da democracia e na saúde pública. Os textos reunidos na obra lançam um olhar severo sobre a história recente do Brasil (marcado pelo autoritarismo e racismo) e sobre este presente que, depois de avanços na nossa democracia desde 1988, vem nos empurrando para o abismo da desigualdade, de novas formas de fascismo e da agressão à vida. Mas este livro não é somente mais um lamento, mas a explosão crítica de duas das mais poderosas vozes no cenário do debate democrático no Brasil atual: Lilia Schwarcz e Ailton Krenak. Nessa segunda edição, incluímos o ensaio “Maiorias minorizadas” de Lilia Schwarcz, que está em harmonia com a “tolerância intolerante” servindo para dar ainda mais ênfase às profundas contradições da sociedade e da política no Brasil. Como proposta que integra os textos, há o clamor pela urgência da conversa cívica e democrática e, ao mesmo tempo, a necessidade de entender aquilo que tem tornado essa civilidade na nossa sociedade.', '["intolerance","democracy","authoritarianism","racism","fascism","social inequality","democratic backsliding","public health","citizen dialogue","Brazilian politics","Ailton Krenak"]', '10.7476/9786556305202', '9786556301310', 'https://books.scielo.org/id/ywnsk', NULL, NULL, 'https://books.scielo.org/id/ywnsk/cover/cover_thumbnail.jpeg', 113, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yx4kn', 'yx4kn', 'Dialogando sobre conhecimento e ciência a partir da cultura Kaingang e da perspectiva decolonial', NULL, '["Elisabete Cristina Hammes"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Nesta obra, que surgiu a partir da vivência da autora com a cultura do povo Kaingang, busca-se desvelar, pelo viés da decolonialidade, a exclusão dos povos nativos dos espaços de produção do saber. No momento em que os povos indígenas começam a acessar os espaços formativos universitários, questões como epistemologia, racismo epistêmico, epistemicídios, colonialidade do ser, saber e poder apontam para um repensar do modelo científico hegemônico, das demandas específicas destas populações, da recuperação e visibilidade de seus saberes e formas específicas de pensar e se relacionar com o outro e com a natureza. “Dialogando sobre conhecimento e ciência a partir da cultura Kaingang e da perspectiva decolonial”, que se constitui de dez capítulos, tem como público de interesse os profissionais que atuam nos espaços formativos, de forma a trazer elementos para construir lógicas educativas voltadas ao contexto dos povos indígenas, suas cosmologias, suas estratégias de transmissão e produção de conhecimentos.', '["Kaingang people","decoloniality","indigenous knowledge","epistemic racism","epistemology","indigenous cosmology","knowledge transmission","scientific knowledge production","human-nature relationship"]', '10.7476/9786586545944', '9786586545944', 'https://books.scielo.org/id/yx4kn', 'https://books.scielo.org/id/yx4kn/pdf/hammes-9786586545944.pdf', NULL, 'https://books.scielo.org/id/yx4kn/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yxn7q', 'yxn7q', '1984: a distopia do indivíduo sob controle', NULL, '["Evanir Pavloski"]', 'Editora UEPG', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Ao longo dos séculos, a ânsia por reestruturar os núcleos sociais tangenciou, muitas vezes, os limites do sonho e do pesadelo. A literatura, ao mesmo tempo testemunha e agente dessas inspirações, figurou espaços utópicos que, de forma ambígua, se revelavam transformadores e normalizadores. Dentre essas produções, destaca-se o romance anitutópico ou distópico 1984, de George Orwell, que desnuda os perigos que cercam o idealismo homogeneizador das utopias políticas. Tendo o universo ficcional do "Big Brother" como objeto de análise, a obra discute a recorrência histórica do utopismo no pensamento humano em geral e na literatura orwelliana em particular. Por meio dessa discussão, busca-se lançar luz sobre os eventos e os processos socioculturais que fomentaram o "medo da utopia" na modernidade tardia.', '["George Orwell","dystopia","utopia","anti-utopia","Big Brother","political utopianism","late modernity"]', '10.7476/9788577982189', '9788577981847', 'https://books.scielo.org/id/yxn7q', 'https://books.scielo.org/id/yxn7q/pdf/pavloski-9788577982189.pdf', 'https://books.scielo.org/id/yxn7q/epub/pavloski-9788577982189.epub', 'https://books.scielo.org/id/yxn7q/cover/cover_thumbnail.jpeg', 272, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yyjp2', 'yyjp2', 'Ideias econômicas no Brasil oitocentista', NULL, '["Ivan Colangelo Salomão","Luiz Felipe Bruzzi Curi"]', 'Editora da UFRGS', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'O propósito de organizar uma obra sobre as ideias econômicas no Brasil do século XIX surgiu da percepção de que a temática, especialmente no que se refere a esse período, encontra uma lacuna patente na historiografia brasileira. A ênfase que geralmente se atribui ao debate econômico após o estabelecimento dos primeiros cursos de Economia no país, nos anos 1940, contribui para escamotear a já intensa circulação de ideias econômicas no Brasil pré-industrial. Se a maioria (senão, a totalidade) delas era, de fato, importada dos países centrais, pode-se observar na leitura desta obra que os principais temas econômicos de que se ocupava a elite brasileira já incorporavam traços da vivência nacional. Diferentemente do que entendia Celso Furtado, por mais recorrentes que aqui fossem os assuntos originalmente discutidos nas escolas europeias, percebe-se que o debate nacional ganhava tinturas tropicais ao adaptar aquelas ideias às especificidades locais. Temas caros à sociedade brasileira do século XIX, tais como escravidão, latifúndio, diversificação produtiva, política aduaneira etc. fizeram do encontro da teoria econômica com a realidade brasileira um rico objeto de estudo para pesquisadores contemporâneos. Dessa forma, reuniram-se economistas e historiadores que se propuseram a analisar os fundamentos do pensamento econômico de nove relevantes atores do cenário político-econômico brasileiro daquele momento. Conquanto não se tenha pretendido inter-relacionar os capítulos, a disposição cronológica dos personagens aqui estudados permite que se vislumbrem as continuidades e reconfigurações relativas aos mais relevantes temas presentes no debate econômico do “longo século XIX”. Assim, espera-se que este livro preencha, ainda que embrionariamente, o hiato existente no estudo das ideias econômicas do Brasil oitocentista. Sem a pretensão de encerrar o assunto, a obra busca incentivar o desenvolvimento de novas pesquisas concernentes a este tema tão pouco explorado pela historiografia brasileira.', '["economic thought","19th-century Brazil","Brazilian elites","slavery","latifundia","production diversification","customs policy","Celso Furtado","history of economic thought"]', '10.7476/9786557252284', '9786557250877', 'https://books.scielo.org/id/yyjp2', NULL, NULL, 'https://books.scielo.org/id/yyjp2/cover/cover_thumbnail.jpeg', 379, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yymmj', 'yymmj', 'Procurando razões', NULL, '["Silva Filho, Waldomiro J."]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2022, NULL, 'pt', 'book', 'humanities', 'Humanidades y Artes', NULL, 'Procurando Razões é um livro surpreendente. Partindo de um conjunto de temas clássicos da filosofia, como conhecimento, racionalidade, ceticismo e virtudes intelectuais, Waldomiro Silva Filho desenvolve um texto único no estilo e na abordagem ao narrar o percurso de uma investigação sobre a noção de reflexão. Escrito na forma ensaística, este livro cruza a própria experiência pessoal do autor com referências filosóficas e literárias. Em vez de avançar, como normalmente acontece com livros de filosofia, para uma conclusão ou na defesa de uma teoria, o texto mostra como uma interrogação inicial sobre qual o bem que podemos conquistar com a reflexão foi se transformando numa dúvida sobre por que algumas vezes a reflexão é importante e porque razões importam.', '[]', '10.7476/9786556305196', '9786556303222', 'https://books.scielo.org/id/yymmj', NULL, NULL, 'https://books.scielo.org/id/yymmj/cover/cover_thumbnail.jpeg', 188, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yyvth', 'yyvth', 'Relações de complementação no português brasileiro: uma perspectiva discursivo-funcional', NULL, '["Liliane Santana"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A complementação na perspectiva discursivo-funcional 1 A noção de complementação em diferentes perspectivas 17 2 A complementação na perspectiva funcional 45 3 A gramática discursivo-funcional 93 Parte IIAnálise da complementação no português falado 4 Universo de pesquisa e procedimentos metodológicos 129 5 Descrição funcional dos tipos de construções encaixadas nominais e verbais', '["complementation","Brazilian Portuguese","Discursive-Functional Grammar","functional grammar","nominal constructions","verb constructions"]', '10.7476/9788579831164', '9788579831164', 'https://books.scielo.org/id/yyvth', 'https://books.scielo.org/id/yyvth/pdf/santana-9788579831164.pdf', NULL, 'https://books.scielo.org/id/yyvth/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yz7gc', 'yz7gc', 'O Conselho Geral de Província: espaço de experiência política na Bahia (1828-1834)', NULL, '["Nora de Cassia Gomes de Oliveira"]', 'EDUNEB', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro que o leitor tem em mãos é resultado da pesquisa de doutorado desenvolvida junto ao Programa de Pós-Graduação em História da Universidade Federal Fluminense (UFF). O estudo analisou a importância do Conselho Geral da Província da Bahia (CGP) como lócus de aprendizado do exercício político da elite baiana, no processo de construção e organização do Estado recém-independente, durante o período de 1828 a 1834.', '["political experience","elite education","political elites","state building","Bahia"]', '10.7476/9786588211557', '9786588211458', 'https://books.scielo.org/id/yz7gc', 'https://books.scielo.org/id/yz7gc/pdf/oliveira-9786588211557.pdf', 'https://books.scielo.org/id/yz7gc/epub/oliveira-9786588211557.epub', 'https://books.scielo.org/id/yz7gc/cover/cover_thumbnail.jpeg', 340, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yzch2', 'yzch2', 'Práticas de ensino e tecnologias digitais', NULL, '["Aranha, Simone Dália de Gusmão","Souza, Fábio Marques de"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro Práticas de ensino e tecnologias digitais reitera o compromisso de se fazer da docência um campo de reflexão científica e ressignificar o magistério, no âmbito superior ou na educação básica, a partir de metodologias ou de propostas de ensino diferenciadas. Nesse processo, ao lado de experiências de ensino relevantes no contexto da formação de professores, cumpre assinalar o diferencial deste volume: a inserção das tecnologias digitais como contraponto às práticas tradicionais de ensino e de formação docente e, consequentemente, como espaço que se sobressai no desenvolvimento de competências básicas (falar, ouvir, ler e escrever, não só em língua materna como também em língua estrangeira/adicional), a partir de textualizações próprias ao espaço digital a da valorização do protagonismo dos alunos.', '["teaching practice","digital technologies in education","teacher professional development","differentiated instruction","digital skills","basic competencies","student agency","digital text production","university teaching"]', '10.7476/9786586221657', '9786586221657', 'https://books.scielo.org/id/yzch2', 'https://books.scielo.org/id/yzch2/pdf/aranha-9786586221657.pdf', NULL, 'https://books.scielo.org/id/yzch2/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yzqzz', 'yzqzz', 'Catálogo Transfopress Brasil: imprensa estrangeira publicada no Brasil', NULL, '["Stephanou, Maria","Luca, Tania Regina de","Guimarães, Valéria dos Santos"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O Catálogo Transfopress Brasil – imprensa estrangeira publicada no Brasil é um instrumento de pesquisa com uma extensa listagem de impressos periódicos alófonos que constam em acervos nacionais e estrangeiros. Os pesquisadores contarão com informações sistematizadas, organizadas por idioma, como títulos, locais e anos de publicação, além da referência da localização em acervos físicos e digitais, com detalhes acerca dos volumes disponíveis (quando possível). O cruzamento de dados entre local de publicação e idioma é particularmente importante, visto que a maioria dos catálogos não possui essas informações ou não lhes dão destaque. E é justamente o cruzamento destas duas entradas que confere interesse para o pesquisador da área. O Catálogo ainda oferece breves textos explicativos sobre a história dos grupos imigrantes que deram origem a estes impressos e observações gerais ou específicas acerca do corpus arrolado. Os jornais, revistas, almanaques e boletins aqui repertoriados são aqueles que sobreviveram e estão disponíveis para a consulta. Alguns passaram incólumes (ou quase) desde o século XIX, século da consolidação das nações quando a imprensa comercial atuou como um fator de integração de um mundo cujas referências iam se tornando cada vez mais compartilhadas, resultado da modernização tecnológica dos meios de transporte e de comunicação, fenômeno de proporções sem precedentes na história da humanidade.', '["foreign-language press","periodicals","immigrant press","immigrant communities","immigration history","commercial press","almanacs","newspapers","newspaper history"]', '10.7476/9786559543632', '9786559543632', 'https://books.scielo.org/id/yzqzz', 'https://books.scielo.org/id/yzqzz/pdf/rodrigues-9786559543632.pdf', NULL, 'https://books.scielo.org/id/yzqzz/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-yzs9w', 'yzs9w', 'O atendimento socioassistencial para crianças e adolescentes: perspectivas contemporâneas', NULL, '["Sílvio José Benelli"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'fonte O ATENDIMENTO SOCIOASSISTENCIAL PARA CRIANÇAS E ADOLESCENTES 17desde a perspectiva de uma Psicologia Social crítica, procuramos apreender as contradições que atravessam essas instâncias de controle social das políticas públicas.O Capítulo 4 analisa os planos de trabalho de duas entidades assistenciais públicas e duas privadas.Optamos por apresentar de modo detalhado e exaustivo tais planos, por causa de sua riqueza analítica e por parecerem eloquentes por si mesmos.Não é comum encontrar tais detalhes sobre os planos de trabalho institucionais das entidades assistenciais, e torná-los disponíveis é uma das contribuições e singularidades desta investigação.A compilação, apresentação e análise desses planos de trabalho podem permitir entender qual seria o estado da arte da socioeducação para crianças e adolescentes na atualidade.O Capítulo 5 apresenta os relatos da observação participante e análises sobre os pressupostos teórico-técnicos, pedagógicos, psicológicos, políticos e éticos que fundamentariam os projetos socioeducativos elaborados pelos estabelecimentos assistenciais públicos e privados.O Capítulo 6 problematiza o tema das redes sociais, procurando explicitar a conexão que pensamos haver entre uma estratégia de captura e de gestão dos riscos sociais.Para tanto, analisamos o processo de naturalização do discurso neoliberal na área da Assistência Social detectado ao revisar a literatura impressa e a disponível na internet, relativas ao tema das redes sociais e da gestão empresarial das organizações da sociedade civil.Compreendemos que discursos inovadores podem se reduzir apenas a uma retórica vazia que pretende difundir a ideia de transformação justamente para manter tudo como está.Uma rede não só se presta a apoiar, intensificar e conectar de modo produtivo, mas também pode ser utilizada para capturar, conter e gerenciar os coletivos sociais.Pensamos que a dimensão política, enquanto participação coletiva, autogestiva e autoanalítica, é essencial quando se busca equacionar os problemas sociais de modo não funcionalista.As conclusões problematizam a Assistência Social como instituição social, definindo o modo de ação das entidades assistenciais 18 SILVIO JOSÉ BENELLI na atualidade e indicando algumas formas de encaminhar os impasses detectados.Finalmente, vêm as referências bibliográficas utilizadas na elaboração desta investigação.', '["social assistance","social networks","neoliberalism","social control","social work","social education","civil society organizations","work plan","social risk management","social participation","social work ethics","social work pedagogy"]', '10.7476/9788568334751', '9788568334751', 'https://books.scielo.org/id/yzs9w', 'https://books.scielo.org/id/yzs9w/pdf/benelli-9788568334751.pdf', NULL, 'https://books.scielo.org/id/yzs9w/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-z2nw3', 'z2nw3', 'Os olhos negros do Brasil', NULL, '["Ordep José Trindade Serra"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Dividido em duas partes, o livro elenca laudos antropológicos elaborados pelo autor, tendo em vista a preservação de terreiros de candomblé de Salvador e pequenos ensaios. Os olhos negros do Brasil traça o seu caminho perpassando desde a questão preliminar sobre o rótulo de “afro-brasileiros” até o racismo, intolerância e violência que oprimem os terreiros baianos. Portanto, o livro representa e preserva a cultura negra a partir de vieses repletos de unidade.', '["Candomblé terreiros","Afro-Brazilian culture","Afro-Brazilian identity","racism","intolerance","Salvador, Bahia","cultural preservation"]', '10.7476/9786556303994', '9788523212490', 'https://books.scielo.org/id/z2nw3', NULL, NULL, 'https://books.scielo.org/id/z2nw3/cover/cover_thumbnail.jpeg', 381, 16, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-z3', 'z3', 'À beira da linha: formações urbanas da Noroeste Paulista', NULL, '["Nilson Ghirardello"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2002, '2002-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Enfoca a formação das cidades paulistas criadas junto à antiga Companhia Estrada de Ferro Noroeste do Brasil - atual Novoeste, do início da construção da ferrovia, em 1905, até 1914, data que marca o término da ligação entre Bauru (SP) e Porto Esperança, no atual Mato Grosso do Sul. Nesse período, surgem, a partir das estações, povoados que apresentam certas constantes urbanísticas. Cidades como Lins, Penápolis e Araçatuba merecem análise detalhada. O autor verifica que nelas predominou, desde a sua origem, a lógica da especulação imobiliária e do lucro como base para a vida urbana.', '["urban formation","railroad towns","railway stations","real estate speculation","urban development","Lin","Araçatuba","Bauru","early 20th century"]', '10.7476/9788539302420', '9788539302420', 'https://books.scielo.org/id/z3', 'https://books.scielo.org/id/z3/pdf/ghirardello-9788539302420.pdf', NULL, 'https://books.scielo.org/id/z3/cover/cover_thumbnail.jpeg', NULL, 24, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-z3529', 'z3529', 'Catálogo de plantas e fungos do Brasil - Vol. 1', NULL, '["Rafaela Campostrini Forzza","Paula Moraes Leitman","Andréa Ferreira da Costa","Aníbal Alves de Carvalho Júnior","Ariane Luna Peixoto","Bruno Machado Teles Walter","Carlos Eduardo de Mattos Bicudo","DANIELA CRISTINA ZAPPI","Denise Pinheiro da Costa","Eduardo Lleras","Gustavo Martinelli","Haroldo Cavalcante de Lima","Jefferson Prado","João Renato Stehmann","José Fernando A. Baumgratz","José Rubens Pirani","Lana da Silva Sylvestre","Leonor Costa Maia","Lúcia G. Lohmann","Luciano Paganucci","Marcos Silveira","Marcus Nadruz","Maria Cândida Henrique Mamede","Maria Nazaré C. Bastos","Marli Pires Morim"]', 'Instituto de Pesquisa Jardim Botânico do Rio de Janeiro', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'es', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', '"Parabenizo a todos os botânicos que contribuíram para completar o presente catálogo. O Brasil é o país que provavelmente possui a maior flora do mundo, portanto, a produção de uma lista completa dessa flora é uma extensa tarefa. Os coordenadores mobilizaram uma grande equipe de pessoas para compilar a lista, e é ótimo ver que este projeto, diferentemente do que se observa em outros países, foi coordenado no Brasil. Isto demonstra o alto nível e a capacidade da comunidade botânica brasileira que se desenvolveu rapidamente nas últimas décadas. Este catálogo, por ter sido preparado na sua maioria por especialistas dos grupos estudados, mostra quais espécies são correntemente aceitas pelos botânicos envolvidos. As espécies foram padronizadas por meio da citação de materiais-voucher, a maioria dos quais foi coletada por brasileiros e está alojada em herbários do Brasil. A informação a respeito da distribuição geográfica de cada espécie será extremamente útil para fins de conservação, e é interessante notar o número expressivo de espécies endêmicas do Brasil. Este catálogo certamente será utilizado por estudantes de diversas áreas envolvendo botânica, ecologia e outras, e tenho certeza de que a sua existência estimulará futuras pesquisas a respeito de plantas brasileiras e que a sua versão online o manterá atualizado. O desafio agora é conservar os muitos ecossistemas diferentes nos quais estas espécies ocorrem, para manter a diversidade botânica do país." (trecho retirado do Prefácio do livro)', '["Brazilian flora","plant species checklist","fungi","species distribution","endemic species","voucher specimens","herbarium collections","plant diversity"]', '10.7476/9788560035083', '9788560035083', 'https://books.scielo.org/id/z3529', 'https://books.scielo.org/id/z3529/pdf/forzza-9788560035083.pdf', NULL, 'https://books.scielo.org/id/z3529/cover/cover_thumbnail.jpeg', NULL, 190, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-z439n', 'z439n', 'Urbanização e mudança social no Brasil', NULL, '["Rubén George Oliven"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro é uma versão modificada de minha tese de doutorado Urbanization and Social Change in Brazil: case study of Porto Alegre defendida na Universidade de Londres (London School of Economics and Political Science) em 1977.', '["urbanization","social change","Porto Alegre","Brazilian cities","urban sociology"]', '10.7476/9788579820014', '9788579820014', 'https://books.scielo.org/id/z439n', 'https://books.scielo.org/id/z439n/pdf/oliven-9788579820014.pdf', NULL, 'https://books.scielo.org/id/z439n/cover/cover_thumbnail.jpeg', NULL, 26, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-z4rtk', 'z4rtk', 'Manchas Metafóricas: o Eu de Augusto dos Anjos em imagens produzidas pela crítica literária', NULL, '["Stefani Daiana Kreutz"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta obra apresenta, por meio do panorama da crítica, a investigação das condições de produção do discurso de dezoito textos de crítica literária de catorze diferentes autores, produzidos entre as décadas de 1910 e 1990. A fim de confrontar discursos diversos da crítica literária sobre a produção de Augusto dos Anjos e identificar as várias leituras e abordagens que se fizeram de sua obra em diferentes contextos, tendo como base algumas metáforas enunciadas por críticos, a autora mapeou metáforas e analisou possíveis relações dialógicas que elas estabelecem no discurso. “Manchas Metafóricas: O Eu de Augusto dos Anjos em imagens produzidas pela crítica literária” fundamenta-se em Bakhtin e em pesquisadores como José Luiz Fiorin, Diana Luz Pessoa de Barros e Beth Brait. As concepções de crítica literária são as de Adolfo Casais Monteiro, Antonio Candido, João Cezar de Castro Rocha, Flora Süssekind, entre outros estudiosos do assunto. Trata-se, portanto, de um livro para os estudiosos e interessados na área de Letras. Outros leitores ou analistas podem identificar diferentes metáforas e construir diferentes imagens; afinal, as metáforas selecionadas são próprias de gesto de leitura da autora, a partir de ideias que lhe chamaram a atenção.', '["Augusto dos Anjos","literary criticism","self","Bakhtin","dialogism","Antonio Candido","literary reception","Brazilian modernist poetry"]', '10.7476/9786550190460', '9786550190460', 'https://books.scielo.org/id/z4rtk', 'https://books.scielo.org/id/z4rtk/pdf/kreutz-9786550190460.pdf', NULL, 'https://books.scielo.org/id/z4rtk/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-z4wym', 'z4wym', 'A redação no Vestibular Unicamp: o que e como se avalia', NULL, '["Márcia Mendonça","Cynthia Agra de Brito Neves"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O que é avaliado em uma prova de redação? E como os textos são avaliados? Este livro traz respostas a essas questões. Para tanto, apresenta os critérios usados para avaliar as redações dos candidatos ao Vestibular da Unicamp, informação nunca antes divulgada. Buscando a transparência, a Comissão Permanente para os Vestibulares da Unicamp (Comvest) decidiu torná-la pública. A grade de avaliação integra as dimensões da leitura e da escrita, um dos destaques do Vestibular Unicamp em todas as disciplinas, não só na redação. Ela permite analisar os textos de forma criteriosa e consistente, a fim de encontrar, entre os candidatos, aqueles que melhor atendam ao perfil esperado: o de sujeitos com capacidades de leitura crítica e de escrita consolidadas. A publicação traz ainda as mudanças nas provas de redação do Vestibular Unicamp nos últimos 30 anos e um apanhado das recentes ações implementadas pela Comvest em relação às políticas de acesso e inclusão na Unicamp.', '["essay scoring","evaluation criteria","reading and writing skills","critical reading","writing assessment","university admission policy","access and inclusion"]', '10.7476/9786586253917', '9788526814929', 'https://books.scielo.org/id/z4wym', NULL, NULL, 'https://books.scielo.org/id/z4wym/cover/cover_thumbnail.jpeg', 184, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-z5pb7', 'z5pb7', 'Nostálgicos na terra do banzo: o imigrante italiano em Juó Bananére e António de Alcântara Machado', NULL, '["Francisco Cláudio Alves Marques"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Neste livro, Francisco Cláudio Alves Marques examina a participação do imigrante italiano no processo de urbanização paulista nos anos de 1920, no qual se misturavam trabalhadores de procedências diversas, como o escravo recém-liberto, o caipira e o imigrante italiano vindo da zona rural, todos “desenraizados” no espaço ou no tempo. É dessa perspectiva que o autor procura compreender as caricaturas elaboradas por Juó Bananére e António de Alcântara Machado, considerando-as mais do que manifestação de rejeição ou acolhimento do imigrante, mas expressão do papel desse contingente nas transformações por que passava o País no período em que se discutia a configuração da identidade nacional. Para lançar luz sobre a representação do imigrante italiano nas obras daqueles dois escritores paulistas, a autor considera aspectos históricos, sociológicos e culturais implicados no processo imigratório do início do século XX. Partindo da caracterização da personagem macarrônica, nos planos gráfico e linguístico, o autor chega a possíveis sentidos do efeito cômico dessa caricatura na percepção do papel do imigrante italiano na constituição da sociedade brasileira, aspecto que enseja sutil contraste com o nacionalismo na obra de Alcântara Machado.', '["Italian immigrants","caricature","representation of immigrants","national identity","nationalism","comic effect"]', '10.7476/9786557140079', '9786557140079', 'https://books.scielo.org/id/z5pb7', 'https://books.scielo.org/id/z5pb7/pdf/marques-9786557140079.pdf', NULL, 'https://books.scielo.org/id/z5pb7/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-z7hc7', 'z7hc7', 'O negro no mundo dos ricos: um estudo sobre a disparidade racial de riqueza com os dados do Censo 2010', NULL, '["Rocha, Emerson Ferreira"]', 'Editora UnB', 'Brasil', 'SciELO Books', 'books', 2019, NULL, 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', NULL, 'O negro no mundo dos ricos é produto de pesquisa de doutorado realizada na Universidade de Brasília, com apoio do CNPq, e na University of Illinois at Urbana Champaign, com apoio da Capes. O livro utiliza os dados do último Censo Demográfico brasileiro para identificar padrões na desigualdade de renda entre negros e brancos no Brasil, dando ênfase ao grupo dos 1% mais ricos da população. Com isso, o trabalho pretende lançar novas luzes sobre o estudo da desigualdade racial de renda no Brasil, que tem dado enfoque a diferenças na média dos rendimentos ou na composição racial das faixas mais pobres da população. A intenção das análises é identificar, a partir de uma série de exercícios estatísticos, o papel desempenhado, de um lado, por processos de discriminação racial e, do outro, pelas desigualdades educacionais entre negros e brancos, inclusive em termos de área de formação superior, na determinação das desigualdades observadas na composição do grupo dos ricos. Destacando as interações entre condição racial e condição de gênero, o livro traz também um diagnóstico sobre as situações enfrentadas, especificamente, pelas mulheres negras.', '[]', '10.7476/9786558460527', '9788523009922', 'https://books.scielo.org/id/z7hc7', 'https://books.scielo.org/id/z7hc7/pdf/rocha-9786558460527.pdf', 'https://books.scielo.org/id/z7hc7/epub/rocha-9786558460527.epub', 'https://books.scielo.org/id/z7hc7/cover/cover_thumbnail.jpeg', 218, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-z7jnq', 'z7jnq', 'Pesquisas linguísticas pautadas em corpora', NULL, '["Daniel Soares da Costa"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Primeiras palavrasDiversas pesquisas sociolinguísticas, abordando diferentes níveis da língua (fonológico, sintático, morfológico, lexical, semântico e pragmático), foram e têm sido realizadas no Brasil ao longo, sobretudo, dos últimos trinta anos.Focando seu olhar ora na variedade brasileira, ora na lusitana, ou ainda, em ambas, por meio de estudos comparativos, essas pesquisas têm mostrado que embora haja vários pontos de divergência entre o Português do Brasil (PB) e o Português de Portugal (PP), as semelhanças são muitas.Coadunando-nos com a noção de que a língua varia e pode mudar ao longo do tempo, visto que sua realidade é dinâmica e multifacetada, em constante "fazimento", tal como propunha Coseriu (1979), neste capítulo serão apresentados parte dos resultados a que cheguei com a realização de minha tese de doutorado (cf.Marine, 2009), parcialmente embasada, cabe destacar, pelos pressupostos teórico-metodológicos do modelo laboviano da Variação e Mudança Linguísticas (Weinreich, Labov, Herzog, 2006; Labov, 1972; 1994; 2002).pronomes demonstrativos se mostra bastante produtivo há tempos em nossa língua, característica que, provavelmente, herdamos do Latim. Referências bibliográficas', '["Brazilian Portuguese","sociolinguistic variation","language change","demonstrative pronouns","Latin influence"]', '10.7476/9788568334416', '9788568334416', 'https://books.scielo.org/id/z7jnq', 'https://books.scielo.org/id/z7jnq/pdf/costa-9788568334416.pdf', NULL, 'https://books.scielo.org/id/z7jnq/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-z7jnr', 'z7jnr', 'Uma esquerda para o capital', 'o transformismo dos grupos dirigentes do PT (1979-1998)', '["Eurelino Teixeira Coelho Neto"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O que aconteceu com o PT? Como foi que ficaram para trás o programa e os métodos políticos daqueles militantes que haviam renovado a cena política brasileira na década de 1980? Como foi que o PT se tornou um ‘‘partido da ordem?’’. Este livro enfrenta estas questões em perspectiva histórica. Eurelino Coelho recorre a fontes ainda inexploradas desde a sua origem até 1998. O autor detecta e analisa as mudanças capilares que terminaram por configurar o novo projeto político dos petistas e, com isso, permite compreender o sentido geral do movimento que os transformou na ala esquerda do‘‘partido orgânico do capital’’. A mudança de projeto é pensada como expressão de uma transformação muito mais profunda, incidente sobre a práxis dos sujeitos e sua relação com a luta de classes. É a face mais visível da mudança que afetou os próprios sujeitos: o transformismo. As sólidas evidências documentais apresentadas na obra comprovam que essa reviravolta ocorreu muito antes da eleição de Lula à presidência, em 2002.', '["Partido dos Trabalhadores (PT)","political transition","class struggle","political subjectivity","Brazilian left","Luiz Inácio Lula da Silva"]', '10.7476/9788555921186', '9786589524496', 'https://books.scielo.org/id/z7jnr', NULL, NULL, 'https://books.scielo.org/id/z7jnr/cover/cover_thumbnail.jpeg', 482, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-z7jxb', 'z7jxb', 'Promoção da saúde: a construção social de um conceito em perspectiva comparada', NULL, '["Lucíola Santos Rabello"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A crescente necessidade de mudanças profundas na abordagem da saúde e nas práticas de atenção tem gerado intenso debate internacional, convergindo para a proposição de um novo paradigma. Este é baseado na promoção da saúde, a qual defende uma evolução substantiva no modo como são formuladas e implementadas as políticas públicas, sociais e econômicas que influenciam diretamente as condições de saúde da população. Neste livro, a autora reconstitui com maestria a história social da tessitura do conceito e das práticas de promoção da saúde como crítica ao entendimento prioritariamente biomédico da saúde. Analisa como Brasil e Canadá incorporaram em suas políticas públicas a proposta de promoção da saúde ratificada pela Declaração de Otawa, em 1986, assim como também os componentes conceituais da proposta, teoricamente e em suas apropriações pelos dois países. No caso do Brasil, a análise centrou-se na proposta do SUS, e no do Canadá examinaram-se os diversos documentos originários da proposta e de sua evolução. Disso emergem e são abordadas as discussões sobre a medicina como instituição social, a crise do Estado, o Estado neoliberal e a cooperação técnica internacional em saúde. Obra que, por seu conteúdo, provoca instigantes questões, aqui tratadas primorosamente por Lucíola.', '["health promotion","social construction of concepts","Ottawa Charter","Unified Health System (SUS)","Canadian health policy","biomedical model","crisis of the state","neoliberal state","social determinants of health","Brazil"]', '10.7476/9788575413524', '9788575413524', 'https://books.scielo.org/id/z7jxb', 'https://books.scielo.org/id/z7jxb/pdf/rabello-9788575413524.pdf', NULL, 'https://books.scielo.org/id/z7jxb/cover/cover_thumbnail.jpeg', NULL, 12, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-z7k3v', 'z7k3v', 'Planejamento e gestão em saúde: conceitos, história e propostas', NULL, '["Francisco Javier Uribe Rivera","Elizabeth Artmann"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Como utilizar recursos finitos e, muitas vezes, escassos? De que modo redistribuir os bens e aumentar o acesso a eles? Essas escolhas e decisões fazem parte do dia a dia dos gestores e profissionais da saúde. E é a eles – assim como aos pesquisadores, estudantes e todos aqueles que se preocupam com os rumos da saúde do país – que se dirige este livro. Os autores contam a evolução histórica do planejamento em saúde na América Latina e no Brasil. Colocam lado a lado os temas clássicos e os dilemas contemporâneos, que exigem releituras e respostas atualizadas. Discutem um novo paradigma, baseado em Habermas, que tem sido denominado comunicativo ou intersubjetivo. Também apresentam duas propostas teórico-metodológicas para o Sistema Único de Saúde (SUS) e oferecem roteiros para que elas possam ser utilizadas em oficinas de trabalho. Assim, ao abordarem e dialogarem com diferentes enfoques sobre o planejamento em saúde, os autores revelam que não existe somente um caminho correto. Convidam o leitor “ao exercício de escuta e de avaliação dos problemas de saúde de forma ampla, compreendendo sua permeabilidade à técnica e aos valores, às ideologias, à história, à política e à cultura”.', '["health planning","health management","Latin America","Brazil","communicative paradigm","Jürgen Habermas","intersubjectivity","Unified Health System (SUS)","healthcare resource allocation","health care access","health policy","participatory workshops"]', '10.7476/9788575415795', '9788575414163', 'https://books.scielo.org/id/z7k3v', NULL, NULL, 'https://books.scielo.org/id/z7k3v/cover/cover_thumbnail.jpeg', 162, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-z7xc5', 'z7xc5', 'Diálogos curriculares entre Brasil e México', NULL, '["Alice Casimiro Lopes","Alícia De Alba"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Enquanto no Brasil o sentido do currículo é intrinsecamente associado à discussão sobre a educação básica, no México o pensamento curricular demonstra-se vinculado ao ensino superior. Diferenças como essa são apresentadas neste livro por professores de ambos os países, em um debate que ultrapassa fronteiras. Os ensaios abordam temas como a organização curricular, a cultura escolar, a avaliação, a formação dos professores, a pesquisa e a pós-graduação, entre outros.', '["course program","curriculum organization","school culture","educational assessment","teacher professional development","higher education","basic education","graduate education","comparative education"]', '10.7476/9788575114704', '9788575113332', 'https://books.scielo.org/id/z7xc5', NULL, NULL, 'https://books.scielo.org/id/z7xc5/cover/cover_thumbnail.jpeg', 340, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
